  parameter CLP_DEBUG_MODE_KV_0 = 32'hAAAA_AAAA;
  parameter CLP_DEBUG_MODE_KV_1 = 32'h5555_5555;
module caliptra_sram #(
     parameter DEPTH      = 64
    ,parameter DATA_WIDTH = 32
    ,parameter ADDR_WIDTH = $clog2(DEPTH)
    )
    (
    input  logic                       clk_i,
    input  logic                       cs_i,
    input  logic                       we_i,
    input  logic [ADDR_WIDTH-1:0]      addr_i,
    input  logic [DATA_WIDTH-1:0]      wdata_i,
    output logic [DATA_WIDTH-1:0]      rdata_o
    );
    localparam NUM_BYTES = DATA_WIDTH/8 + ((DATA_WIDTH % 8) ? 1 : 0);
    logic [7:0] ram [DEPTH][NUM_BYTES-1:0];
    initial rdata_o = '{default:0};
    always @(posedge clk_i) begin
        if (cs_i & we_i) begin
            for (int i = 0; i < NUM_BYTES; i++) begin
                ram[addr_i][i] <= wdata_i[i*8 +: 8];
            end
        end
        if (cs_i & ~we_i) begin
            for (int i = 0; i < NUM_BYTES; i++) begin
                rdata_o[i*8 +: 8] <= ram[addr_i][i];
            end
        end
    end
endmodule
package ahb_defines_pkg;
parameter H_OKAY=1'b0;
parameter H_ERROR=1'b1;
endpackage
module caliptra_ahb_srom 
 import ahb_defines_pkg::*;
 #(
    parameter AHB_DATA_WIDTH    = 64,
    parameter AHB_ADDR_WIDTH    = 32,
    parameter CLIENT_ADDR_WIDTH = 32
)(
    input logic                       hclk,
    input logic                       hreset_n,
    input logic [AHB_ADDR_WIDTH-1:0]  haddr_i,
    input logic [AHB_DATA_WIDTH-1:0]  hwdata_i,
    input logic                       hsel_i,
    input logic                       hwrite_i,
    input logic                       hready_i,
    input logic [1:0]                 htrans_i,
    input logic [2:0]                 hsize_i,
    output logic                      hresp_o,
    output logic                      hreadyout_o,
    output logic [AHB_DATA_WIDTH-1:0] hrdata_o,
    output logic cs,
    output logic [CLIENT_ADDR_WIDTH-1:0] addr,
    input logic [AHB_DATA_WIDTH-1:0] rdata
);
logic                       sram_error, sram_error_data_ph, sram_error_data_ph_f;
assign cs = hready_i & hsel_i & htrans_i inside {2'b10, 2'b11};
assign addr = haddr_i >> $clog2(AHB_DATA_WIDTH/8);
assign sram_error = cs & hwrite_i;  
assign hrdata_o = rdata;
always_comb begin : response_block
    hreadyout_o = 1'b1;
    hresp_o = H_OKAY;
    if (sram_error_data_ph & ~sram_error_data_ph_f) begin
        hreadyout_o = 1'b0;
        hresp_o = H_ERROR;
    end else if (sram_error_data_ph_f) begin
        hreadyout_o = 1'b1;
        hresp_o = H_ERROR;
    end
end
always_ff @(posedge hclk or negedge hreset_n) begin
    if (~hreset_n) begin
        sram_error_data_ph <= '0;
        sram_error_data_ph_f <= '0;
    end else begin
        sram_error_data_ph <= sram_error;
        sram_error_data_ph_f <= sram_error_data_ph;
    end
end
endmodule
module ahb_slv_sif 
  import ahb_defines_pkg::*; 
  #(
    parameter AHB_DATA_WIDTH = 64
   ,parameter CLIENT_DATA_WIDTH = 32
   ,parameter AHB_ADDR_WIDTH = 32
   ,parameter CLIENT_ADDR_WIDTH = AHB_ADDR_WIDTH
   )
   (
    input logic hclk,
    input logic hreset_n,
    input logic [AHB_ADDR_WIDTH-1:0] haddr_i,
    input logic [AHB_DATA_WIDTH-1:0] hwdata_i,
    input logic hsel_i,
    input logic hwrite_i,
    input logic hready_i,
    input logic [1:0] htrans_i,
    input logic [2:0] hsize_i,
    output logic hresp_o,
    output logic hreadyout_o,
    output logic [AHB_DATA_WIDTH-1:0] hrdata_o,
    output logic                         dv,
    input  logic                         hld,
    input  logic                         err,
    output logic                         write,
    output logic [CLIENT_DATA_WIDTH-1:0] wdata,
    output logic [CLIENT_ADDR_WIDTH-1:0] addr,
    input  logic [CLIENT_DATA_WIDTH-1:0] rdata
   );
logic err_f;
logic [2:0] size;
localparam BITS_WDATA = $bits(wdata);
generate 
    if ((AHB_DATA_WIDTH == 32) & (CLIENT_DATA_WIDTH == 32)) begin
        always_comb begin
            unique case (size) inside
                3'b000:   
                    wdata = {{BITS_WDATA-8{1'b0}},hwdata_i[7:0]};
                3'b001:   
                    wdata = {{BITS_WDATA-16{1'b0}},hwdata_i[15:0]};
                3'b010:   
                    wdata = hwdata_i[31:0];
                default:  
                wdata = hwdata_i[31:0];
            endcase
        end
        always_comb hrdata_o = rdata;
    end else if ((AHB_DATA_WIDTH == 64) & (CLIENT_DATA_WIDTH == 32)) begin
        always_comb begin
            unique case (size) inside
                3'b000:   
                    wdata = addr[2] ? {{BITS_WDATA-8{1'b0}},hwdata_i[39:32]} : {{BITS_WDATA-8{1'b0}},hwdata_i[7:0]};
                3'b001:   
                    wdata = addr[2] ? {{BITS_WDATA-16{1'b0}},hwdata_i[47:32]} : {{BITS_WDATA-16{1'b0}},hwdata_i[15:0]};
                3'b010:   
                    wdata = addr[2] ? hwdata_i[63:32] : hwdata_i[31:0];
                default:  
                wdata = addr[2] ? hwdata_i[63:32] : hwdata_i[31:0];
            endcase
        end
        always_comb hrdata_o = addr[2] ? {rdata, 32'b0} : {32'b0, rdata};
    end else if ((AHB_DATA_WIDTH == 64) & (CLIENT_DATA_WIDTH == 64)) begin
        always_comb begin
            unique case (size) inside
                3'b000:   
                    wdata = {{BITS_WDATA-8{1'b0}},hwdata_i[7:0]};
                3'b001:   
                    wdata = {{BITS_WDATA-16{1'b0}},hwdata_i[15:0]};
                3'b010:   
                    wdata = addr[2]? hwdata_i[63:32] : hwdata_i[31:0];
                3'b011:  
                    wdata = hwdata_i;
                default:  
                    wdata = hwdata_i;
            endcase
        end
        always_comb hrdata_o = rdata;
    end 
endgenerate
    always_ff @(posedge hclk or negedge hreset_n) begin
        if(!hreset_n) begin
            dv <= 1'b0;
            write <= 1'b0;
            addr <= '0;
            err_f <= '0;
            size <= '0;
        end
        else begin
            err_f <= err;
            if (hready_i) begin
                dv <= hsel_i & htrans_i inside {2'b10, 2'b11};
            end
            else if (dv && !hld) begin
                dv <= 1'b0;
            end
            if(hready_i & hsel_i) begin
                addr <= haddr_i[CLIENT_ADDR_WIDTH-1:0];
                write <= hwrite_i & |htrans_i;
                size <= hsize_i;
            end
        end
    end
always_comb begin : response_block
    hreadyout_o = 1'b1;
    hresp_o = H_OKAY;
    if (err & ~err_f) begin
        hreadyout_o = 1'b0;
        hresp_o = H_ERROR;
    end else if (dv & hld) begin
        hreadyout_o = 1'b0;
        hresp_o = H_OKAY;
    end else if (err_f) begin
        hreadyout_o = 1'b1;
        hresp_o = H_ERROR;
    end
end
endmodule
    module cptra_clk_gate (
        input logic clk,
        input logic en,
        output clk_cg
    );
        logic en_lat;
        always_latch begin
            if(!clk) begin
                en_lat = en;
            end
        end
        assign clk_cg = clk && en_lat;
    endmodule
module clk_gate (
    input logic clk,
    input logic cptra_rst_b,
    input logic psel,
    input logic clk_gate_en,
    input logic rdc_clk_dis,
    input logic rdc_clk_dis_uc,
    input logic cpu_halt_status,
    input logic [63:0] generic_input_wires,
    input logic cptra_error_fatal,
    input logic cptra_in_debug_scan_mode,
    output logic clk_cg,
    output logic soc_ifc_clk_cg,
    output logic rdc_clk_cg,
    output logic uc_clk_cg,
    input  logic cptra_dmi_reg_en_preQ  
);
logic disable_clk;
logic disable_soc_ifc_clk;
logic disable_uc_clk;
logic [63:0] generic_input_wires_f;
logic change_in_generic_wires;
logic sleep_condition;
always_ff@(posedge clk or negedge cptra_rst_b) begin
    if(!cptra_rst_b) begin
        generic_input_wires_f <= 'h0;
    end
    else begin 
        generic_input_wires_f <= generic_input_wires;
    end
end
always_comb begin
    change_in_generic_wires = ((generic_input_wires ^ generic_input_wires_f) != 'h0);
    sleep_condition         = (cpu_halt_status && !change_in_generic_wires && !cptra_error_fatal && !cptra_in_debug_scan_mode && !cptra_dmi_reg_en_preQ);
    disable_clk             = (clk_gate_en && sleep_condition) | rdc_clk_dis;
    disable_soc_ifc_clk     = (clk_gate_en && (sleep_condition && !psel)) | rdc_clk_dis;
    disable_uc_clk          = (rdc_clk_dis | rdc_clk_dis_uc);
end
    cptra_clk_gate caliptra_icg (.clk(clk), .en(!disable_clk), .clk_cg(clk_cg));
    cptra_clk_gate caliptra_soc_ifc_icg (.clk(clk), .en(!disable_soc_ifc_clk), .clk_cg(soc_ifc_clk_cg));
    cptra_clk_gate caliptra_rdc_icg (.clk(clk), .en(!rdc_clk_dis), .clk_cg(rdc_clk_cg));
    cptra_clk_gate caliptra_rdc_uc_icg (.clk(clk), .en(!disable_uc_clk), .clk_cg(uc_clk_cg));
endmodule
module caliptra_2ff_sync  #( parameter WIDTH=1,
                             parameter RST_VAL=0)
    (
    input logic clk,
    input logic rst_b,
    input logic [WIDTH-1:0] din,
    output logic [WIDTH-1:0] dout
);
logic din_ff;
always_ff@(posedge clk or negedge rst_b) begin
    if(!rst_b) begin
        dout <= RST_VAL;
        din_ff <= RST_VAL;
    end
    else begin 
        din_ff <= din;
        dout <= din_ff;
    end
end
endmodule
module ahb_to_reg_adapter#(
    parameter DATA_WIDTH = 32,
    parameter DATA_BYTE_WIDTH = DATA_WIDTH / 8,
    parameter ADDR_WIDTH = 32
  ) (
    input  logic                       clk,
    input  logic                       rst_n,
    input  logic                       ahb_reg_dv,
    output logic                       ahb_reg_hld,
    output logic                       ahb_reg_err,
    input  logic                       ahb_reg_write,
    input  logic [DATA_WIDTH-1:0]      ahb_reg_wdata,
    input  logic [ADDR_WIDTH-1:0]      ahb_reg_addr,
    output logic [DATA_WIDTH-1:0]      ahb_reg_rdata,
    output logic                       reg_we,
    output logic                       reg_re,
    output logic [ADDR_WIDTH-1:0]      reg_addr,
    output logic [DATA_WIDTH-1:0]      reg_wdata,
    output logic [DATA_BYTE_WIDTH-1:0] reg_be,
    input  logic [DATA_WIDTH-1:0]      reg_rdata,
    input  logic                       reg_error,
    input  logic                       reg_busy
    );
  always_comb begin
    ahb_reg_rdata = reg_rdata;
    ahb_reg_err   = reg_error;
    ahb_reg_hld   = reg_busy;
    reg_addr      = ahb_reg_addr;
    reg_wdata     = ahb_reg_wdata;
    reg_we        = ahb_reg_dv && ahb_reg_write && !ahb_reg_hld;
  end
  assign reg_re = ahb_reg_dv && !ahb_reg_write;
  assign reg_be = {DATA_BYTE_WIDTH{1'b1}};
endmodule
`default_nettype none
module skidbuffer #(
                parameter       [0:0]   OPT_LOWPOWER = 0,
                parameter       [0:0]   OPT_OUTREG = 1,
                parameter       [0:0]   OPT_PASSTHROUGH = 0,
                parameter               DW = 8
        ) (
                input   wire                    i_clk, i_reset,  
                input   wire                    i_valid,
                output  wire                    o_ready,
                input   wire    [DW-1:0]        i_data,
                output  wire                    o_valid,
                input   wire                    i_ready,
                output  reg     [DW-1:0]        o_data
        );
        wire    [DW-1:0]        w_data;
        generate if (OPT_PASSTHROUGH)
        begin : PASSTHROUGH
                assign  { o_valid, o_ready } = { i_valid, i_ready };
                always @(*)
                if (!i_valid && OPT_LOWPOWER)
                        o_data = 0;
                else
                        o_data = i_data;
                assign  w_data = 0;
                /*verilator lint_off UNUSED*/ 
                wire    unused_passthrough;
                assign  unused_passthrough = &{ 1'b0, i_clk, i_reset };
                /*verilator lint_on UNUSED*/ 
        end else begin : BUF_STAGE
                reg                     r_valid;
                reg     [DW-1:0]        r_data;
                always @(posedge i_clk or negedge i_reset)
                if (!i_reset)
                        r_valid <= 0;
                else if ((i_valid && o_ready) && (o_valid && !i_ready))
                        r_valid <= 1;
                else if (i_ready)
                        r_valid <= 0;
                always @(posedge i_clk or negedge i_reset)
                if (!i_reset)
                        r_data <= 0;
                else if (OPT_LOWPOWER && (!o_valid || i_ready))
                        r_data <= 0;
                else if ((!OPT_LOWPOWER || !OPT_OUTREG || i_valid) && o_ready)
                        r_data <= i_data;
                assign  w_data = r_data;
                assign o_ready = !r_valid;
                if (!OPT_OUTREG)
                begin : NET_OUTPUT
                        assign  o_valid =  (i_valid || r_valid);
                        always @(*)
                        if (r_valid)
                                o_data = r_data;
                        else if (!OPT_LOWPOWER || i_valid)
                                o_data = i_data;
                        else
                                o_data = 0;
                end else begin : REG_OUTPUT
                        reg     ro_valid;
                        always @(posedge i_clk or negedge i_reset)
                        if (!i_reset)
                                ro_valid <= 0;
                        else if (!o_valid || i_ready)
                                ro_valid <= (i_valid || r_valid);
                        assign  o_valid = ro_valid;
                        always @(posedge i_clk or negedge i_reset)
                        if (!i_reset)
                                o_data <= 0;
                        else if (!o_valid || i_ready)
                        begin
                                if (r_valid)
                                        o_data <= r_data;
                                else if (!OPT_LOWPOWER || i_valid)
                                        o_data <= i_data;
                                else
                                        o_data <= 0;
                        end
                end
        end endgenerate
        /*verilator lint_off UNUSED*/ 
        wire    unused;
        assign  unused = &{ 1'b0, w_data };
        /*verilator lint_on UNUSED*/ 
endmodule
`default_nettype wire
package kv_defines_pkg;
parameter KV_NUM_DWORDS = 16;  
parameter KV_NUM_KEYS = 24;
parameter KV_ADDR_W = 13;
parameter KV_DATA_W = 32;
parameter KV_ENTRY_ADDR_W = $clog2(KV_NUM_KEYS);
parameter KV_ENTRY_SIZE_W = $clog2(KV_NUM_DWORDS);
parameter KV_NUM_READ=9;
parameter KV_NUM_WRITE=5;
parameter ECC_NUM_DWORDS = 12;
parameter MLDSA_NUM_DWORDS = 8;
parameter KV_ENTRY_FOR_ECC_SIGNING = 7;
parameter KV_ENTRY_FOR_MLDSA_SIGNING = 8;
parameter PCR_HASH_NUM_DWORDS = 16;
localparam KV_STANDARD_SLOT_LOW            = 0;
localparam KV_STANDARD_SLOT_HI             = 15;
localparam KV_OCP_LOCK_SLOT_LOW            = 16;
localparam KV_OCP_LOCK_SLOT_HI             = 23;
localparam OCP_LOCK_RT_OBF_KEY_KV_SLOT  = 16;  
localparam OCP_LOCK_HEK_SEED_KV_SLOT    = 22;  
localparam OCP_LOCK_KEY_RELEASE_KV_SLOT = 23;  
localparam OCP_LOCK_HEK_NUM_DWORDS      = 8;   
localparam OCP_LOCK_MEK_NUM_DWORDS      = 16;  
localparam KV_WRITE_IDX_HMAC      = 0;
localparam KV_WRITE_IDX_MLKEM     = 1;
localparam KV_WRITE_IDX_ECC       = 2;
localparam KV_WRITE_IDX_DOE       = 3;
localparam KV_WRITE_IDX_AES       = 4;
localparam KV_DEST_IDX_HMAC_KEY   = 0;
localparam KV_DEST_IDX_HMAC_BLOCK = 1;
localparam KV_DEST_IDX_MLDSA_SEED = 2;
localparam KV_DEST_IDX_ECC_PKEY   = 3;
localparam KV_DEST_IDX_ECC_SEED   = 4;
localparam KV_DEST_IDX_AES_KEY    = 5;
localparam KV_DEST_IDX_MLKEM_SEED = 6;
localparam KV_DEST_IDX_MLKEM_MSG  = 7;
localparam KV_DEST_IDX_DMA_DATA   = 8;
localparam OCP_LOCK_HEK_SEED_DEST_VALID = (1 << KV_DEST_IDX_HMAC_BLOCK);
typedef struct packed {
    logic   [KV_ADDR_W-1:0] addr;
    logic   [KV_DATA_W-1:0] wdata;
    logic                   write;
} kv_uc_req_t;
typedef struct packed {
    logic   [KV_ENTRY_ADDR_W-1:0] read_entry;
    logic   [KV_ENTRY_SIZE_W-1:0] read_offset;
} kv_read_t;
typedef struct packed {
    logic                         write_en;
    logic   [KV_ENTRY_ADDR_W-1:0] write_entry;
    logic   [KV_ENTRY_SIZE_W-1:0] write_offset;
    logic   [KV_DATA_W-1:0]       write_data;
    logic   [KV_NUM_READ-1:0]     write_dest_valid;
} kv_write_t;
typedef struct packed {
    logic          error;
} kv_wr_resp_t;
typedef struct packed {
    logic                   error;
    logic                   last;
    logic   [KV_DATA_W-1:0] read_data;
} kv_rd_resp_t;
localparam KV_READ_CTRL_RSVD_MSB = 32 - KV_ENTRY_SIZE_W - 1 - 1;
typedef struct packed {
    logic [KV_READ_CTRL_RSVD_MSB:0] rsvd;
    logic [KV_ENTRY_ADDR_W-1:0] read_entry;
    logic pcr_hash_extend;
    logic read_en;
} kv_read_ctrl_reg_t;
localparam KV_WRITE_CTRL_RSVD_MSB = 32 - KV_NUM_READ - KV_ENTRY_ADDR_W - 1;
typedef struct packed {
    logic [KV_WRITE_CTRL_RSVD_MSB:0] rsvd;
    logic [KV_NUM_READ-1:0] write_dest_vld;
    logic [KV_ENTRY_ADDR_W-1:0] write_entry;
    logic write_en;
} kv_write_ctrl_reg_t;
typedef enum logic [7:0] {
    KV_SUCCESS = 8'h00,
    KV_READ_FAIL = 8'h01,
    KV_WRITE_FAIL = 8'h02
} kv_error_code_e;
typedef struct packed {
    logic [PCR_HASH_NUM_DWORDS-1:0][31:0]   pcr_hash;
    logic [ECC_NUM_DWORDS-1:0][31:0]        pcr_ecc_signing_privkey;
    logic [MLDSA_NUM_DWORDS-1:0][31:0]      pcr_mldsa_signing_seed;
} pcr_signing_t;
typedef struct packed {
    logic                       ocp_lock_in_progress;
    logic [KV_NUM_READ-1:0]     kv_read_dest;
    logic [KV_ENTRY_ADDR_W-1:0] kv_key_entry;
} kv_read_filter_metrics_t;
typedef struct packed {
    logic                       ocp_lock_in_progress;
    logic                       kv_data0_present;
    logic [KV_ENTRY_ADDR_W-1:0] kv_data0_entry;
    logic                       kv_data1_present;
    logic [KV_ENTRY_ADDR_W-1:0] kv_data1_entry;
    logic [KV_NUM_WRITE-1:0]    kv_write_src;
    logic [KV_ENTRY_ADDR_W-1:0] kv_write_entry;
    logic                       aes_decrypt_ecb_op;
} kv_write_filter_metrics_t;
endpackage
package pv_defines_pkg;
parameter PV_NUM_DWORDS = 12;  
parameter PV_NUM_PCR = 32;
parameter PV_ADDR_W = 13;
parameter PV_DATA_W = 32;
parameter PV_ENTRY_ADDR_W = $clog2(PV_NUM_PCR);
parameter PV_ENTRY_SIZE_WIDTH = $clog2(PV_NUM_DWORDS);
