   assign quotient_raw[15]       = (~adder15_out[37] ^ dividend_sign_ff) | ( (a_ff[27:0] == 28'b0) & (adder15_out[37:0] == 38'b0) );
   assign quotient_new[0]        = ( quotient_raw[15:01] == 15'b000_0000_0000_0001 ) |   
                                   ( quotient_raw[15:03] == 13'b000_0000_0000_01   ) |   
                                   ( quotient_raw[15:05] == 11'b000_0000_0001      ) |   
                                   ( quotient_raw[15:07] ==  9'b000_0000_01        ) |   
                                   ( quotient_raw[15:09] ==  7'b000_0001           ) |   
                                   ( quotient_raw[15:11] ==  5'b000_01             ) |   
                                   ( quotient_raw[15:13] ==  3'b001                ) |   
                                   ( quotient_raw[   15] ==  1'b1                  );    
   assign quotient_new[1]        = ( quotient_raw[15:02] == 14'b000_0000_0000_001  ) |   
                                   ( quotient_raw[15:03] == 13'b000_0000_0000_01   ) |   
                                   ( quotient_raw[15:06] == 10'b000_0000_001       ) |   
                                   ( quotient_raw[15:07] ==  9'b000_0000_01        ) |   
                                   ( quotient_raw[15:10] ==  6'b000_001            ) |   
                                   ( quotient_raw[15:11] ==  5'b000_01             ) |   
                                   ( quotient_raw[15:14] ==  2'b01                 ) |   
                                   ( quotient_raw[   15] ==  1'b1                  );    
   assign quotient_new[2]        = ( quotient_raw[15:04] == 12'b000_0000_0000_1    ) |   
                                   ( quotient_raw[15:05] == 11'b000_0000_0001      ) |   
                                   ( quotient_raw[15:06] == 10'b000_0000_001       ) |   
                                   ( quotient_raw[15:07] ==  9'b000_0000_01        ) |   
                                   ( quotient_raw[15:12] ==  4'b000_1              ) |   
                                   ( quotient_raw[15:13] ==  3'b001                ) |   
                                   ( quotient_raw[15:14] ==  2'b01                 ) |   
                                   ( quotient_raw[   15] ==  1'b1                  );    
   assign quotient_new[3]        = ( quotient_raw[15:08] ==  8'b000_0000_1         ) |   
                                   ( quotient_raw[15:09] ==  7'b000_0001           ) |   
                                   ( quotient_raw[15:10] ==  6'b000_001            ) |   
                                   ( quotient_raw[15:11] ==  5'b000_01             ) |   
                                   ( quotient_raw[15:12] ==  4'b000_1              ) |   
