   logic [1:0]                                    f0hist1;
   logic [1:0]                                    f1hist0;
   logic [1:0]                                    f0hist0;
   logic [1:0][$clog2(pt.BTB_SIZE)-1:0]           f0index, f1index, alignindex;
   logic [1:0]                                    f1ictype;
   logic [1:0]                                    f0ictype;
   logic [1:0]                                    f1pc4;
   logic [1:0]                                    f0pc4;
   logic [1:0]                                    f1ret;
   logic [1:0]                                    f0ret;
