   logic [1:0]                                    f0way;
   logic [1:0]                                    f1brend;
   logic [1:0]                                    f0brend;
   logic [1:0]                                    alignbrend;
   logic [1:0]                                    alignpc4;
   logic [1:0]                                    alignret;
   logic [1:0]                                    alignway;
