      output ic_tag_clken_final, ic_tag_wren_q, ic_tag_wren_biten_vec, ic_tag_wr_data, ic_rw_addr_q,
      input ic_tag_data_raw_packed_pre,ic_tag_data_raw_pre
  );
endinterface
module el2_lsu_addrcheck
import el2_pkg::*;
#(
parameter el2_param_t pt = '{
