module caliptra_prim_generic_clock_mux2 #(
  parameter bit NoFpgaBufG = 1'b0  
) (
  input        clk0_i,
  input        clk1_i,
  input        sel_i,
  output logic clk_o
);
  assign clk_o = (sel_i & clk1_i) | (~sel_i & clk0_i);
endmodule : caliptra_prim_generic_clock_mux2
module caliptra_prim_generic_clock_inv #(
  parameter bit HasScanMode = 1'b1,
  parameter bit NoFpgaBufG  = 1'b0  
) (
  input        clk_i,
  input        scanmode_i,
  output logic clk_no       
);
  if (HasScanMode) begin : gen_scan
    caliptra_prim_generic_clock_mux2 #(
      .NoFpgaBufG(NoFpgaBufG)
    ) i_dft_tck_mux (
      .clk0_i ( ~clk_i     ),
      .clk1_i ( clk_i      ),  
      .sel_i  ( scanmode_i ),
      .clk_o  ( clk_no     )
    );
  end else begin : gen_noscan
    logic unused_scanmode;
    assign unused_scanmode = scanmode_i;
    assign clk_no = ~clk_i;
  end
endmodule : caliptra_prim_generic_clock_inv
module caliptra_prim_generic_xor2 #(
