module kv_reg (
        input wire clk,
        input wire rst,
        input wire s_cpuif_req,
        input wire s_cpuif_req_is_wr,
        input wire [11:0] s_cpuif_addr,
        input wire [31:0] s_cpuif_wr_data,
        input wire [31:0] s_cpuif_wr_biten,
        output wire s_cpuif_req_stall_wr,
        output wire s_cpuif_req_stall_rd,
        output wire s_cpuif_rd_ack,
        output wire s_cpuif_rd_err,
        output wire [31:0] s_cpuif_rd_data,
        output wire s_cpuif_wr_ack,
        output wire s_cpuif_wr_err,
        input kv_reg_pkg::kv_reg__in_t hwif_in,
        output kv_reg_pkg::kv_reg__out_t hwif_out
    );
    logic cpuif_req;
    logic cpuif_req_is_wr;
    logic [11:0] cpuif_addr;
    logic [31:0] cpuif_wr_data;
    logic [31:0] cpuif_wr_biten;
    logic cpuif_req_stall_wr;
    logic cpuif_req_stall_rd;
    logic cpuif_rd_ack;
    logic cpuif_rd_err;
    logic [31:0] cpuif_rd_data;
    logic cpuif_wr_ack;
    logic cpuif_wr_err;
    assign cpuif_req = s_cpuif_req;
    assign cpuif_req_is_wr = s_cpuif_req_is_wr;
    assign cpuif_addr = s_cpuif_addr;
    assign cpuif_wr_data = s_cpuif_wr_data;
    assign cpuif_wr_biten = s_cpuif_wr_biten;
    assign s_cpuif_req_stall_wr = cpuif_req_stall_wr;
    assign s_cpuif_req_stall_rd = cpuif_req_stall_rd;
    assign s_cpuif_rd_ack = cpuif_rd_ack;
    assign s_cpuif_rd_err = cpuif_rd_err;
    assign s_cpuif_rd_data = cpuif_rd_data;
    assign s_cpuif_wr_ack = cpuif_wr_ack;
    assign s_cpuif_wr_err = cpuif_wr_err;
    logic cpuif_req_masked;
    assign cpuif_req_stall_rd = '0;
    assign cpuif_req_stall_wr = '0;
    assign cpuif_req_masked = cpuif_req
                            & !(!cpuif_req_is_wr & cpuif_req_stall_rd)
                            & !(cpuif_req_is_wr & cpuif_req_stall_wr);
    typedef struct packed{
        logic [24-1:0]KEY_CTRL;
        logic [24-1:0][16-1:0]KEY_ENTRY;
        logic CLEAR_SECRETS;
    } decoded_reg_strb_t;
    decoded_reg_strb_t decoded_reg_strb;
    logic decoded_req;
    logic decoded_req_is_wr;
    logic [31:0] decoded_wr_data;
    logic [31:0] decoded_wr_biten;
    always_comb begin
        for(int i0=0; i0<24; i0++) begin
            decoded_reg_strb.KEY_CTRL[i0] = cpuif_req_masked & (cpuif_addr == 12'h0 + i0*12'h4);
        end
        for(int i0=0; i0<24; i0++) begin
            for(int i1=0; i1<16; i1++) begin
                decoded_reg_strb.KEY_ENTRY[i0][i1] = cpuif_req_masked & (cpuif_addr == 12'h600 + i0*12'h40 + i1*12'h4);
            end
        end
        decoded_reg_strb.CLEAR_SECRETS = cpuif_req_masked & (cpuif_addr == 12'hc00);
    end
    assign decoded_req = cpuif_req_masked;
    assign decoded_req_is_wr = cpuif_req_is_wr;
    assign decoded_wr_data = cpuif_wr_data;
    assign decoded_wr_biten = cpuif_wr_biten;
    typedef struct packed{
        struct packed{
            struct packed{
                logic next;
                logic load_next;
            } lock_wr;
            struct packed{
                logic next;
                logic load_next;
            } lock_use;
            struct packed{
                logic next;
                logic load_next;
            } clear;
            struct packed{
                logic next;
                logic load_next;
            } rsvd0;
            struct packed{
                logic [4:0] next;
                logic load_next;
            } rsvd1;
            struct packed{
                logic [8:0] next;
                logic load_next;
            } dest_valid;
            struct packed{
                logic [3:0] next;
                logic load_next;
            } last_dword;
        } [24-1:0]KEY_CTRL;
        struct packed{
            struct packed{
                logic [31:0] next;
                logic load_next;
            } data;
        } [24-1:0][16-1:0]KEY_ENTRY;
        struct packed{
            struct packed{
                logic next;
                logic load_next;
            } wr_debug_values;
            struct packed{
                logic next;
                logic load_next;
            } sel_debug_value;
        } CLEAR_SECRETS;
    } field_combo_t;
    field_combo_t field_combo;
    typedef struct packed{
        struct packed{
            struct packed{
                logic value;
            } lock_wr;
            struct packed{
                logic value;
            } lock_use;
            struct packed{
                logic value;
            } clear;
            struct packed{
                logic value;
            } rsvd0;
            struct packed{
                logic [4:0] value;
            } rsvd1;
            struct packed{
                logic [8:0] value;
            } dest_valid;
            struct packed{
                logic [3:0] value;
            } last_dword;
        } [24-1:0]KEY_CTRL;
        struct packed{
            struct packed{
                logic [31:0] value;
            } data;
        } [24-1:0][16-1:0]KEY_ENTRY;
        struct packed{
            struct packed{
                logic value;
            } wr_debug_values;
            struct packed{
                logic value;
            } sel_debug_value;
        } CLEAR_SECRETS;
    } field_storage_t;
    field_storage_t field_storage;
    for(genvar i0=0; i0<24; i0++) begin
        always_comb begin
            automatic logic [0:0] next_c;
            automatic logic load_next_c;
            next_c = field_storage.KEY_CTRL[i0].lock_wr.value;
            load_next_c = '0;
            if(decoded_reg_strb.KEY_CTRL[i0] && decoded_req_is_wr && !(hwif_in.KEY_CTRL[i0].lock_wr.swwel)) begin  
                next_c = (field_storage.KEY_CTRL[i0].lock_wr.value & ~decoded_wr_biten[0:0]) | (decoded_wr_data[0:0] & decoded_wr_biten[0:0]);
                load_next_c = '1;
            end
            field_combo.KEY_CTRL[i0].lock_wr.next = next_c;
            field_combo.KEY_CTRL[i0].lock_wr.load_next = load_next_c;
        end
        always_ff @(posedge clk or negedge hwif_in.core_only_rst_b) begin
            if(~hwif_in.core_only_rst_b) begin
                field_storage.KEY_CTRL[i0].lock_wr.value <= 1'h0;
            end else if(field_combo.KEY_CTRL[i0].lock_wr.load_next) begin
                field_storage.KEY_CTRL[i0].lock_wr.value <= field_combo.KEY_CTRL[i0].lock_wr.next;
            end
        end
        assign hwif_out.KEY_CTRL[i0].lock_wr.value = field_storage.KEY_CTRL[i0].lock_wr.value;
        always_comb begin
            automatic logic [0:0] next_c;
            automatic logic load_next_c;
            next_c = field_storage.KEY_CTRL[i0].lock_use.value;
            load_next_c = '0;
            if(decoded_reg_strb.KEY_CTRL[i0] && decoded_req_is_wr && !(hwif_in.KEY_CTRL[i0].lock_use.swwel)) begin  
                next_c = (field_storage.KEY_CTRL[i0].lock_use.value & ~decoded_wr_biten[1:1]) | (decoded_wr_data[1:1] & decoded_wr_biten[1:1]);
                load_next_c = '1;
            end
            field_combo.KEY_CTRL[i0].lock_use.next = next_c;
            field_combo.KEY_CTRL[i0].lock_use.load_next = load_next_c;
        end
        always_ff @(posedge clk or negedge hwif_in.core_only_rst_b) begin
            if(~hwif_in.core_only_rst_b) begin
                field_storage.KEY_CTRL[i0].lock_use.value <= 1'h0;
            end else if(field_combo.KEY_CTRL[i0].lock_use.load_next) begin
                field_storage.KEY_CTRL[i0].lock_use.value <= field_combo.KEY_CTRL[i0].lock_use.next;
            end
        end
        assign hwif_out.KEY_CTRL[i0].lock_use.value = field_storage.KEY_CTRL[i0].lock_use.value;
        always_comb begin
            automatic logic [0:0] next_c;
            automatic logic load_next_c;
            next_c = field_storage.KEY_CTRL[i0].clear.value;
            load_next_c = '0;
            if(decoded_reg_strb.KEY_CTRL[i0] && decoded_req_is_wr) begin  
                next_c = (field_storage.KEY_CTRL[i0].clear.value & ~decoded_wr_biten[2:2]) | (decoded_wr_data[2:2] & decoded_wr_biten[2:2]);
                load_next_c = '1;
            end else begin  
                next_c = '0;
                load_next_c = '1;
            end
            field_combo.KEY_CTRL[i0].clear.next = next_c;
            field_combo.KEY_CTRL[i0].clear.load_next = load_next_c;
        end
        always_ff @(posedge clk or negedge hwif_in.reset_b) begin
            if(~hwif_in.reset_b) begin
                field_storage.KEY_CTRL[i0].clear.value <= 1'h0;
            end else if(field_combo.KEY_CTRL[i0].clear.load_next) begin
                field_storage.KEY_CTRL[i0].clear.value <= field_combo.KEY_CTRL[i0].clear.next;
            end
        end
        assign hwif_out.KEY_CTRL[i0].clear.value = field_storage.KEY_CTRL[i0].clear.value;
        always_comb begin
            automatic logic [0:0] next_c;
            automatic logic load_next_c;
            next_c = field_storage.KEY_CTRL[i0].rsvd0.value;
            load_next_c = '0;
            if(decoded_reg_strb.KEY_CTRL[i0] && decoded_req_is_wr) begin  
                next_c = (field_storage.KEY_CTRL[i0].rsvd0.value & ~decoded_wr_biten[3:3]) | (decoded_wr_data[3:3] & decoded_wr_biten[3:3]);
                load_next_c = '1;
            end else if(hwif_in.KEY_CTRL[i0].rsvd0.hwclr) begin  
                next_c = '0;
                load_next_c = '1;
            end
            field_combo.KEY_CTRL[i0].rsvd0.next = next_c;
            field_combo.KEY_CTRL[i0].rsvd0.load_next = load_next_c;
        end
        always_ff @(posedge clk or negedge hwif_in.reset_b) begin
            if(~hwif_in.reset_b) begin
                field_storage.KEY_CTRL[i0].rsvd0.value <= 1'h0;
            end else if(field_combo.KEY_CTRL[i0].rsvd0.load_next) begin
                field_storage.KEY_CTRL[i0].rsvd0.value <= field_combo.KEY_CTRL[i0].rsvd0.next;
            end
        end
        assign hwif_out.KEY_CTRL[i0].rsvd0.value = field_storage.KEY_CTRL[i0].rsvd0.value;
        always_comb begin
            automatic logic [4:0] next_c;
            automatic logic load_next_c;
            next_c = field_storage.KEY_CTRL[i0].rsvd1.value;
            load_next_c = '0;
            if(decoded_reg_strb.KEY_CTRL[i0] && decoded_req_is_wr) begin  
                next_c = (field_storage.KEY_CTRL[i0].rsvd1.value & ~decoded_wr_biten[8:4]) | (decoded_wr_data[8:4] & decoded_wr_biten[8:4]);
                load_next_c = '1;
            end
            field_combo.KEY_CTRL[i0].rsvd1.next = next_c;
            field_combo.KEY_CTRL[i0].rsvd1.load_next = load_next_c;
        end
        always_ff @(posedge clk or negedge hwif_in.reset_b) begin
            if(~hwif_in.reset_b) begin
                field_storage.KEY_CTRL[i0].rsvd1.value <= 5'h0;
            end else if(field_combo.KEY_CTRL[i0].rsvd1.load_next) begin
                field_storage.KEY_CTRL[i0].rsvd1.value <= field_combo.KEY_CTRL[i0].rsvd1.next;
            end
        end
        assign hwif_out.KEY_CTRL[i0].rsvd1.value = field_storage.KEY_CTRL[i0].rsvd1.value;
        always_comb begin
            automatic logic [8:0] next_c;
            automatic logic load_next_c;
            next_c = field_storage.KEY_CTRL[i0].dest_valid.value;
            load_next_c = '0;
            if(hwif_in.KEY_CTRL[i0].dest_valid.we) begin  
                next_c = hwif_in.KEY_CTRL[i0].dest_valid.next;
                load_next_c = '1;
            end else if(hwif_in.KEY_CTRL[i0].dest_valid.hwclr) begin  
                next_c = '0;
                load_next_c = '1;
            end
            field_combo.KEY_CTRL[i0].dest_valid.next = next_c;
            field_combo.KEY_CTRL[i0].dest_valid.load_next = load_next_c;
        end
        always_ff @(posedge clk or negedge hwif_in.hard_reset_b) begin
            if(~hwif_in.hard_reset_b) begin
                field_storage.KEY_CTRL[i0].dest_valid.value <= 9'h0;
            end else if(field_combo.KEY_CTRL[i0].dest_valid.load_next) begin
                field_storage.KEY_CTRL[i0].dest_valid.value <= field_combo.KEY_CTRL[i0].dest_valid.next;
            end
        end
        assign hwif_out.KEY_CTRL[i0].dest_valid.value = field_storage.KEY_CTRL[i0].dest_valid.value;
        always_comb begin
            automatic logic [3:0] next_c;
            automatic logic load_next_c;
            next_c = field_storage.KEY_CTRL[i0].last_dword.value;
            load_next_c = '0;
            if(hwif_in.KEY_CTRL[i0].last_dword.we) begin  
                next_c = hwif_in.KEY_CTRL[i0].last_dword.next;
                load_next_c = '1;
            end else if(hwif_in.KEY_CTRL[i0].last_dword.hwclr) begin  
                next_c = '0;
                load_next_c = '1;
            end
            field_combo.KEY_CTRL[i0].last_dword.next = next_c;
            field_combo.KEY_CTRL[i0].last_dword.load_next = load_next_c;
        end
        always_ff @(posedge clk or negedge hwif_in.hard_reset_b) begin
            if(~hwif_in.hard_reset_b) begin
                field_storage.KEY_CTRL[i0].last_dword.value <= 4'h0;
            end else if(field_combo.KEY_CTRL[i0].last_dword.load_next) begin
                field_storage.KEY_CTRL[i0].last_dword.value <= field_combo.KEY_CTRL[i0].last_dword.next;
            end
        end
        assign hwif_out.KEY_CTRL[i0].last_dword.value = field_storage.KEY_CTRL[i0].last_dword.value;
    end
    for(genvar i0=0; i0<24; i0++) begin
        for(genvar i1=0; i1<16; i1++) begin
            always_comb begin
                automatic logic [31:0] next_c;
                automatic logic load_next_c;
                next_c = field_storage.KEY_ENTRY[i0][i1].data.value;
                load_next_c = '0;
                if(decoded_reg_strb.KEY_ENTRY[i0][i1] && decoded_req_is_wr && !(hwif_in.KEY_ENTRY[i0][i1].data.swwel)) begin  
                    next_c = (field_storage.KEY_ENTRY[i0][i1].data.value & ~decoded_wr_biten[31:0]) | (decoded_wr_data[31:0] & decoded_wr_biten[31:0]);
                    load_next_c = '1;
                end else if(hwif_in.KEY_ENTRY[i0][i1].data.we) begin  
                    next_c = hwif_in.KEY_ENTRY[i0][i1].data.next;
                    load_next_c = '1;
                end else if(hwif_in.KEY_ENTRY[i0][i1].data.hwclr) begin  
                    next_c = '0;
                    load_next_c = '1;
                end
                field_combo.KEY_ENTRY[i0][i1].data.next = next_c;
                field_combo.KEY_ENTRY[i0][i1].data.load_next = load_next_c;
            end
            always_ff @(posedge clk or negedge hwif_in.hard_reset_b) begin
                if(~hwif_in.hard_reset_b) begin
                    field_storage.KEY_ENTRY[i0][i1].data.value <= 32'h0;
                end else if(field_combo.KEY_ENTRY[i0][i1].data.load_next) begin
                    field_storage.KEY_ENTRY[i0][i1].data.value <= field_combo.KEY_ENTRY[i0][i1].data.next;
                end
            end
            assign hwif_out.KEY_ENTRY[i0][i1].data.value = field_storage.KEY_ENTRY[i0][i1].data.value;
        end
    end
    always_comb begin
        automatic logic [0:0] next_c;
        automatic logic load_next_c;
        next_c = field_storage.CLEAR_SECRETS.wr_debug_values.value;
        load_next_c = '0;
        if(decoded_reg_strb.CLEAR_SECRETS && decoded_req_is_wr) begin  
            next_c = (field_storage.CLEAR_SECRETS.wr_debug_values.value & ~decoded_wr_biten[0:0]) | (decoded_wr_data[0:0] & decoded_wr_biten[0:0]);
            load_next_c = '1;
        end else begin  
            next_c = '0;
            load_next_c = '1;
        end
        field_combo.CLEAR_SECRETS.wr_debug_values.next = next_c;
        field_combo.CLEAR_SECRETS.wr_debug_values.load_next = load_next_c;
    end
    always_ff @(posedge clk or negedge hwif_in.reset_b) begin
        if(~hwif_in.reset_b) begin
            field_storage.CLEAR_SECRETS.wr_debug_values.value <= 1'h0;
        end else if(field_combo.CLEAR_SECRETS.wr_debug_values.load_next) begin
            field_storage.CLEAR_SECRETS.wr_debug_values.value <= field_combo.CLEAR_SECRETS.wr_debug_values.next;
        end
    end
    assign hwif_out.CLEAR_SECRETS.wr_debug_values.value = field_storage.CLEAR_SECRETS.wr_debug_values.value;
    always_comb begin
        automatic logic [0:0] next_c;
        automatic logic load_next_c;
        next_c = field_storage.CLEAR_SECRETS.sel_debug_value.value;
        load_next_c = '0;
        if(decoded_reg_strb.CLEAR_SECRETS && decoded_req_is_wr) begin  
            next_c = (field_storage.CLEAR_SECRETS.sel_debug_value.value & ~decoded_wr_biten[1:1]) | (decoded_wr_data[1:1] & decoded_wr_biten[1:1]);
            load_next_c = '1;
        end
        field_combo.CLEAR_SECRETS.sel_debug_value.next = next_c;
        field_combo.CLEAR_SECRETS.sel_debug_value.load_next = load_next_c;
    end
    always_ff @(posedge clk or negedge hwif_in.reset_b) begin
        if(~hwif_in.reset_b) begin
            field_storage.CLEAR_SECRETS.sel_debug_value.value <= 1'h0;
        end else if(field_combo.CLEAR_SECRETS.sel_debug_value.load_next) begin
            field_storage.CLEAR_SECRETS.sel_debug_value.value <= field_combo.CLEAR_SECRETS.sel_debug_value.next;
        end
    end
    assign hwif_out.CLEAR_SECRETS.sel_debug_value.value = field_storage.CLEAR_SECRETS.sel_debug_value.value;
    assign cpuif_wr_ack = decoded_req & decoded_req_is_wr;
    assign cpuif_wr_err = '0;
    logic readback_err;
    logic readback_done;
    logic [31:0] readback_data;
    logic [25-1:0][31:0] readback_array;
    for(genvar i0=0; i0<24; i0++) begin
        assign readback_array[i0*1 + 0][0:0] = (decoded_reg_strb.KEY_CTRL[i0] && !decoded_req_is_wr) ? field_storage.KEY_CTRL[i0].lock_wr.value : '0;
        assign readback_array[i0*1 + 0][1:1] = (decoded_reg_strb.KEY_CTRL[i0] && !decoded_req_is_wr) ? field_storage.KEY_CTRL[i0].lock_use.value : '0;
        assign readback_array[i0*1 + 0][2:2] = (decoded_reg_strb.KEY_CTRL[i0] && !decoded_req_is_wr) ? field_storage.KEY_CTRL[i0].clear.value : '0;
        assign readback_array[i0*1 + 0][3:3] = (decoded_reg_strb.KEY_CTRL[i0] && !decoded_req_is_wr) ? field_storage.KEY_CTRL[i0].rsvd0.value : '0;
        assign readback_array[i0*1 + 0][8:4] = (decoded_reg_strb.KEY_CTRL[i0] && !decoded_req_is_wr) ? field_storage.KEY_CTRL[i0].rsvd1.value : '0;
        assign readback_array[i0*1 + 0][17:9] = (decoded_reg_strb.KEY_CTRL[i0] && !decoded_req_is_wr) ? field_storage.KEY_CTRL[i0].dest_valid.value : '0;
        assign readback_array[i0*1 + 0][21:18] = (decoded_reg_strb.KEY_CTRL[i0] && !decoded_req_is_wr) ? field_storage.KEY_CTRL[i0].last_dword.value : '0;
        assign readback_array[i0*1 + 0][31:22] = '0;
    end
    assign readback_array[24][0:0] = (decoded_reg_strb.CLEAR_SECRETS && !decoded_req_is_wr) ? field_storage.CLEAR_SECRETS.wr_debug_values.value : '0;
    assign readback_array[24][1:1] = (decoded_reg_strb.CLEAR_SECRETS && !decoded_req_is_wr) ? field_storage.CLEAR_SECRETS.sel_debug_value.value : '0;
    assign readback_array[24][31:2] = '0;
    always_comb begin
        automatic logic [31:0] readback_data_var;
        readback_done = decoded_req & ~decoded_req_is_wr;
        readback_err = '0;
        readback_data_var = '0;
        for(int i=0; i<25; i++) readback_data_var |= readback_array[i];
        readback_data = readback_data_var;
    end
    assign cpuif_rd_ack = readback_done;
    assign cpuif_rd_data = readback_data;
    assign cpuif_rd_err = readback_err;
endmodule
module kv 
    import kv_defines_pkg::*;
    import kv_reg_pkg::*;
    #(
     parameter AHB_ADDR_WIDTH = KV_ADDR_W
    ,parameter AHB_DATA_WIDTH = 32
    )
    (
    input logic clk,
    input logic rst_b,
    input logic core_only_rst_b,
    input logic cptra_pwrgood,
    input logic fw_update_rst_window,
    input logic cptra_in_debug_scan_mode,
    input logic debugUnlock_or_scan_mode_switch,
    input logic [AHB_ADDR_WIDTH-1:0]      haddr_i,
    input logic [AHB_DATA_WIDTH-1:0]      hwdata_i,
    input logic                           hsel_i,
    input logic                           hwrite_i,
    input logic                           hready_i,
    input logic [1:0]                     htrans_i,
    input logic [2:0]                     hsize_i,
    output logic                          hresp_o,
    output logic                          hreadyout_o,
    output logic [AHB_DATA_WIDTH-1:0]     hrdata_o,
    input kv_read_t [KV_NUM_READ-1:0]     kv_read,
    input kv_write_t [KV_NUM_WRITE-1:0]   kv_write,
    output kv_rd_resp_t [KV_NUM_READ-1:0] kv_rd_resp,
    output kv_wr_resp_t [KV_NUM_WRITE-1:0] kv_wr_resp,
    output logic [ECC_NUM_DWORDS-1:0][31:0]     pcr_ecc_signing_key,
    output logic [MLDSA_NUM_DWORDS-1:0][31:0]   pcr_mldsa_signing_key
);
logic uc_req_dv, uc_req_hold;
logic uc_req_error;
logic [31:0] uc_req_rdata;
logic kv_reg_read_error, kv_reg_write_error;
logic [AHB_ADDR_WIDTH-1:0] uc_req_addr;
kv_uc_req_t uc_req;
logic flush_keyvault;
logic [31:0] debug_value;
logic [KV_NUM_KEYS-1:0][KV_NUM_DWORDS-1:0] key_entry_we;
logic [KV_NUM_KEYS-1:0] key_entry_ctrl_we;
logic [KV_NUM_KEYS-1:0][KV_NUM_DWORDS-1:0][31:0] key_entry_next;
logic [KV_NUM_KEYS-1:0][KV_NUM_READ-1:0] key_entry_dest_valid_next;
logic [KV_NUM_KEYS-1:0][KV_ENTRY_SIZE_W-1:0] key_entry_last_dword_next;
logic [KV_NUM_KEYS-1:0] lock_wr_q;
logic [KV_NUM_KEYS-1:0] lock_use_q;
kv_reg__in_t kv_reg_hwif_in;
kv_reg__out_t kv_reg_hwif_out;
logic [KV_NUM_KEYS-1:0] key_entry_clear;
logic [$clog2(KV_NUM_WRITE)-1:0] kv_write_cnt;
logic kv_multi_write_err;
ahb_slv_sif #(
    .AHB_ADDR_WIDTH(AHB_ADDR_WIDTH),
    .AHB_DATA_WIDTH(AHB_DATA_WIDTH),
    .CLIENT_DATA_WIDTH(32)
)
kv_ahb_slv1 (
    .hclk(clk),
    .hreset_n(rst_b),
    .haddr_i(haddr_i),
    .hwdata_i(hwdata_i),
    .hsel_i(hsel_i),
    .hwrite_i(hwrite_i),
    .hready_i(hready_i),
    .htrans_i(htrans_i),
    .hsize_i(hsize_i),
    .hresp_o(hresp_o),
    .hreadyout_o(hreadyout_o),
    .hrdata_o(hrdata_o),
    .dv(uc_req_dv),
    .hld(uc_req_hold),
    .err(uc_req_error),
    .write(uc_req.write),
    .wdata(uc_req.wdata),
    .addr(uc_req_addr),
    .rdata(uc_req_rdata)
);
always_comb uc_req.addr = uc_req_addr[KV_ADDR_W-1:0];
always_comb uc_req_error = kv_reg_read_error | kv_reg_write_error;
always_comb uc_req_hold = '0;
always_comb flush_keyvault = debugUnlock_or_scan_mode_switch | 
                             (cptra_in_debug_scan_mode & kv_reg_hwif_out.CLEAR_SECRETS.wr_debug_values.value);
always_comb debug_value = kv_reg_hwif_out.CLEAR_SECRETS.sel_debug_value.value ? CLP_DEBUG_MODE_KV_1 : CLP_DEBUG_MODE_KV_0;
always_comb begin : keyvault_pcr_ecc_signing
    for (int dword = 0; dword < ECC_NUM_DWORDS; dword++) begin
        pcr_ecc_signing_key[dword] = kv_reg_hwif_out.KEY_ENTRY[KV_ENTRY_FOR_ECC_SIGNING][dword].data.value;
    end 
end
always_comb begin : keyvault_pcr_mldsa_signing
    for (int dword = 0; dword < MLDSA_NUM_DWORDS; dword++) begin
        pcr_mldsa_signing_key[dword] = kv_reg_hwif_out.KEY_ENTRY[KV_ENTRY_FOR_MLDSA_SIGNING][dword].data.value;
    end 
end
always_comb begin
    kv_write_cnt = 0;
    for (int client = 0; client < KV_NUM_WRITE; client++)begin
        if (kv_write[client].write_en)
            kv_write_cnt = kv_write_cnt + 'd1;
    end
end
always_comb kv_multi_write_err = kv_write_cnt > 1;
generate
    for (genvar g_entry = 0; g_entry < KV_NUM_KEYS; g_entry++) begin
        always_ff@(posedge clk or negedge rst_b) begin
            if(~rst_b) begin
                key_entry_clear[g_entry] <= '0;
            end
            else begin
                key_entry_clear[g_entry] <= kv_multi_write_err |
                                            (kv_reg_hwif_out.KEY_CTRL[g_entry].clear.value & ~lock_wr_q[g_entry] & ~lock_use_q[g_entry]) |
                                            (key_entry_clear[g_entry] & key_entry_ctrl_we[g_entry]);
            end
        end
    end
endgenerate
always_comb begin : keyvault_ctrl
    for (int entry = 0; entry < KV_NUM_KEYS; entry++) begin
        key_entry_ctrl_we[entry] = '0;
        key_entry_dest_valid_next[entry] = '0; 
        key_entry_last_dword_next[entry] = '0;
        lock_wr_q[entry] = kv_reg_hwif_out.KEY_CTRL[entry].lock_wr.value & ~fw_update_rst_window;
        lock_use_q[entry] = kv_reg_hwif_out.KEY_CTRL[entry].lock_use.value & ~fw_update_rst_window;
        for (int client = 0; client < KV_NUM_WRITE; client++) begin
            key_entry_ctrl_we[entry] |= (kv_write[client].write_entry == entry) & kv_write[client].write_en & 
                                        ~lock_wr_q[entry] & ~lock_use_q[entry]; 
            key_entry_dest_valid_next[entry] |= (kv_write[client].write_entry == entry) & kv_write[client].write_en ? kv_write[client].write_dest_valid : '0;
            key_entry_last_dword_next[entry] |= (kv_write[client].write_entry == entry) & kv_write[client].write_en ? kv_write[client].write_offset : '0;
        end 
        kv_reg_hwif_in.KEY_CTRL[entry].lock_wr.swwel = lock_wr_q[entry];
        kv_reg_hwif_in.KEY_CTRL[entry].lock_use.swwel = lock_use_q[entry];
        kv_reg_hwif_in.KEY_CTRL[entry].dest_valid.hwclr = key_entry_clear[entry];
        kv_reg_hwif_in.KEY_CTRL[entry].last_dword.hwclr = key_entry_clear[entry];
        kv_reg_hwif_in.KEY_CTRL[entry].dest_valid.we = key_entry_ctrl_we[entry] & ~key_entry_clear[entry];
        kv_reg_hwif_in.KEY_CTRL[entry].dest_valid.next = {3'd0,key_entry_dest_valid_next[entry]};
        kv_reg_hwif_in.KEY_CTRL[entry].last_dword.we = key_entry_ctrl_we[entry] & ~key_entry_clear[entry];
        kv_reg_hwif_in.KEY_CTRL[entry].last_dword.next = key_entry_last_dword_next[entry];
    end
    for (int entry = 0; entry < KV_NUM_KEYS; entry++) begin
        for (int dword = 0; dword < KV_NUM_DWORDS; dword++) begin
            kv_reg_hwif_in.KEY_ENTRY[entry][dword].data.swwel = '1;  
            key_entry_we[entry][dword] = '0;
            key_entry_next[entry][dword] = '0;
            for (int client = 0; client < KV_NUM_WRITE; client++) begin
                key_entry_we[entry][dword] |= ((((kv_write[client].write_entry == entry) & (kv_write[client].write_offset == dword) & 
                                                kv_write[client].write_en) | flush_keyvault) & 
                                              ((~lock_wr_q[entry] & ~lock_use_q[entry]) | debugUnlock_or_scan_mode_switch));
                key_entry_next[entry][dword] |= flush_keyvault ? debug_value :
                                                kv_write[client].write_en & (kv_write[client].write_entry == entry) ? kv_write[client].write_data : '0;
            end
            kv_reg_hwif_in.KEY_ENTRY[entry][dword].data.we = key_entry_we[entry][dword] & ~key_entry_clear[entry];
            kv_reg_hwif_in.KEY_ENTRY[entry][dword].data.next = key_entry_next[entry][dword];
            kv_reg_hwif_in.KEY_ENTRY[entry][dword].data.hwclr = key_entry_clear[entry];
        end
    end
end
always_comb begin : keyvault_readmux
    for (int client = 0; client < KV_NUM_READ; client++) begin  
        kv_rd_resp[client].read_data = '0;
        kv_rd_resp[client].error = '0;
        kv_rd_resp[client].last = '0;
        for (int entry = 0; entry < KV_NUM_KEYS; entry++) begin
            for (int dword = 0; dword < KV_NUM_DWORDS; dword++) begin
                kv_rd_resp[client].read_data |= (kv_read[client].read_entry == entry) & (kv_read[client].read_offset == dword) &
                                                ~lock_use_q[entry] & kv_reg_hwif_out.KEY_CTRL[entry].dest_valid.value[client] ? 
                                                 kv_reg_hwif_out.KEY_ENTRY[entry][dword].data.value : '0;
            end
        kv_rd_resp[client].last |= (kv_read[client].read_entry == entry) & (kv_read[client].read_offset == kv_reg_hwif_out.KEY_CTRL[entry].last_dword.value);
        kv_rd_resp[client].error |= (kv_read[client].read_entry == entry) & 
                                    (lock_use_q[entry] | ~kv_reg_hwif_out.KEY_CTRL[entry].dest_valid.value[client]);
        end
    end
end
always_comb begin : keyvault_write_resp
    for (int client = 0 ; client < KV_NUM_WRITE; client++) begin
        kv_wr_resp[client].error = '0;
        for (int entry = 0; entry < KV_NUM_KEYS; entry++) begin
            kv_wr_resp[client].error |= (kv_write[client].write_entry == entry) & kv_write[client].write_en &
                                        (key_entry_clear[entry] | lock_wr_q[entry] | lock_use_q[entry]);
        end
    end
end
always_comb begin
    for (int entry = 0; entry < KV_NUM_KEYS; entry++) begin
        kv_reg_hwif_in.KEY_CTRL[entry].rsvd0.hwclr = '0;
    end
end
always_comb kv_reg_hwif_in.hard_reset_b = cptra_pwrgood;
always_comb kv_reg_hwif_in.reset_b = rst_b;
always_comb kv_reg_hwif_in.core_only_rst_b = core_only_rst_b;  
kv_reg kv_reg1 (
    .clk(clk),
    .rst('0),
    .s_cpuif_req(uc_req_dv),
    .s_cpuif_req_is_wr(uc_req.write),
    .s_cpuif_addr(uc_req.addr[KV_REG_ADDR_WIDTH-1:0]),
    .s_cpuif_wr_data(uc_req.wdata),
    .s_cpuif_wr_biten('1),
    .s_cpuif_req_stall_wr(),
    .s_cpuif_req_stall_rd(),
    .s_cpuif_rd_ack(),
    .s_cpuif_rd_err(kv_reg_read_error),
    .s_cpuif_rd_data(uc_req_rdata),
    .s_cpuif_wr_ack(),
    .s_cpuif_wr_err(kv_reg_write_error),
    .hwif_in(kv_reg_hwif_in),
    .hwif_out(kv_reg_hwif_out)
);
endmodule
module kv_fsm 
    import kv_defines_pkg::*;
    #(
    parameter DATA_WIDTH = 512
   ,parameter PAD = 0
   ,parameter HMAC = 0
   ,localparam OFFSET_W = $clog2(DATA_WIDTH/32)
)
(
    input logic clk,
    input logic rst_b,
    input logic zeroize,
    input logic start,
    input logic allow,
    input logic last,
    input logic pcr_hash_extend,
    input logic [OFFSET_W:0] num_dwords,
    output logic [OFFSET_W-1:0] read_offset,
    output logic write_en,
    output logic [OFFSET_W-1:0] write_offset,
    output logic write_pad,
    output logic [31:0] pad_data,
    output logic write_last,
    output logic ready,
    output logic done
);
localparam KV_MAX_DWORDS = 1024/32;
localparam KV_NUM_DWORDS_W = $clog2(KV_MAX_DWORDS);
localparam KV_PAD_LENGTH_START = 28;
logic [KV_NUM_DWORDS_W:0] num_dwords_data;
logic [KV_NUM_DWORDS_W:0] num_dwords_total;
logic [31:0] length_for_pad;
typedef enum logic [2:0] {
    KV_IDLE   = 3'b000,
    KV_RW     = 3'b001,
    KV_PAD    = 3'b011,
    KV_ZERO   = 3'b010,
    KV_LENGTH = 3'b110,
    KV_DONE   = 3'b100
} kv_fsm_state_e;
kv_fsm_state_e kv_fsm_ps, kv_fsm_ns;
logic arc_KV_IDLE_KV_RW;
logic arc_KV_IDLE_KV_DONE;
logic arc_KV_RW_KV_DONE;
logic arc_KV_DONE_KV_IDLE;
logic arc_KV_RW_KV_PAD;
logic arc_KV_PAD_KV_ZERO;
logic arc_KV_ZERO_KV_LENGTH;
logic arc_KV_LENGTH_KV_DONE;
logic offset_en;
logic offset_rst;
logic [OFFSET_W:0] offset, offset_nxt;
assign num_dwords_total = pcr_hash_extend ? 'd12 :
                          ((PAD == 1) ? KV_MAX_DWORDS : $bits(num_dwords_total)'(num_dwords));
always_comb ready = (kv_fsm_ps == KV_IDLE);
always_comb length_for_pad = (HMAC == 1) ? (32'b0 | ((num_dwords_data << 5) + 'd1024)) : (32'b0 | (num_dwords_data << 5));
always_comb arc_KV_IDLE_KV_RW = start && allow;
always_comb arc_KV_IDLE_KV_DONE = start && !allow;
always_comb arc_KV_RW_KV_DONE = ((PAD == 0) | pcr_hash_extend) & (($bits(num_dwords_total)'(offset) == (num_dwords_total-1)) | last);  
always_comb arc_KV_RW_KV_PAD  = ((PAD == 1) & ~pcr_hash_extend) & last;  
always_comb arc_KV_PAD_KV_ZERO = (PAD == 1) && (kv_fsm_ps == KV_PAD);
always_comb arc_KV_ZERO_KV_LENGTH = (PAD == 1) && ($bits(num_dwords_total)'(offset_nxt) == 'd31);  
always_comb arc_KV_LENGTH_KV_DONE = (PAD == 1) && (kv_fsm_ps == KV_LENGTH);
always_comb arc_KV_DONE_KV_IDLE = '1;
always_comb offset_rst = arc_KV_RW_KV_DONE | arc_KV_LENGTH_KV_DONE;
always_comb write_last = arc_KV_RW_KV_DONE | arc_KV_LENGTH_KV_DONE;
always_comb begin : kv_fsm_comb
    kv_fsm_ns = kv_fsm_ps;
    write_en = '0;
    write_pad = '0;
    offset_en = '0;
    offset_nxt = '0;
    pad_data = '0;
    done = '0;
    unique case (kv_fsm_ps)
        KV_IDLE: begin
            if      (arc_KV_IDLE_KV_RW)   kv_fsm_ns = KV_RW;
            else if (arc_KV_IDLE_KV_DONE) kv_fsm_ns = KV_DONE;
        end
        KV_RW: begin
            if (arc_KV_RW_KV_PAD) kv_fsm_ns = KV_PAD;
            if (arc_KV_RW_KV_DONE) kv_fsm_ns = KV_DONE;
            write_en = '1;
            offset_en = '1;
            offset_nxt = offset + 'd1;
        end
        KV_PAD: begin
            if (arc_KV_PAD_KV_ZERO) kv_fsm_ns = KV_ZERO;
            write_en = '1;
            offset_en = '1;
            offset_nxt = offset + 'd1;
            write_pad = '1;
            pad_data = 32'h8000_0000;
        end
        KV_ZERO: begin
            if (arc_KV_ZERO_KV_LENGTH) kv_fsm_ns = KV_LENGTH;
            write_en = '1;
            offset_en = '1;
            offset_nxt = offset + 'd1;
            write_pad = '1;
            pad_data = '0;
        end
        KV_LENGTH: begin
            if (arc_KV_LENGTH_KV_DONE) kv_fsm_ns = KV_DONE;
            write_en = '1;
            offset_en = '1;
            offset_nxt = offset + 'd1;
            write_pad = '1;
            pad_data = length_for_pad;
        end
        KV_DONE: begin
            if (arc_KV_DONE_KV_IDLE) kv_fsm_ns = KV_IDLE;
            done = '1;
        end
        default: begin
        end
    endcase
end
always_ff @(posedge clk or negedge rst_b) begin
    if (!rst_b) begin
        kv_fsm_ps <= KV_IDLE;
        offset <= '0;
    end
    else if (zeroize) begin
        kv_fsm_ps <= KV_IDLE;
        offset <= '0;
    end
    else begin
        kv_fsm_ps <= kv_fsm_ns;
        offset <= offset_rst ? '0 :
                  offset_en ? offset_nxt : offset;
    end
end
generate
    if (PAD==1) begin
        always_ff @(posedge clk or negedge rst_b) begin
            if (!rst_b) begin
                num_dwords_data <= '0;
            end
            else if (zeroize) begin
                num_dwords_data <= '0;
            end
            else begin
                num_dwords_data <= arc_KV_RW_KV_PAD ? $bits(num_dwords_data)'(offset_nxt) : num_dwords_data;
            end
        end
    end else begin
        always_comb num_dwords_data = '0;
    end
endgenerate
always_comb read_offset = (kv_fsm_ps == KV_RW) ? offset[OFFSET_W-1:0] : '0;
always_comb write_offset = offset[OFFSET_W-1:0];
endmodule
module kv_read_client 
    import kv_defines_pkg::*;
    #(
    parameter DATA_WIDTH = 512
   ,parameter HMAC = 0
   ,parameter PAD = 0
   ,localparam DATA_OFFSET_W = $clog2(DATA_WIDTH/32)
)
(
    input logic clk,
    input logic rst_b,
    input logic zeroize,
    input kv_read_ctrl_reg_t read_ctrl_reg,
    input var kv_read_filter_metrics_t read_metrics,
    output kv_read_t kv_read,
    input kv_rd_resp_t kv_resp,
    output logic write_en,
    output logic [DATA_OFFSET_W-1:0] write_offset,
    output logic [31:0] write_data,
    output kv_error_code_e error_code,
    output logic kv_ready,
    output logic read_done
);
logic validated_read_en;
logic read_allow;
logic [DATA_OFFSET_W-1:0] read_offset;
logic [DATA_OFFSET_W:0] num_dwords;
logic write_pad;
logic [31:0] pad_data;
assign num_dwords = DATA_WIDTH/32;
kv_read_rule_check kv_read_rules
(
    .clk         (clk                  ),
    .rst_b       (rst_b                ),
    .read_en_i   (read_ctrl_reg.read_en),
    .read_done   (read_done            ),
    .read_en_o   (validated_read_en    ),  
    .read_metrics(read_metrics         ),
    .read_allow  (read_allow           )
);
kv_fsm #(
    .DATA_WIDTH(DATA_WIDTH),
    .HMAC(HMAC),
    .PAD(PAD)
)
kv_read_fsm
(
    .clk(clk),
    .rst_b(rst_b),
    .zeroize(zeroize),
    .start(validated_read_en),
    .allow(read_allow),
    .last (kv_resp.last),
    .pcr_hash_extend(read_ctrl_reg.pcr_hash_extend),
    .num_dwords(num_dwords),
    .read_offset(read_offset),
    .write_en(write_en),
    .write_offset(write_offset),
    .write_pad(write_pad),
    .write_last(),
    .pad_data(pad_data),
    .ready(kv_ready),
    .done(read_done)
);
always_comb kv_read.read_entry = read_ctrl_reg.read_entry;
always_comb kv_read.read_offset = KV_ENTRY_SIZE_W'(read_offset);
always_comb write_data = write_pad ? pad_data : kv_resp.read_data;
always_ff @(posedge clk or negedge rst_b) begin
    if (!rst_b) begin
        error_code <= KV_SUCCESS;
    end
    else if (zeroize) begin
        error_code <= KV_SUCCESS;
    end
    else begin
        error_code <= validated_read_en && |write_offset && (error_code != KV_SUCCESS) ? error_code :
                      validated_read_en & ~read_allow ? KV_READ_FAIL :
                      validated_read_en & kv_resp.error ? KV_READ_FAIL : 
                      validated_read_en & ~kv_resp.error ? KV_SUCCESS : error_code;
    end
end
endmodule
module kv_write_client 
    import kv_defines_pkg::*;
    #(
    parameter DATA_WIDTH = 512
   ,parameter KV_WRITE_SWAP_DWORDS = 1 
   ,localparam DATA_OFFSET_W = $clog2(DATA_WIDTH/32)
   ,localparam DATA_NUM_DWORDS = (DATA_WIDTH/32)
)
(
    input logic clk,
    input logic rst_b,
    input logic zeroize,
    input logic [DATA_OFFSET_W:0] num_dwords,
    input kv_write_ctrl_reg_t write_ctrl_reg,
    input var kv_write_filter_metrics_t write_metrics,
    output kv_write_t kv_write,
    input  kv_wr_resp_t kv_resp,
    output logic dest_keyvault,
    input logic dest_data_avail,
    input logic [DATA_NUM_DWORDS-1:0][31:0] dest_data,
    output kv_error_code_e error_code,
    output logic kv_ready,
    output logic dest_done
);
logic write_allow;
logic [DATA_OFFSET_W-1:0] dest_read_offset;
logic [DATA_OFFSET_W-1:0] dest_write_offset;
logic dest_write_en;
logic [31:0] pad_data;
logic write_pad;
logic write_last;
kv_write_rule_check kv_write_rules
(
    .clk  (clk  ),
    .rst_b(rst_b),
    .write_metrics(write_metrics),
    .write_allow  (write_allow  )
);
kv_fsm #(
    .DATA_WIDTH(DATA_WIDTH),
    .PAD(0)
)
kv_dest_write_fsm
(
    .clk(clk),
    .rst_b(rst_b),
    .zeroize(zeroize),
    .start(dest_data_avail & write_ctrl_reg.write_en),
    .allow(write_allow),
    .last('0),
    .pcr_hash_extend(1'b0),
    .num_dwords(num_dwords),
    .read_offset(dest_read_offset),
    .write_en(dest_write_en),
    .write_offset(dest_write_offset),
    .write_pad(write_pad),
    .write_last(write_last),
    .pad_data(pad_data),
    .ready(kv_ready),
    .done(dest_done)
);
always_comb dest_keyvault = write_ctrl_reg.write_en;
always_comb kv_write.write_entry = write_ctrl_reg.write_entry;
always_comb kv_write.write_offset = KV_ENTRY_SIZE_W'(dest_write_offset);
always_comb kv_write.write_en = dest_write_en;
always_comb kv_write.write_data = KV_WRITE_SWAP_DWORDS ? dest_data[(DATA_NUM_DWORDS-1) - dest_read_offset] : dest_data[dest_read_offset];
always_comb kv_write.write_dest_valid = write_last ? write_ctrl_reg.write_dest_vld : '0;
always_ff @(posedge clk or negedge rst_b) begin
    if (!rst_b) begin
        error_code <= KV_SUCCESS;
    end
    else if (zeroize) begin
        error_code <= KV_SUCCESS;
    end
    else begin
        error_code <= dest_write_en && |dest_write_offset && (error_code != KV_SUCCESS) ? error_code : 
                      dest_data_avail & write_ctrl_reg.write_en & !write_allow ? KV_WRITE_FAIL :
                      dest_write_en & kv_resp.error ? KV_WRITE_FAIL : 
                      dest_write_en & ~kv_resp.error ? KV_SUCCESS : error_code;
    end
end
endmodule
module kv_read_rule_check
import kv_defines_pkg::*;
(
    input logic clk,
    input logic rst_b,
    input  logic                        read_en_i,
    input  logic                        read_done,
    output logic                        read_en_o,  
    input  var kv_read_filter_metrics_t read_metrics,
    output logic                        read_allow
);
    struct packed {
        logic no_read_key_release;  
    } rule_fail;
    always_comb begin
        rule_fail.no_read_key_release = read_metrics.ocp_lock_in_progress &&
                                        read_metrics.kv_read_dest != (8'h1 << KV_DEST_IDX_DMA_DATA) &&
                                        read_metrics.kv_key_entry == OCP_LOCK_KEY_RELEASE_KV_SLOT;
    end
    always_ff@(posedge clk or negedge rst_b) begin
        if (!rst_b) begin
            read_allow <= 1'b0;
            read_en_o  <= 1'b0;
        end
        else if (read_done) begin
            read_allow <= 1'b0;
            read_en_o  <= 1'b0;
        end
        else if (read_en_i) begin
            read_allow <= ~|rule_fail;
            read_en_o  <= 1'b1;
        end
        else begin
            read_allow <= read_allow;
            read_en_o  <= 1'b0;
        end
    end
endmodule
module kv_write_rule_check
import kv_defines_pkg::*;
(
    input logic clk,
    input logic rst_b,
    input  var kv_write_filter_metrics_t write_metrics,
    output logic                         write_allow
);
    struct packed {
        logic aes_only_to_key_release;  
        logic std_to_std;  
        logic lock_to_lock;  
        logic aes_dec_to_rt_obf_key;
    } rule_fail;
    always_comb begin
        rule_fail.aes_only_to_key_release = write_metrics.ocp_lock_in_progress &&
                                          |(write_metrics.kv_write_src & ~(KV_NUM_WRITE'(1) << KV_WRITE_IDX_AES)) &&
                                            write_metrics.kv_write_entry == OCP_LOCK_KEY_RELEASE_KV_SLOT;
    end
    always_comb begin
        rule_fail.std_to_std = write_metrics.ocp_lock_in_progress &&
                             ((write_metrics.kv_data0_present &&
                               write_metrics.kv_data0_entry   inside {[KV_STANDARD_SLOT_LOW:KV_STANDARD_SLOT_HI]}) ||
                              (write_metrics.kv_data1_present &&
                               write_metrics.kv_data1_entry   inside {[KV_STANDARD_SLOT_LOW:KV_STANDARD_SLOT_HI]})) &&
                             !(write_metrics.kv_write_entry inside {[KV_STANDARD_SLOT_LOW:KV_STANDARD_SLOT_HI]});
    end
    always_comb begin
        rule_fail.lock_to_lock = write_metrics.ocp_lock_in_progress &&
                               ((write_metrics.kv_data0_present &&
                                 write_metrics.kv_data0_entry   inside {[KV_OCP_LOCK_SLOT_LOW:KV_OCP_LOCK_SLOT_HI]}) ||
                                (write_metrics.kv_data1_present &&
                                 write_metrics.kv_data1_entry   inside {[KV_OCP_LOCK_SLOT_LOW:KV_OCP_LOCK_SLOT_HI]})) &&
                               !(write_metrics.kv_write_entry inside {[KV_OCP_LOCK_SLOT_LOW:KV_OCP_LOCK_SLOT_HI]});
    end
    always_comb begin
        rule_fail.aes_dec_to_rt_obf_key = write_metrics.kv_write_src[KV_WRITE_IDX_AES] &&
                                          (!write_metrics.ocp_lock_in_progress ||
                                           !write_metrics.aes_decrypt_ecb_op ||
                                           !write_metrics.kv_data0_present ||
                                            write_metrics.kv_data0_entry != OCP_LOCK_RT_OBF_KEY_KV_SLOT ||
                                            write_metrics.kv_write_entry != OCP_LOCK_KEY_RELEASE_KV_SLOT);
    end
    always_ff@(posedge clk or negedge rst_b) begin
        if (!rst_b) begin
            write_allow <= 1'b0;
        end
        else begin
            write_allow <= ~|rule_fail;
        end
    end
endmodule
package pv_reg_pkg;
    localparam PV_REG_DATA_WIDTH = 32;
    localparam PV_REG_MIN_ADDR_WIDTH = 12;
    typedef struct packed{
        logic swwel;
    } pv_reg__pvCtrl__lock__in_t;
    typedef struct packed{
        logic swwel;
    } pv_reg__pvCtrl__clear__in_t;
    typedef struct packed{
        logic hwclr;
    } pv_reg__pvCtrl__rsvd0__in_t;
    typedef struct packed{
        pv_reg__pvCtrl__lock__in_t lock;
        pv_reg__pvCtrl__clear__in_t clear;
        pv_reg__pvCtrl__rsvd0__in_t rsvd0;
    } pv_reg__pvCtrl__in_t;
    typedef struct packed{
        logic [31:0] next;
        logic we;
        logic hwclr;
    } pv_reg__pcr_w32__in_t;
    typedef struct packed{
        pv_reg__pcr_w32__in_t data;
    } pv_reg__pcrReg__in_t;
    typedef struct packed{
        logic reset_b;
        logic core_only_rst_b;
        logic hard_reset_b;
        pv_reg__pvCtrl__in_t [32-1:0]PCR_CTRL;
        pv_reg__pcrReg__in_t [32-1:0][12-1:0]PCR_ENTRY;
    } pv_reg__in_t;
    typedef struct packed{
        logic value;
    } pv_reg__pvCtrl__lock__out_t;
    typedef struct packed{
        logic value;
    } pv_reg__pvCtrl__clear__out_t;
    typedef struct packed{
        logic value;
    } pv_reg__pvCtrl__rsvd0__out_t;
    typedef struct packed{
        logic [4:0] value;
    } pv_reg__pvCtrl__rsvd1__out_t;
    typedef struct packed{
        pv_reg__pvCtrl__lock__out_t lock;
        pv_reg__pvCtrl__clear__out_t clear;
        pv_reg__pvCtrl__rsvd0__out_t rsvd0;
        pv_reg__pvCtrl__rsvd1__out_t rsvd1;
    } pv_reg__pvCtrl__out_t;
    typedef struct packed{
        logic [31:0] value;
    } pv_reg__pcr_w32__out_t;
    typedef struct packed{
        pv_reg__pcr_w32__out_t data;
    } pv_reg__pcrReg__out_t;
    typedef struct packed{
        pv_reg__pvCtrl__out_t [32-1:0]PCR_CTRL;
        pv_reg__pcrReg__out_t [32-1:0][12-1:0]PCR_ENTRY;
    } pv_reg__out_t;
    localparam PV_REG_ADDR_WIDTH = 32'd12;
endpackage
module pv_reg (
        input wire clk,
        input wire rst,
        input wire s_cpuif_req,
        input wire s_cpuif_req_is_wr,
        input wire [11:0] s_cpuif_addr,
        input wire [31:0] s_cpuif_wr_data,
        input wire [31:0] s_cpuif_wr_biten,
        output wire s_cpuif_req_stall_wr,
        output wire s_cpuif_req_stall_rd,
        output wire s_cpuif_rd_ack,
        output wire s_cpuif_rd_err,
        output wire [31:0] s_cpuif_rd_data,
        output wire s_cpuif_wr_ack,
        output wire s_cpuif_wr_err,
        input pv_reg_pkg::pv_reg__in_t hwif_in,
        output pv_reg_pkg::pv_reg__out_t hwif_out
    );
    logic cpuif_req;
    logic cpuif_req_is_wr;
    logic [11:0] cpuif_addr;
    logic [31:0] cpuif_wr_data;
    logic [31:0] cpuif_wr_biten;
    logic cpuif_req_stall_wr;
    logic cpuif_req_stall_rd;
    logic cpuif_rd_ack;
    logic cpuif_rd_err;
    logic [31:0] cpuif_rd_data;
    logic cpuif_wr_ack;
    logic cpuif_wr_err;
    assign cpuif_req = s_cpuif_req;
    assign cpuif_req_is_wr = s_cpuif_req_is_wr;
    assign cpuif_addr = s_cpuif_addr;
    assign cpuif_wr_data = s_cpuif_wr_data;
    assign cpuif_wr_biten = s_cpuif_wr_biten;
    assign s_cpuif_req_stall_wr = cpuif_req_stall_wr;
    assign s_cpuif_req_stall_rd = cpuif_req_stall_rd;
    assign s_cpuif_rd_ack = cpuif_rd_ack;
    assign s_cpuif_rd_err = cpuif_rd_err;
    assign s_cpuif_rd_data = cpuif_rd_data;
    assign s_cpuif_wr_ack = cpuif_wr_ack;
    assign s_cpuif_wr_err = cpuif_wr_err;
    logic cpuif_req_masked;
    assign cpuif_req_stall_rd = '0;
    assign cpuif_req_stall_wr = '0;
    assign cpuif_req_masked = cpuif_req
                            & !(!cpuif_req_is_wr & cpuif_req_stall_rd)
                            & !(cpuif_req_is_wr & cpuif_req_stall_wr);
    typedef struct packed{
        logic [32-1:0]PCR_CTRL;
        logic [32-1:0][12-1:0]PCR_ENTRY;
    } decoded_reg_strb_t;
    decoded_reg_strb_t decoded_reg_strb;
    logic decoded_req;
    logic decoded_req_is_wr;
    logic [31:0] decoded_wr_data;
    logic [31:0] decoded_wr_biten;
    always_comb begin
        for(int i0=0; i0<32; i0++) begin
            decoded_reg_strb.PCR_CTRL[i0] = cpuif_req_masked & (cpuif_addr == 12'h0 + i0*12'h4);
        end
        for(int i0=0; i0<32; i0++) begin
            for(int i1=0; i1<12; i1++) begin
                decoded_reg_strb.PCR_ENTRY[i0][i1] = cpuif_req_masked & (cpuif_addr == 12'h600 + i0*12'h30 + i1*12'h4);
            end
        end
    end
    assign decoded_req = cpuif_req_masked;
    assign decoded_req_is_wr = cpuif_req_is_wr;
    assign decoded_wr_data = cpuif_wr_data;
    assign decoded_wr_biten = cpuif_wr_biten;
    typedef struct packed{
        struct packed{
            struct packed{
                logic next;
                logic load_next;
            } lock;
            struct packed{
                logic next;
                logic load_next;
            } clear;
            struct packed{
                logic next;
                logic load_next;
            } rsvd0;
            struct packed{
                logic [4:0] next;
                logic load_next;
            } rsvd1;
        } [32-1:0]PCR_CTRL;
        struct packed{
            struct packed{
                logic [31:0] next;
                logic load_next;
            } data;
        } [32-1:0][12-1:0]PCR_ENTRY;
    } field_combo_t;
    field_combo_t field_combo;
    typedef struct packed{
        struct packed{
            struct packed{
                logic value;
            } lock;
            struct packed{
                logic value;
            } clear;
            struct packed{
                logic value;
            } rsvd0;
            struct packed{
                logic [4:0] value;
            } rsvd1;
        } [32-1:0]PCR_CTRL;
        struct packed{
            struct packed{
                logic [31:0] value;
            } data;
        } [32-1:0][12-1:0]PCR_ENTRY;
    } field_storage_t;
    field_storage_t field_storage;
    for(genvar i0=0; i0<32; i0++) begin
        always_comb begin
            automatic logic [0:0] next_c;
            automatic logic load_next_c;
            next_c = field_storage.PCR_CTRL[i0].lock.value;
            load_next_c = '0;
            if(decoded_reg_strb.PCR_CTRL[i0] && decoded_req_is_wr && !(hwif_in.PCR_CTRL[i0].lock.swwel)) begin  
