module sha512_w_mem(
                    input wire            clk,
                    input wire            reset_n,
                    input wire            zeroize,
                    input wire [1023 : 0] block_msg,
                    input wire            init_cmd,
                    input wire            next_cmd,
                    output wire [63 : 0]  w_val
                   );
  reg [63 : 0] w_mem [0 : 15];
  reg [63 : 0] w_mem00_new;
  reg [63 : 0] w_mem01_new;
  reg [63 : 0] w_mem02_new;
  reg [63 : 0] w_mem03_new;
  reg [63 : 0] w_mem04_new;
  reg [63 : 0] w_mem05_new;
  reg [63 : 0] w_mem06_new;
  reg [63 : 0] w_mem07_new;
  reg [63 : 0] w_mem08_new;
  reg [63 : 0] w_mem09_new;
  reg [63 : 0] w_mem10_new;
  reg [63 : 0] w_mem11_new;
  reg [63 : 0] w_mem12_new;
  reg [63 : 0] w_mem13_new;
  reg [63 : 0] w_mem14_new;
  reg [63 : 0] w_mem15_new;
  reg          w_mem_we;
  reg [6 : 0] w_ctr_reg;
  reg [6 : 0] w_ctr_new;
  reg         w_ctr_we;
  reg [63 : 0] w_tmp;
  reg [63 : 0] w_new;
  assign w_val = w_tmp;
  always @ (posedge clk or negedge reset_n)
    begin : reg_update
      integer ii;
      if (!reset_n) begin
        for (ii = 0; ii < 16; ii = ii + 1)
          w_mem[ii] <= 64'h0;
        w_ctr_reg <= 7'h0;
      end
      else begin
        if (zeroize) begin
          for (ii = 0; ii < 16; ii = ii + 1)
            w_mem[ii] <= 64'h0;
          w_ctr_reg <= 7'h0;
        end
        else begin
          if (w_mem_we)
            begin
              w_mem[00] <= w_mem00_new;
              w_mem[01] <= w_mem01_new;
              w_mem[02] <= w_mem02_new;
              w_mem[03] <= w_mem03_new;
              w_mem[04] <= w_mem04_new;
              w_mem[05] <= w_mem05_new;
              w_mem[06] <= w_mem06_new;
              w_mem[07] <= w_mem07_new;
              w_mem[08] <= w_mem08_new;
              w_mem[09] <= w_mem09_new;
              w_mem[10] <= w_mem10_new;
              w_mem[11] <= w_mem11_new;
              w_mem[12] <= w_mem12_new;
              w_mem[13] <= w_mem13_new;
              w_mem[14] <= w_mem14_new;
              w_mem[15] <= w_mem15_new;
            end
          if (w_ctr_we)
              w_ctr_reg <= w_ctr_new;
        end
      end
    end  
  always @*
    begin : select_w
      if (w_ctr_reg < 16)
        w_tmp = w_mem[w_ctr_reg[3 : 0]];
      else
        w_tmp = w_new;
    end  
  always @*
    begin : w_mem_update_logic
      reg [63 : 0] w_0;
      reg [63 : 0] w_1;
      reg [63 : 0] w_9;
      reg [63 : 0] w_14;
      reg [63 : 0] d0;
      reg [63 : 0] d1;
      w_mem00_new = 64'h0;
      w_mem01_new = 64'h0;
      w_mem02_new = 64'h0;
      w_mem03_new = 64'h0;
      w_mem04_new = 64'h0;
      w_mem05_new = 64'h0;
      w_mem06_new = 64'h0;
      w_mem07_new = 64'h0;
      w_mem08_new = 64'h0;
      w_mem09_new = 64'h0;
      w_mem10_new = 64'h0;
      w_mem11_new = 64'h0;
      w_mem12_new = 64'h0;
      w_mem13_new = 64'h0;
      w_mem14_new = 64'h0;
      w_mem15_new = 64'h0;
      w_mem_we    = 0;
      w_0  = w_mem[0];
      w_1  = w_mem[1];
      w_9  = w_mem[9];
      w_14 = w_mem[14];
      d0 = {w_1[0],     w_1[63 : 1]} ^  
           {w_1[7 : 0], w_1[63 : 8]} ^  
           {7'b0000000, w_1[63 : 7]};   
      d1 = {w_14[18 : 0], w_14[63 : 19]} ^  
           {w_14[60 : 0], w_14[63 : 61]} ^  
           {6'b000000,    w_14[63 : 6]};    
      w_new = w_0 + d0 + w_9 + d1;
      if (init_cmd)
        begin
          w_mem00_new = block_msg[1023 : 960];
          w_mem01_new = block_msg[959  : 896];
          w_mem02_new = block_msg[895  : 832];
          w_mem03_new = block_msg[831  : 768];
          w_mem04_new = block_msg[767  : 704];
          w_mem05_new = block_msg[703  : 640];
          w_mem06_new = block_msg[639  : 576];
          w_mem07_new = block_msg[575  : 512];
          w_mem08_new = block_msg[511  : 448];
          w_mem09_new = block_msg[447  : 384];
          w_mem10_new = block_msg[383  : 320];
          w_mem11_new = block_msg[319  : 256];
          w_mem12_new = block_msg[255  : 192];
          w_mem13_new = block_msg[191  : 128];
          w_mem14_new = block_msg[127  :  64];
          w_mem15_new = block_msg[63   :   0];
          w_mem_we    = 1;
        end
      if (next_cmd && (w_ctr_reg > 15))
        begin
          w_mem00_new = w_mem[01];
          w_mem01_new = w_mem[02];
          w_mem02_new = w_mem[03];
          w_mem03_new = w_mem[04];
          w_mem04_new = w_mem[05];
          w_mem05_new = w_mem[06];
          w_mem06_new = w_mem[07];
          w_mem07_new = w_mem[08];
          w_mem08_new = w_mem[09];
          w_mem09_new = w_mem[10];
          w_mem10_new = w_mem[11];
          w_mem11_new = w_mem[12];
          w_mem12_new = w_mem[13];
          w_mem13_new = w_mem[14];
          w_mem14_new = w_mem[15];
          w_mem15_new = w_new;
          w_mem_we    = 1;
        end
    end  
  always @*
    begin : w_ctr
      w_ctr_new = 7'h0;
      w_ctr_we  = 1'h0;
      if (init_cmd)
        begin
          w_ctr_new = 7'h00;
          w_ctr_we  = 1'h1;
        end
      if (next_cmd)
        begin
          w_ctr_new = w_ctr_reg + 7'h01;
          w_ctr_we  = 1'h1;
        end
    end  
endmodule  
module sha512_reg (
        input wire clk,
        input wire rst,
        input wire s_cpuif_req,
        input wire s_cpuif_req_is_wr,
        input wire [11:0] s_cpuif_addr,
        input wire [31:0] s_cpuif_wr_data,
        input wire [31:0] s_cpuif_wr_biten,
        output wire s_cpuif_req_stall_wr,
        output wire s_cpuif_req_stall_rd,
        output wire s_cpuif_rd_ack,
        output wire s_cpuif_rd_err,
        output wire [31:0] s_cpuif_rd_data,
        output wire s_cpuif_wr_ack,
        output wire s_cpuif_wr_err,
        input sha512_reg_pkg::sha512_reg__in_t hwif_in,
        output sha512_reg_pkg::sha512_reg__out_t hwif_out
    );
    logic cpuif_req;
    logic cpuif_req_is_wr;
    logic [11:0] cpuif_addr;
    logic [31:0] cpuif_wr_data;
    logic [31:0] cpuif_wr_biten;
    logic cpuif_req_stall_wr;
    logic cpuif_req_stall_rd;
    logic cpuif_rd_ack;
    logic cpuif_rd_err;
    logic [31:0] cpuif_rd_data;
    logic cpuif_wr_ack;
    logic cpuif_wr_err;
    assign cpuif_req = s_cpuif_req;
    assign cpuif_req_is_wr = s_cpuif_req_is_wr;
    assign cpuif_addr = s_cpuif_addr;
    assign cpuif_wr_data = s_cpuif_wr_data;
    assign cpuif_wr_biten = s_cpuif_wr_biten;
    assign s_cpuif_req_stall_wr = cpuif_req_stall_wr;
    assign s_cpuif_req_stall_rd = cpuif_req_stall_rd;
    assign s_cpuif_rd_ack = cpuif_rd_ack;
    assign s_cpuif_rd_err = cpuif_rd_err;
    assign s_cpuif_rd_data = cpuif_rd_data;
    assign s_cpuif_wr_ack = cpuif_wr_ack;
    assign s_cpuif_wr_err = cpuif_wr_err;
    logic cpuif_req_masked;
    assign cpuif_req_stall_rd = '0;
    assign cpuif_req_stall_wr = '0;
    assign cpuif_req_masked = cpuif_req
                            & !(!cpuif_req_is_wr & cpuif_req_stall_rd)
                            & !(cpuif_req_is_wr & cpuif_req_stall_wr);
    typedef struct packed{
        logic [2-1:0]SHA512_NAME;
        logic [2-1:0]SHA512_VERSION;
        logic SHA512_CTRL;
        logic SHA512_STATUS;
        logic [32-1:0]SHA512_BLOCK;
        logic [16-1:0]SHA512_DIGEST;
        logic SHA512_VAULT_RD_CTRL;
        logic SHA512_VAULT_RD_STATUS;
        logic SHA512_KV_WR_CTRL;
        logic SHA512_KV_WR_STATUS;
        logic [8-1:0]SHA512_GEN_PCR_HASH_NONCE;
        logic SHA512_GEN_PCR_HASH_CTRL;
        logic SHA512_GEN_PCR_HASH_STATUS;
        logic [16-1:0]SHA512_GEN_PCR_HASH_DIGEST;
        struct packed{
            logic global_intr_en_r;
            logic error_intr_en_r;
            logic notif_intr_en_r;
