module sha256_w_mem(
                    input wire           clk,
                    input wire           reset_n,
                    input wire           zeroize,
                    input wire [511 : 0] block_msg,
                    input wire           init_cmd,
                    input wire           next_cmd,
                    output wire [31 : 0] w_val
                   );
  reg [31 : 0] w_mem [0 : 15];
  reg [31 : 0] w_mem00_new;
  reg [31 : 0] w_mem01_new;
  reg [31 : 0] w_mem02_new;
  reg [31 : 0] w_mem03_new;
  reg [31 : 0] w_mem04_new;
  reg [31 : 0] w_mem05_new;
  reg [31 : 0] w_mem06_new;
  reg [31 : 0] w_mem07_new;
  reg [31 : 0] w_mem08_new;
  reg [31 : 0] w_mem09_new;
  reg [31 : 0] w_mem10_new;
  reg [31 : 0] w_mem11_new;
  reg [31 : 0] w_mem12_new;
  reg [31 : 0] w_mem13_new;
  reg [31 : 0] w_mem14_new;
  reg [31 : 0] w_mem15_new;
  reg          w_mem_we;
  reg [5 : 0] w_ctr_reg;
  reg [5 : 0] w_ctr_new;
  reg         w_ctr_we;
  reg [31 : 0] w_tmp;
  reg [31 : 0] w_new;
  assign w_val = w_tmp;
  always @ (posedge clk or negedge reset_n)
    begin : reg_update
      integer ii;
      if (!reset_n)
        begin
          for (ii = 0 ; ii < 16 ; ii = ii + 1)
            w_mem[ii] <= 32'h0;
          w_ctr_reg <= 6'h0;
        end
      else if (zeroize)
        begin
          for (ii = 0 ; ii < 16 ; ii = ii + 1)
            w_mem[ii] <= 32'h0;
          w_ctr_reg <= 6'h0;
        end
      else
        begin
          if (w_mem_we)
            begin
              w_mem[00] <= w_mem00_new;
              w_mem[01] <= w_mem01_new;
              w_mem[02] <= w_mem02_new;
              w_mem[03] <= w_mem03_new;
              w_mem[04] <= w_mem04_new;
              w_mem[05] <= w_mem05_new;
              w_mem[06] <= w_mem06_new;
              w_mem[07] <= w_mem07_new;
              w_mem[08] <= w_mem08_new;
              w_mem[09] <= w_mem09_new;
              w_mem[10] <= w_mem10_new;
              w_mem[11] <= w_mem11_new;
              w_mem[12] <= w_mem12_new;
              w_mem[13] <= w_mem13_new;
              w_mem[14] <= w_mem14_new;
              w_mem[15] <= w_mem15_new;
            end
          if (w_ctr_we)
            w_ctr_reg <= w_ctr_new;
        end
    end  
  always @*
    begin : select_w
      if (w_ctr_reg < 16)
        w_tmp = w_mem[w_ctr_reg[3 : 0]];
      else
        w_tmp = w_new;
    end  
  always @*
    begin : w_mem_update_logic
      reg [31 : 0] w_0;
      reg [31 : 0] w_1;
      reg [31 : 0] w_9;
      reg [31 : 0] w_14;
      reg [31 : 0] d0;
      reg [31 : 0] d1;
      w_mem00_new = 32'h0;
      w_mem01_new = 32'h0;
      w_mem02_new = 32'h0;
      w_mem03_new = 32'h0;
      w_mem04_new = 32'h0;
      w_mem05_new = 32'h0;
      w_mem06_new = 32'h0;
      w_mem07_new = 32'h0;
      w_mem08_new = 32'h0;
      w_mem09_new = 32'h0;
      w_mem10_new = 32'h0;
      w_mem11_new = 32'h0;
      w_mem12_new = 32'h0;
      w_mem13_new = 32'h0;
      w_mem14_new = 32'h0;
      w_mem15_new = 32'h0;
      w_mem_we    = 0;
      w_0  = w_mem[0];
      w_1  = w_mem[1];
      w_9  = w_mem[9];
      w_14 = w_mem[14];
      d0 = {w_1[6  : 0], w_1[31 :  7]} ^
           {w_1[17 : 0], w_1[31 : 18]} ^
           {3'b000, w_1[31 : 3]};
      d1 = {w_14[16 : 0], w_14[31 : 17]} ^
           {w_14[18 : 0], w_14[31 : 19]} ^
           {10'b0000000000, w_14[31 : 10]};
      w_new = d1 + w_9 + d0 + w_0;
      if (init_cmd)
        begin
          w_mem00_new = block_msg[511 : 480];
          w_mem01_new = block_msg[479 : 448];
          w_mem02_new = block_msg[447 : 416];
          w_mem03_new = block_msg[415 : 384];
          w_mem04_new = block_msg[383 : 352];
          w_mem05_new = block_msg[351 : 320];
          w_mem06_new = block_msg[319 : 288];
          w_mem07_new = block_msg[287 : 256];
          w_mem08_new = block_msg[255 : 224];
          w_mem09_new = block_msg[223 : 192];
          w_mem10_new = block_msg[191 : 160];
          w_mem11_new = block_msg[159 : 128];
          w_mem12_new = block_msg[127 :  96];
          w_mem13_new = block_msg[95  :  64];
          w_mem14_new = block_msg[63  :  32];
          w_mem15_new = block_msg[31  :   0];
          w_mem_we    = 1;
        end
      if (next_cmd && (w_ctr_reg > 15))
        begin
          w_mem00_new = w_mem[01];
          w_mem01_new = w_mem[02];
          w_mem02_new = w_mem[03];
          w_mem03_new = w_mem[04];
          w_mem04_new = w_mem[05];
          w_mem05_new = w_mem[06];
          w_mem06_new = w_mem[07];
          w_mem07_new = w_mem[08];
          w_mem08_new = w_mem[09];
          w_mem09_new = w_mem[10];
          w_mem10_new = w_mem[11];
          w_mem11_new = w_mem[12];
          w_mem12_new = w_mem[13];
          w_mem13_new = w_mem[14];
          w_mem14_new = w_mem[15];
          w_mem15_new = w_new;
          w_mem_we    = 1;
        end
    end  
  always @*
    begin : w_ctr
      w_ctr_new = 6'h0;
      w_ctr_we  = 1'h0;
      if (init_cmd)
        begin
          w_ctr_new = 6'h0;
          w_ctr_we  = 1'h1;
        end
      if (next_cmd)
        begin
          w_ctr_new = w_ctr_reg + 6'h01;
          w_ctr_we  = 1'h1;
        end
    end  
endmodule  
