endmodule
module abr_ram_regout #(
     parameter DEPTH      = 64
    ,parameter DATA_WIDTH = 32
    ,parameter NUM_RD_PORTS = 1
    ,parameter NUM_WR_PORTS = 1
    ,parameter ADDR_WIDTH = $clog2(DEPTH)
    )
    (
    input  logic                                    clk_i,
    input  logic                                    zeroize_i,
    input  logic [NUM_WR_PORTS-1:0]                 we_i,
    input  logic [NUM_WR_PORTS-1:0][ADDR_WIDTH-1:0] waddr_i,
    input  logic [NUM_WR_PORTS-1:0][DATA_WIDTH-1:0] wdata_i,
    input  logic [NUM_RD_PORTS-1:0]                 re_i,
    input  logic [NUM_RD_PORTS-1:0][ADDR_WIDTH-1:0] raddr_i,
    output logic [NUM_RD_PORTS-1:0][DATA_WIDTH-1:0] rdata_o,
    output logic [DEPTH-1:0][DATA_WIDTH-1:0]        reg_o
    );
    logic [DEPTH-1:0][DATA_WIDTH-1:0] ram;
    always @(posedge clk_i) begin
        if (zeroize_i) begin
            ram <= '0;
        end
        else begin
            for (int port = 0; port < NUM_WR_PORTS; port++) begin
                if (we_i[port]) begin
                    ram[waddr_i[port]] <= wdata_i[port];
                end
            end
        end
    end
    always @(posedge clk_i) begin
        for (int port = 0; port < NUM_RD_PORTS; port++) begin
            if (re_i[port]) begin
                rdata_o[port] <= ram[raddr_i[port]];
            end
        end
    end
    assign reg_o = ram;
endmodule
    module abr_clk_gate (
        input logic clk,
        input logic en,
        output clk_cg
    );
        logic en_lat;
        always_latch begin
            if(!clk) begin
                en_lat = en;
            end
        end
        assign clk_cg = clk && en_lat;
    endmodule
module abr_2ff_sync  #( parameter WIDTH=1,
                             parameter RST_VAL=0)
    (
    input logic clk,
    input logic rst_b,
    input logic [WIDTH-1:0] din,
    output logic [WIDTH-1:0] dout
);
logic din_ff;
always_ff@(posedge clk or negedge rst_b) begin
    if(!rst_b) begin
        dout <= RST_VAL;
        din_ff <= RST_VAL;
    end
    else begin 
        din_ff <= din;
        dout <= din_ff;
    end
end
endmodule
module abr_piso_multi #(
  parameter int NUM_MODES = 5,
  parameter int PISO_BUFFER_W = 1344,
  parameter int PISO_PTR_W = $clog2(PISO_BUFFER_W),
  parameter int PISO_ACT_INPUT_RATE = 1088,
  parameter int PISO_ACT_OUTPUT_RATE = 80,
  parameter int INPUT_RATES [NUM_MODES] = '{1088, 1088, 1088, 1088, 1088},
  parameter int OUTPUT_RATES[NUM_MODES] = '{80, 80, 80, 80, 80}
)(
  input  logic                          clk,
  input  logic                          rst_b,
  input  logic                          zeroize,
  input  logic [$clog2(NUM_MODES)-1:0]  mode,
  input  logic                          valid_i,
  output logic                          hold_o,
  input  logic [PISO_ACT_INPUT_RATE-1:0] data_i,
  output logic                          valid_o,
  input  logic                          hold_i,
  output logic [PISO_ACT_OUTPUT_RATE-1:0] data_o
);
  localparam BUFFER_W_DELTA = PISO_BUFFER_W - PISO_ACT_INPUT_RATE;
  logic [PISO_BUFFER_W-1:0] buffer, buffer_d;
  logic [PISO_PTR_W-1:0] buffer_wr_ptr, buffer_wr_ptr_d;
  logic [PISO_PTR_W-1:0] current_input_rate, current_output_rate;
  logic buffer_wr, buffer_rd;
  logic update_buffer;
  always_comb begin
    current_input_rate  = INPUT_RATES[mode][PISO_PTR_W-1:0];
    current_output_rate = OUTPUT_RATES[mode][PISO_PTR_W-1:0];
  end
  always_comb hold_o  = buffer_wr_ptr > (PISO_BUFFER_W[PISO_PTR_W-1:0] - current_input_rate);
  always_comb data_o  = buffer[PISO_ACT_OUTPUT_RATE-1:0];
  always_comb valid_o = buffer_wr_ptr >= current_output_rate;
  always_comb buffer_wr = valid_i & ~hold_o;
  always_comb buffer_rd = valid_o & ~hold_i;
  always_comb update_buffer = buffer_rd | buffer_wr;
  always_ff @(posedge clk or negedge rst_b) begin
    if (!rst_b) begin
      buffer <= '0;
      buffer_wr_ptr <= '0;
    end else if (zeroize) begin
      buffer <= '0;
      buffer_wr_ptr <= '0;
    end else if (update_buffer) begin
      buffer <= buffer_d;
      buffer_wr_ptr <= buffer_wr_ptr_d;
    end
  end
  always_comb begin
    unique case ({buffer_rd, buffer_wr})
      2'b00 : buffer_wr_ptr_d = buffer_wr_ptr;
      2'b01 : buffer_wr_ptr_d = buffer_wr_ptr + current_input_rate;
      2'b10 : buffer_wr_ptr_d = buffer_wr_ptr - current_output_rate;
      2'b11 : buffer_wr_ptr_d = buffer_wr_ptr + (current_input_rate - current_output_rate);
      default : buffer_wr_ptr_d = buffer_wr_ptr;
    endcase
  end
  logic [PISO_BUFFER_W-1:0] buffer_wdata;
  logic [PISO_BUFFER_W-1:0] buffer_wdata_mask;
  always_comb begin
    buffer_wdata = '0;
    buffer_wdata_mask = '1;
    buffer_wdata_mask = PISO_BUFFER_W'(buffer_wdata_mask >> (PISO_BUFFER_W[PISO_PTR_W-1:0] - current_input_rate));
    buffer_wdata = {{BUFFER_W_DELTA{1'b0}}, data_i} & buffer_wdata_mask;
  end
  always_comb begin
    unique case ({buffer_rd, buffer_wr})
      2'b00 : buffer_d = buffer;
      2'b10 : buffer_d = PISO_BUFFER_W'(buffer >> current_output_rate);
      2'b01 : buffer_d = PISO_BUFFER_W'(buffer_wdata << buffer_wr_ptr) | buffer;
      2'b11 : buffer_d = PISO_BUFFER_W'(buffer_wdata << (buffer_wr_ptr - current_output_rate)) |
                         PISO_BUFFER_W'(buffer >> current_output_rate);
      default : buffer_d = buffer;
    endcase
  end
endmodule
module abr_piso
  #( parameter PISO_BUFFER_W    = 1344
    ,parameter PISO_PTR_W = $clog2(PISO_BUFFER_W)
    ,parameter PISO_INPUT_RATE = 1088
    ,parameter PISO_OUTPUT_RATE = 80
  )
  (
    input logic                          clk,
    input logic                          rst_b,
    input logic                          zeroize,
    input  logic                             valid_i,
    output logic                             hold_o,
    input  logic [PISO_INPUT_RATE-1:0]   data_i,
    output logic                             valid_o,
    input  logic                             hold_i,
    output logic [PISO_OUTPUT_RATE-1:0]  data_o
  );
  parameter BUFFER_W_DELTA = PISO_BUFFER_W - PISO_INPUT_RATE;
  logic [PISO_BUFFER_W-1:0] buffer, buffer_d;
  logic [PISO_PTR_W-1:0] buffer_wr_ptr, buffer_wr_ptr_d;
  logic [PISO_PTR_W-1:0] current_input_rate, current_output_rate;
  logic buffer_wr, buffer_rd;
  logic update_buffer;
  always_comb current_input_rate = PISO_INPUT_RATE;
  always_comb current_output_rate = PISO_OUTPUT_RATE;
  always_comb hold_o = buffer_wr_ptr > (PISO_BUFFER_W[PISO_PTR_W-1:0] - current_input_rate);
  always_comb data_o = buffer[PISO_OUTPUT_RATE-1:0];
  always_comb valid_o = buffer_wr_ptr >= current_output_rate;
  always_comb buffer_wr = valid_i & ~hold_o;
  always_comb buffer_rd = valid_o & ~hold_i;
  always_comb update_buffer = buffer_rd | buffer_wr;
  always_ff @(posedge clk or negedge rst_b) begin
    if (!rst_b) begin
      buffer <= '0;
      buffer_wr_ptr <= '0;
    end else if (zeroize) begin
      buffer <= '0;
      buffer_wr_ptr <= '0;
    end else if (update_buffer) begin
      buffer <= buffer_d;
      buffer_wr_ptr <= buffer_wr_ptr_d;
    end 
  end
  always_comb begin
    unique case ({buffer_rd, buffer_wr}) 
      2'b00 : buffer_wr_ptr_d = buffer_wr_ptr;
      2'b01 : buffer_wr_ptr_d = buffer_wr_ptr + current_input_rate;
      2'b10 : buffer_wr_ptr_d = buffer_wr_ptr - current_output_rate;
      2'b11 : buffer_wr_ptr_d = buffer_wr_ptr + (current_input_rate - current_output_rate);
      default : buffer_wr_ptr_d = buffer_wr_ptr;
    endcase
  end
  logic [PISO_BUFFER_W-1:0] buffer_wdata;
  logic [PISO_BUFFER_W-1:0] buffer_wdata_mask;
  always_comb begin
    buffer_wdata = '0;
    buffer_wdata_mask = '1;
    buffer_wdata_mask = PISO_BUFFER_W'(buffer_wdata_mask >> (PISO_BUFFER_W[PISO_PTR_W-1:0] - current_input_rate));
    buffer_wdata = {{BUFFER_W_DELTA{1'b0}},data_i} & buffer_wdata_mask;
  end
  always_comb begin
    unique case ({buffer_rd, buffer_wr})
      2'b00 : buffer_d = buffer;
      2'b10 : buffer_d = PISO_BUFFER_W'(buffer >> current_output_rate);
      2'b01 : buffer_d = PISO_BUFFER_W'(buffer_wdata << buffer_wr_ptr) | buffer;
      2'b11 : buffer_d = PISO_BUFFER_W'(buffer_wdata << (buffer_wr_ptr - current_output_rate)) | PISO_BUFFER_W'(buffer >> current_output_rate);
      default : buffer_d = buffer;
    endcase
  end
endmodule
module abr_sample_buffer
  #(
   parameter NUM_WR = 5
  ,parameter NUM_RD  = 4
  ,parameter BUFFER_DATA_W = 32
  ,parameter OPT_BUFFER_DEPTH = 0
  ,localparam BUFFER_DEPTH = (NUM_WR + NUM_RD)
  ,localparam BUF_W = BUFFER_DEPTH*BUFFER_DATA_W
  )
  (
  input logic clk,
  input logic rst_b,
  input logic zeroize,
  input  logic [NUM_WR-1:0]                    data_valid_i,
  input  logic [NUM_WR-1:0][BUFFER_DATA_W-1:0] data_i,
  output logic                                 buffer_full_o,
  output logic                                 data_valid_o,
  output logic [NUM_RD-1:0][BUFFER_DATA_W-1:0] data_o
  );
  logic buffer_rd, buffer_wr;
  logic update_buffer;
  logic [BUFFER_DEPTH-1:0][BUFFER_DATA_W-1:0] buffer_wr_data, buffer_wr_data_shift;
  logic [BUFFER_DEPTH-1:0] buffer_wr_valid, buffer_wr_valid_shift;
  logic [BUFFER_DEPTH-1:0] buffer_valid, buffer_valid_d, buffer_valid_shift;
  logic [BUFFER_DEPTH-1:0][BUFFER_DATA_W-1:0] buffer, buffer_d, buffer_shift;
  logic [$clog2(BUFFER_DEPTH):0] num_valid;
  generate
    if (NUM_WR == NUM_RD)  always_comb buffer_full_o = '0;
    else                   always_comb buffer_full_o = buffer_valid[(BUFFER_DEPTH-(NUM_WR-NUM_RD))];
  endgenerate
  always_comb buffer_rd = buffer_valid[NUM_RD-1]; 
  always_comb buffer_wr = (|data_valid_i) & ~buffer_full_o;
  always_comb update_buffer = buffer_rd | buffer_wr;
  always_comb begin
    num_valid = '0;
    for (int i = 0; i < BUFFER_DEPTH; i++) begin
      if (buffer_valid[i] == 1'b1) num_valid += 1'b1;
    end
  end
  logic [$clog2(BUFFER_DEPTH)-1:0] sample_wr_ptr;
  always_comb begin
    sample_wr_ptr = '0;
    buffer_wr_data = '0;
    buffer_wr_valid = '0;
    for (int sample = 0; sample < NUM_WR; sample++) begin
      if (data_valid_i[sample]) begin
        buffer_wr_data[sample_wr_ptr] = data_i[sample][BUFFER_DATA_W-1:0];
        buffer_wr_valid[sample_wr_ptr] = 1'b1;
        sample_wr_ptr += 1;
      end
    end
    buffer_wr_data_shift = buffer_rd ? buffer_wr_data << (num_valid - NUM_RD)*BUFFER_DATA_W : 
                                       buffer_wr_data << (num_valid)*BUFFER_DATA_W;
    buffer_wr_valid_shift = buffer_wr ?
                            (buffer_rd ? buffer_wr_valid << (num_valid - NUM_RD) :
                                         buffer_wr_valid << (num_valid)) : '0;
  end
  always_comb begin
    buffer_shift = buffer_rd ? BUF_W'(buffer >> (NUM_RD*BUFFER_DATA_W)) : buffer;
    buffer_valid_shift = buffer_rd ? BUFFER_DEPTH'(buffer_valid >> NUM_RD) : buffer_valid;
    buffer_d = buffer_shift | buffer_wr_data_shift;
    buffer_valid_d = buffer_valid_shift | buffer_wr_valid_shift;
  end
  always_ff @(posedge clk or negedge rst_b) begin
    if (!rst_b) begin
      buffer <= '0;
      buffer_valid <= '0;
    end else if (zeroize) begin
      buffer <= '0;
      buffer_valid <= '0;
    end else if (update_buffer) begin
      buffer <= buffer_d;
      buffer_valid <= buffer_valid_d;
    end 
  end
  always_comb data_valid_o = buffer_rd & ~zeroize;
  always_comb data_o = buffer[NUM_RD-1:0];
endmodule
module abr_msg_buffer
  #(
   parameter NUM_WR = 5
  ,parameter NUM_RD  = 4
  ,parameter BUFFER_DATA_W = 32
  ,localparam BUFFER_DEPTH = (NUM_WR + NUM_RD)
  ,localparam BUF_W = BUFFER_DEPTH*BUFFER_DATA_W
  )
  (
  input logic clk,
  input logic rst_b,
  input logic flush,
  input  logic [NUM_WR-1:0]                    data_valid_i,
  input  logic [NUM_WR-1:0][BUFFER_DATA_W-1:0] data_i,
  output logic                                 buffer_full_o,
  output logic [NUM_RD-1:0]                    data_valid_o,
  input  logic                                 data_hold_i,
  output logic [NUM_RD-1:0][BUFFER_DATA_W-1:0] data_o
  );
  logic buffer_rd, buffer_wr;
  logic update_buffer;
  logic [BUFFER_DEPTH-1:0][BUFFER_DATA_W-1:0] buffer_wr_data, buffer_wr_data_shift;
  logic [BUFFER_DEPTH-1:0] buffer_wr_valid, buffer_wr_valid_shift;
  logic [BUFFER_DEPTH-1:0] buffer_valid, buffer_valid_d, buffer_valid_shift;
  logic [BUFFER_DEPTH-1:0][BUFFER_DATA_W-1:0] buffer, buffer_d, buffer_shift;
  logic [$clog2(BUFFER_DEPTH):0] num_valid;
  generate
    if (NUM_WR <= NUM_RD) always_comb buffer_full_o = buffer_valid[BUFFER_DEPTH-NUM_WR] & ~buffer_rd;
    else                  always_comb buffer_full_o = buffer_rd ? buffer_valid[(BUFFER_DEPTH-(NUM_WR-NUM_RD))] :
                                                      buffer_valid[BUFFER_DEPTH-NUM_WR];
  endgenerate
  always_comb buffer_rd = ~data_hold_i & (buffer_valid[NUM_RD-1] | (flush & buffer_valid[0])); 
  always_comb buffer_wr = (|data_valid_i) & ~buffer_full_o;
  always_comb update_buffer = buffer_rd | buffer_wr;
  always_comb begin
    num_valid = '0;
    for (int i = 0; i < BUFFER_DEPTH; i++) begin
      if (buffer_valid[i] == 1'b1) num_valid += 1'b1;
    end
  end
  always_comb begin
    buffer_wr_data = '0;
    buffer_wr_valid = '0;
    for (int sample = 0; sample < NUM_WR; sample++) begin
      buffer_wr_data[sample] = data_valid_i[sample] ? data_i[sample][BUFFER_DATA_W-1:0] : '0;
      buffer_wr_valid[sample] = data_valid_i[sample];
    end
  end
  always_comb begin
    buffer_wr_data_shift = buffer_rd ? buffer_wr_data << (num_valid - NUM_RD)*BUFFER_DATA_W : 
                                       buffer_wr_data << (num_valid)*BUFFER_DATA_W;
    buffer_wr_valid_shift = buffer_wr ?
                            (buffer_rd ? buffer_wr_valid << (num_valid - NUM_RD) :
                                         buffer_wr_valid << (num_valid)) : '0;
  end
  always_comb begin
    buffer_shift = buffer_rd ? BUF_W'(buffer >> (NUM_RD*BUFFER_DATA_W)) : buffer;
    buffer_valid_shift = buffer_rd ? BUFFER_DEPTH'(buffer_valid >> NUM_RD) : buffer_valid;
    buffer_d = buffer_shift | buffer_wr_data_shift;
    buffer_valid_d = buffer_valid_shift | buffer_wr_valid_shift;
  end
  always_ff @(posedge clk or negedge rst_b) begin
    if (!rst_b) begin
      buffer <= '0;
      buffer_valid <= '0;
    end else if (update_buffer) begin
      buffer <= buffer_d;
      buffer_valid <= buffer_valid_d;
    end 
  end
  always_comb data_valid_o = buffer_valid[NUM_RD-1:0];
  always_comb data_o = buffer[NUM_RD-1:0];
endmodule
package abr_ahb_defines_pkg;
  parameter ABR_H_OKAY=1'b0;
  parameter ABR_H_ERROR=1'b1;
endpackage
module abr_ahb_slv_sif 
  import abr_ahb_defines_pkg::*; 
  #(
    parameter AHB_DATA_WIDTH = 64
   ,parameter CLIENT_DATA_WIDTH = 32
   ,parameter AHB_ADDR_WIDTH = 32
   ,parameter CLIENT_ADDR_WIDTH = AHB_ADDR_WIDTH
   )
   (
    input logic hclk,
    input logic hreset_n,
    input logic [AHB_ADDR_WIDTH-1:0] haddr_i,
    input logic [AHB_DATA_WIDTH-1:0] hwdata_i,
    input logic hsel_i,
    input logic hwrite_i,
    input logic hready_i,
    input logic [1:0] htrans_i,
    input logic [2:0] hsize_i,
    output logic hresp_o,
    output logic hreadyout_o,
    output logic [AHB_DATA_WIDTH-1:0] hrdata_o,
    output logic                         dv,
    input  logic                         hld,
    input  logic                         err,
    output logic                         write,
    output logic [CLIENT_DATA_WIDTH-1:0] wdata,
    output logic [CLIENT_ADDR_WIDTH-1:0] addr,
    input  logic [CLIENT_DATA_WIDTH-1:0] rdata
   );
logic err_f;
localparam BITS_WDATA = $bits(wdata);
generate 
    if ((AHB_DATA_WIDTH == 32) & (CLIENT_DATA_WIDTH == 32)) begin
        always_comb begin
            unique case (hsize_i) inside
                3'b000:   
                    wdata = {{BITS_WDATA-8{1'b0}},hwdata_i[7:0]};
                3'b001:   
                    wdata = {{BITS_WDATA-16{1'b0}},hwdata_i[15:0]};
                3'b010:   
                    wdata = hwdata_i[31:0];
                default:  
                wdata = hwdata_i[31:0];
            endcase
        end
        always_comb hrdata_o = rdata;
    end else if ((AHB_DATA_WIDTH == 64) & (CLIENT_DATA_WIDTH == 32)) begin
        always_comb begin
            unique case (hsize_i) inside
                3'b000:   
                    wdata = addr[2] ? {{BITS_WDATA-8{1'b0}},hwdata_i[39:32]} : {{BITS_WDATA-8{1'b0}},hwdata_i[7:0]};
                3'b001:   
                    wdata = addr[2] ? {{BITS_WDATA-16{1'b0}},hwdata_i[47:32]} : {{BITS_WDATA-16{1'b0}},hwdata_i[15:0]};
                3'b010:   
                    wdata = addr[2] ? hwdata_i[63:32] : hwdata_i[31:0];
                default:  
                wdata = addr[2] ? hwdata_i[63:32] : hwdata_i[31:0];
            endcase
        end
        always_comb hrdata_o = addr[2] ? {rdata, 32'b0} : {32'b0, rdata};
    end else if ((AHB_DATA_WIDTH == 64) & (CLIENT_DATA_WIDTH == 64)) begin
        always_comb begin
            unique case (hsize_i) inside
                3'b000:   
                    wdata = {{BITS_WDATA-8{1'b0}},hwdata_i[7:0]};
                3'b001:   
                    wdata = {{BITS_WDATA-16{1'b0}},hwdata_i[15:0]};
                3'b010:   
                    wdata = addr[2]? hwdata_i[63:32] : hwdata_i[31:0];
                3'b011:  
                    wdata = hwdata_i;
                default:  
                    wdata = hwdata_i;
            endcase
        end
        always_comb hrdata_o = rdata;
    end 
endgenerate
    always_ff @(posedge hclk or negedge hreset_n) begin
        if(!hreset_n) begin
            dv <= 1'b0;
            write <= 1'b0;
            addr <= '0;
            err_f <= '0;
        end
        else begin
            err_f <= err;
            if (hready_i) begin
                dv <= hsel_i & htrans_i inside {2'b10, 2'b11};
            end
            if(hready_i & hsel_i) begin
                addr <= haddr_i[CLIENT_ADDR_WIDTH-1:0];
                write <= hwrite_i & |htrans_i;
            end
        end
    end
always_comb begin : response_block
    hreadyout_o = 1'b1;
    hresp_o = ABR_H_OKAY;
    if (err & ~err_f) begin
        hreadyout_o = 1'b0;
        hresp_o = ABR_H_ERROR;
    end else if (hld) begin
        hreadyout_o = 1'b0;
        hresp_o = ABR_H_OKAY;
    end else if (err_f) begin
        hreadyout_o = 1'b1;
        hresp_o = ABR_H_ERROR;
    end
end
endmodule
 module abr_masked_AND
    (
        input wire clk,              
        input wire rst_n,            
        input wire zeroize,          
        input wire [1:0] x,          
        input wire [1:0] y,          
        input wire rnd,              
        output logic [1:0] c         
    );
    logic [3:0] calculation;
    logic [3:0] resharing;
    always_comb begin
        calculation[0] = x[0] & y[0];  
        calculation[1] = x[0] & y[1];  
        calculation[2] = x[1] & y[0];  
        calculation[3] = x[1] & y[1];  
    end
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            for (int i = 0; i < 4; i++) begin
                resharing[i] <= 1'b0;
            end
        end
        else if (zeroize) begin
            for (int i = 0; i < 4; i++) begin
                resharing[i] <= 1'b0;
            end
        end
        else begin
            resharing[0] <= calculation[0];          
            resharing[1] <= calculation[1] ^ rnd;    
            resharing[2] <= calculation[2] ^ rnd;    
            resharing[3] <= calculation[3];          
        end
    end
    always_comb begin
        c[0] = resharing[0] ^ resharing[1];      
        c[1] = resharing[2] ^ resharing[3];      
    end
endmodule: abr_masked_AND
module abr_delay_masked_shares
#(
    parameter WIDTH = 46,   
    parameter N = 5         
)
(
    input  wire clk,
    input  wire rst_n,
    input  wire zeroize,
    input  wire [1:0] input_reg [WIDTH-1:0],  
    output logic [1:0] delayed_reg [WIDTH-1:0]  
);
    logic [N-1:0][WIDTH-1:0][1:0] shift_reg ;
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            for (int j = 0; j < N; j = j + 1) begin
                shift_reg[j] <= '0;
            end
        end
        else if (zeroize) begin
            for (int j = 0; j < N; j = j + 1) begin
                shift_reg[j] <= '0;
            end
        end
        else begin
            for (int j = 0; j < N-1; j = j + 1) begin
                shift_reg[j+1] <= shift_reg[j];
            end
            for (int i = 0; i < WIDTH; i = i + 1) begin
                shift_reg[0][i] <= input_reg[i];
            end
        end
    end
    always_comb begin
        for (int i = 0; i < WIDTH; i = i + 1) begin
            delayed_reg[i] = shift_reg[N-1][i];
        end
    end
endmodule: abr_delay_masked_shares
module abr_masked_add_sub_mod_Boolean #(
    parameter WIDTH      = 23,
    parameter PRIME = 23'd8380417
    )
    (
    input wire           clk,
    input wire           rst_n,
    input wire           zeroize,
    input logic [3*WIDTH-1:0] rnd,
    input  wire        sub_i,
    input  wire  [1:0] opa_i_masked [WIDTH-1:0],
    input  wire  [1:0] opb_i_masked [WIDTH-1:0],
    output logic [1:0] res_o_masked [WIDTH-1:0]
);
    logic  [1:0] opa_i_masked_padded [WIDTH:0];
    logic  [1:0] opb_i_masked_padded [WIDTH:0];
    logic  [1:0] opa_2_masked_padded [WIDTH:0];
    logic  [1:0] prime [WIDTH:0];
    logic  [1:0] r0_c0 [WIDTH:0];
    logic  [1:0] r1_c1 [WIDTH:0];
    logic  [1:0] r0_c0_delayed [WIDTH:0];
    always_comb begin
        for (int i = 0; i < WIDTH; i = i + 1) begin
            opa_i_masked_padded[i]  = opa_i_masked[i];
            if (sub_i) begin
                opb_i_masked_padded[i][0]   = opb_i_masked[i][0];
                opb_i_masked_padded[i][1]   = ~opb_i_masked[i][1];
                prime[i]                    = {1'b0, PRIME[i]};
            end
            else begin
                opb_i_masked_padded[i]      = opb_i_masked[i];
                prime[i]                    = {1'b0, ~PRIME[i]};
            end
        end
        opa_i_masked_padded[WIDTH] = 2'b00;
        opb_i_masked_padded[WIDTH] = 2'b00;
        prime[WIDTH] = 2'b00;
    end
    always_comb begin
        for (int i = 0; i < WIDTH; i = i + 1) begin
            opa_2_masked_padded[i] = r0_c0[i];
        end
        opa_2_masked_padded[WIDTH] = 2'b00;
    end
    abr_masked_N_bit_Boolean_sub #(
        .WIDTH(WIDTH+1)
    ) r0_sub_or_add (
        .clk(clk),
        .rst_n(rst_n),
        .zeroize(zeroize),
        .sub_i(sub_i),
        .x(opa_i_masked_padded),
        .y(opb_i_masked_padded),
        .rnd(rnd[WIDTH:0]),
        .s(r0_c0)
    );
    abr_delay_masked_shares #(
        .WIDTH(WIDTH+1),
        .N(WIDTH+3)  
    ) delay_r0_c0 (
        .clk(clk),
        .rst_n(rst_n),
        .zeroize(zeroize),
        .input_reg(r0_c0),
        .delayed_reg(r0_c0_delayed)
    );
    abr_masked_N_bit_Boolean_sub #(
        .WIDTH(WIDTH+1)
    ) r1_sub_or_add (
        .clk(clk),
        .rst_n(rst_n),
        .zeroize(zeroize),
        .sub_i(~sub_i),
        .x(opa_2_masked_padded),
        .y(prime),
        .rnd(rnd[WIDTH:0]),
        .s(r1_c1)
    );
    abr_masked_MUX #(
        .WIDTH(WIDTH)
    ) r0_MUX_r0 (
        .clk(clk),
        .rst_n(rst_n),
        .zeroize(zeroize),
        .sub_i(sub_i),
        .carry0(r0_c0_delayed[WIDTH]),
        .carry1(r1_c1[WIDTH]),
        .r0(r0_c0_delayed[WIDTH-1:0]),
        .r1(r1_c1[WIDTH-1:0]),
        .rnd_xor(rnd[WIDTH*2-1:WIDTH]),
        .rnd_and(rnd[WIDTH*3-1:2*WIDTH]),
        .res_o_masked(res_o_masked)
    );
endmodule: abr_masked_add_sub_mod_Boolean
module abr_masked_MUX #(
    parameter WIDTH = 23
)(
    input wire                  clk,          
    input wire                  rst_n,        
    input wire                  zeroize,      
    input wire                  sub_i,        
    input wire  [1:0]           carry0,       
    input wire  [1:0]           carry1,       
    input wire  [1:0]           r0 [WIDTH-1:0],  
    input wire  [1:0]           r1 [WIDTH-1:0],  
    input wire  [WIDTH-1:0]     rnd_xor,      
    input wire  [WIDTH-1:0]     rnd_and,      
    output logic [1:0]          res_o_masked [WIDTH-1:0]  
);
    logic [1:0] s;
    logic [1:0] c0c1;
    logic [1:0] xy [WIDTH-1:0];
    logic [1:0] xyk [WIDTH-1:0];
    logic [1:0] xy_and_s [WIDTH-1:0];
    logic [1:0] r1_k [WIDTH-1:0];
    logic [1:0] r1_delayed [WIDTH-1:0];
    always_comb begin
        if (sub_i) begin
            s = carry0;
            c0c1 = 2'h0; /*verilator */ 
        end
        else begin
            c0c1 = carry0 ^ carry1;
            s[0] = ~c0c1[0];
            s[1] = c0c1[1];
        end
    end
    always_comb begin /*verilator */ 
        for (int i = 0; i < WIDTH; i++) begin
            xy[i] = r0[i] ^ r1[i];
            xyk[i][0] = xy[i][0] ^ rnd_xor[i];
            xyk[i][1] = xy[i][1] ^ rnd_xor[i];
            r1_k[i][0] = r1[i][0] ^ rnd_xor[i];
            r1_k[i][1] = r1[i][1] ^ rnd_xor[i];
        end
    end
    genvar i_AND;
    generate
        for (i_AND = 0; i_AND < WIDTH; i_AND = i_AND + 1) begin : gen_DOM_AND
            abr_masked_AND and_gate_inst (
                .clk(clk),
                .rst_n(rst_n),
                .zeroize(zeroize),
                .x(xyk[i_AND]),
                .y(s),
                .rnd(rnd_and[i_AND]),
                .c(xy_and_s[i_AND])
            );
        end
    endgenerate
    abr_delay_masked_shares #(
        .WIDTH(WIDTH),
        .N(1)  
    ) delay_r1_k (
        .clk(clk),
        .rst_n(rst_n),
        .zeroize(zeroize),
        .input_reg(r1_k),
        .delayed_reg(r1_delayed)
    );
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            for (int i = 0; i < WIDTH; i++) begin
                res_o_masked[i] <= 2'b0;
            end
        end
        else if (zeroize) begin
            for (int i = 0; i < WIDTH; i++) begin
                res_o_masked[i] <= 2'b0;
            end
        end
        else begin
            for (int i = 0; i < WIDTH; i++) begin
                res_o_masked[i] <= xy_and_s[i] ^ r1_delayed[i];
            end
        end
    end
endmodule: abr_masked_MUX
module abr_masked_N_bit_Boolean_sub #(
    parameter WIDTH = 8  
)(
    input wire clk,                     
    input wire rst_n,                   
    input wire zeroize,                 
    input wire sub_i,
    input wire [1:0] x [WIDTH-1:0],     
    input wire [1:0] y [WIDTH-1:0],     
    input wire [WIDTH-1:0] rnd,         
    output logic [1:0] s [WIDTH-1:0]
);
    logic  [WIDTH:0] [1:0] carry;  
    logic  [WIDTH-1:0] [1:0] sum;  
    logic  [WIDTH-1:0][WIDTH-1:0][1:0] x_reg;  
    logic  [WIDTH-1:0][WIDTH-1:0][1:0] y_reg;  
    logic  [WIDTH-1:0][WIDTH-1:0][1:0] sum_reg;  
    logic [1:0] the_last_sum;
    assign carry[0] = sub_i ? 2'b01 : 2'b00;
    genvar i;
    generate
        for (i = 0; i < WIDTH; i = i + 1) begin : gen_full_adders
            always_ff @(posedge clk or negedge rst_n) begin
                if (!rst_n) begin
                    x_reg[i] <= '0;
                    y_reg[i] <= '0;
                end
                else if (zeroize) begin
                    x_reg[i] <= '0;
                    y_reg[i] <= '0;
                end
                else begin
                    for (int j = 0; j < WIDTH; j = j + 1) begin
                        if (j == 0) begin
                            x_reg[i][j] <= x[i];
                            y_reg[i][j] <= y[i];
                        end
                        else begin
                            x_reg[i][j] <= x_reg[i][j-1];
                            y_reg[i][j] <= y_reg[i][j-1];
                        end
                    end
                end
            end
            always_ff @(posedge clk or negedge rst_n) begin
                if (!rst_n) begin
                    sum_reg[i] <= '0;
                end
                else if (zeroize) begin
                    sum_reg[i] <= '0;
                end
                else begin
                    for (int j = i; j < WIDTH; j = j + 1) begin
                        if (j == i && i == WIDTH-1) begin
                            sum_reg[i][j] <= the_last_sum;
                        end
                        else if (j == i) begin
                            sum_reg[i][j] <= sum[i];
                        end
                        else begin
                            sum_reg[i][j] <= sum_reg[i][j-1];
                        end
                    end
                end
            end
            if (i<(WIDTH-1)) begin : gen_masked_full_adder
                abr_masked_full_adder u_abr_masked_full_adder (
