 module abr_masked_full_adder (
    input wire clk,              
    input wire rst_n,            
    input wire zeroize,          
    input wire [1:0] x,          
    input wire [1:0] y,          
    input wire [1:0] c_in,       
    input wire rnd,              
    output logic [1:0] s,        
    output logic [1:0] c_out     
);
    logic [1:0] sum_comb;
    logic [1:0] and_opr1;
    logic [1:0] and_opr2;
    logic [1:0] and_out;
    always_comb begin : calculate_sum
        for (int i = 0; i < 2; i++) begin
            and_opr1[i] = x[i] ^ y[i];
            and_opr2[i] = x[i] ^ c_in[i];
            sum_comb[i] = and_opr1[i] ^ c_in[i];
        end
    end
    abr_masked_AND u_abr_masked_AND (
        .clk(clk),         
        .rst_n(rst_n),     
        .zeroize(zeroize), 
        .x(and_opr1),      
        .y(and_opr2),      
        .rnd(rnd),         
        .c(and_out)        
    );
    logic [1:0] buffered_x;
    logic [1:0] buffered_sum;
    always_ff @(posedge clk or negedge rst_n) begin : pipeline_inputs
        if (!rst_n) begin
            for (int i = 0; i < 2; i++) begin
                buffered_x[i] <= 1'b0;
                buffered_sum[i] <= 1'b0;
            end
        end
        else if (zeroize) begin
            for (int i = 0; i < 2; i++) begin
                buffered_x[i] <= 1'b0;
                buffered_sum[i] <= 1'b0;
            end
        end
        else begin
            for (int i = 0; i < 2; i++) begin
                buffered_x[i] <= x[i];
                buffered_sum[i] <= sum_comb[i];
            end
        end
    end
    always_comb begin : calculate_carry
        for (int i = 0; i < 2; i++) begin
            s[i] = buffered_sum[i];
            c_out[i] = buffered_x[i] ^ and_out[i];
        end
    end
endmodule : abr_masked_full_adder
