    input wire [1:0][WIDTH-1:0] x,      
    input wire [1:0][WIDTH-1:0] y,      
    output logic [1:0][WIDTH-1:0] s 
);
    logic [1:0][WIDTH-1:0] add_res;
    logic [1:0] s_reg [WIDTH-1:0];
    always_comb begin
        add_res[0] = x[0] + y[0];
        add_res[1] = x[1] + y[1];
    end
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            s <= 'h0;
        end
        else if (zeroize) begin
            s <= 'h0;
        end
        else begin
            s <= add_res;
        end
    end
