 module abr_masked_B2A_conv #(
    parameter WIDTH = 8  
)(
    input wire               clk,
    input wire               rst_n,
    input wire               zeroize,
    input wire [WIDTH-1:0]   rnd,
    input wire [1:0]         x_boolean [WIDTH-1:0],  
    output logic [1:0]       x_arith [WIDTH-1:0]   
);
    logic unsigned [WIDTH-1:0] T0, T1, T2, A0, A1, A2, Gamma_reg, Gamma_reg2, x0, x1;
    logic unsigned [1:0]       x_arith_next [WIDTH-1:0];
    wire [WIDTH-1:0]   Gamma;
    assign Gamma = rnd;
    always_ff @ (posedge clk or negedge rst_n) begin            
        if (!rst_n) begin
            for (int i = 0; i < WIDTH; i++) begin
                Gamma_reg[i]    <= 'h0;
                x0[i]           <= 'h0;
                x1[i]           <= 'h0;
                x_arith[i]      <= 'h0;
            end
        end
        else if (zeroize) begin
            for (int i = 0; i < WIDTH; i++) begin
                Gamma_reg[i]    <= 'h0;
                x0[i]           <= 'h0;
                x1[i]           <= 'h0;
                x_arith[i]      <= 'h0;
            end
        end
        else begin
            for (int i = 0; i < WIDTH; i++) begin
                Gamma_reg[i]    <= Gamma[i];
                x0[i]           <= x_boolean[i][0];
                x1[i]           <= x_boolean[i][1];
                x_arith[i]      <= x_arith_next[i];
            end
        end
    end
    always_comb begin
            T0               = x0 ^ Gamma_reg;               
            T1               = T0 - Gamma_reg;               
            T2               = T1 ^ x0;                      
            Gamma_reg2       = Gamma_reg ^ x1;               
            A0               = x0 ^ Gamma_reg2;              
            A1               = A0 - Gamma_reg2;              
            A2               = A1 ^ T2;                      
        for (int i = 0; i < WIDTH; i++) begin
            x_arith_next[i][0]  = A2[i];                     
            x_arith_next[i][1]  = x1[i];                     
        end
    end
endmodule
 module abr_masked_N_bit_mult
    #(parameter WIDTH = 8, parameter HALF_WIDTH = WIDTH/2)   
    (
        input wire clk,                       
        input wire rst_n,                     
        input wire zeroize,                   
        input wire [1:0] x [WIDTH-1:0],       
        input wire [HALF_WIDTH-1:0] y ,       
        output logic [1:0] z [WIDTH-1:0]      
    );
    logic  [WIDTH-1:0] calculation [1:0];
    logic [WIDTH-1:0] x0, x1;
    always_comb begin
        for (int i = 0; i < WIDTH; i++) begin
            x0[i] = x[i][0];
            x1[i] = x[i][1];
        end
    end
    always_comb begin
        calculation[0] = x0 * y;  
        calculation[1] = x1 * y;  
    end
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            for (int i = 0; i < WIDTH; i++) begin
                z[i] <= 2'b0;
            end
        end
        else if (zeroize) begin
            for (int i = 0; i < WIDTH; i++) begin
                z[i] <= 2'b0;
            end
        end
        else begin
            for (int i = 0; i < WIDTH; i++) begin
                z[i][0] <= calculation[0][i];  
                z[i][1] <= calculation[1][i];  
            end
        end
    end
endmodule: abr_masked_N_bit_mult
 module abr_masked_N_bit_mult_two_share
    #(parameter WIDTH = 8)   
    (
        input wire clk,                          
        input wire rst_n,                        
        input wire zeroize,                      
        input wire        [WIDTH-1:0] random,    
        input wire   [1:0][WIDTH-1:0] x,         
        input wire   [1:0][WIDTH-1:0] y,         
        output logic [1:0] z [WIDTH-1:0]         
    );
    logic [WIDTH-1:0] calculation [3:0];
    logic [WIDTH-1:0] calculation_reg [1:0];
    logic [WIDTH-1:0] calculation_rand [1:0];
    logic [WIDTH-1:0] final_res [1:0];
    logic [WIDTH-1:0] x0, x1, y0, y1;
    always_comb begin
        calculation[0] = WIDTH'(x[0] * y[0]);  
        calculation[1] = WIDTH'(x[1] * y[0]);  
        calculation[2] = WIDTH'(x[0] * y[1]);  
        calculation[3] = WIDTH'(x[1] * y[1]);  
    end
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            for (int i = 0; i < 2; i++) begin
                calculation_rand[i] <= 'h0;
                calculation_reg[i] <= 'h0;
            end
        end
        else if (zeroize) begin
            for (int i = 0; i < 2; i++) begin
                calculation_rand[i] <= 'h0;
                calculation_reg[i] <= 'h0;
            end
        end
        else begin
            calculation_rand[0] <= calculation[2] + random;
            calculation_rand[1] <= calculation[1] - random;
            calculation_reg[0]  <= calculation[0];
            calculation_reg[1]  <= calculation[3];
        end
    end
    always_comb begin
        final_res[0] = calculation_reg[0] + calculation_rand[0];
        final_res[1] = calculation_reg[1] + calculation_rand[1];
    end
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            for (int i = 0; i < WIDTH; i++)
                z[i] <= 2'h0;
        end
        else if (zeroize) begin
            for (int i = 0; i < WIDTH; i++)
                z[i] <= 2'h0;
        end
        else begin
            for (int i = 0; i < WIDTH; i++) begin
                z[i][0] <= final_res[0][i];
                z[i][1] <= final_res[1][i];
            end
        end
    end
 endmodule: abr_masked_N_bit_mult_two_share
module abr_adder #(
    parameter RADIX          = 8
)
(
    input  wire [RADIX-1:0]  a_i,
    input  wire [RADIX-1:0]  b_i,
    input  wire              cin_i,
    output wire [RADIX-1:0]  s_o,
    output wire              cout_o
);
    logic [RADIX : 0]   s_full;
    always_comb begin
        s_full = a_i + b_i + cin_i;
    end
    assign s_o = s_full[RADIX-1 : 0];
    assign cout_o = s_full[RADIX];
endmodule
module abr_add_sub_mod #(
    parameter REG_SIZE      = 384
    )
    (
    input wire           clk,
    input wire           reset_n,
    input wire           zeroize,
    input  wire                 add_en_i,
    input  wire                 sub_i,
    input  wire  [REG_SIZE-1:0] opa_i,
    input  wire  [REG_SIZE-1:0] opb_i,
    input  wire  [REG_SIZE-1:0] prime_i,
    output logic [REG_SIZE-1:0] res_o,
    output logic                ready_o
);
    logic [REG_SIZE-1 : 0] opb0;
    logic [REG_SIZE-1 : 0] opb1;
    logic [REG_SIZE-1 : 0] r0;
    logic [REG_SIZE-1 : 0] r1;
    logic                  carry0; 
    logic                  sub_n;
    logic [REG_SIZE-1 : 0] r0_reg;
    logic                  carry0_reg;
    logic                  carry1;
    logic [1 : 0]          push_result_reg;
    abr_adder #(
        .RADIX(REG_SIZE)
        ) 
        adder_inst_0(
        .a_i(opa_i),
        .b_i(opb0),
        .cin_i(sub_i),
        .s_o(r0),
        .cout_o(carry0)
    );
    abr_adder #(
        .RADIX(REG_SIZE)
        ) 
        adder_inst_1(
        .a_i(r0_reg),
        .b_i(opb1),
        .cin_i(sub_n),
        .s_o(r1),
        .cout_o(carry1)
    );
    assign opb0 = sub_i ? ~opb_i : opb_i;
    always_ff @(posedge clk or negedge reset_n) 
    begin
        if(!reset_n) begin
            r0_reg <= '0;
            carry0_reg <= '0;
            sub_n <= '0;
            opb1 <= '0;
        end
        else if (zeroize) begin
            r0_reg <= '0;
            carry0_reg <= '0;
            sub_n <= '0;
            opb1 <= '0;
        end
        else if (add_en_i) begin 
            r0_reg <= r0;
            carry0_reg <= carry0;
            sub_n <= !sub_i;
            if (sub_i)
                opb1 <= prime_i;
            else
                opb1 <= ~prime_i;
        end
    end
    always_ff @(posedge clk or negedge reset_n) begin
        if (!reset_n)
            push_result_reg <= 2'b0;
        else if (zeroize)
            push_result_reg <= 2'b0;
        else if (add_en_i)
            push_result_reg <= 2'b10;
        else  
            push_result_reg <= 2'(push_result_reg >> 1);
    end
    assign ready_o = push_result_reg[0];
    assign res_o = sub_n ? (carry0_reg ^ carry1)? r1 : r0_reg : (carry0_reg) ? r0_reg : r1;
endmodule
module abr_ntt_add_sub_mod 
    import abr_params_pkg::*;
    #(
    parameter REG_SIZE      = 384
    )
    (
    input wire           clk,
    input wire           reset_n,
    input wire           zeroize,
    input  wire                 add_en_i,
    input  wire                 sub_i,
    input  wire  [REG_SIZE-1:0] opa_i,
    input  wire  [REG_SIZE-1:0] opb_i,
    input  wire  [REG_SIZE-1:0] prime_i,
    input  wire                 mlkem,
    output logic [REG_SIZE-1:0] res_o,
    output logic                ready_o
);
    logic [REG_SIZE-1 : 0] opb0;
    logic [REG_SIZE-1 : 0] opb1;
    logic [REG_SIZE-1 : 0] r0;
    logic [REG_SIZE-1 : 0] r1;
    logic                  carry0; 
    logic                  carry0_int; 
    logic                  sub_n;
    logic [REG_SIZE-1 : 0] r0_reg;
    logic                  carry0_reg;
    logic                  carry1;
    logic                  carry1_int;
    logic [1 : 0]          push_result_reg;
    abr_adder #(
        .RADIX(REG_SIZE)
        ) 
        adder_inst_0(
        .a_i(opa_i),
        .b_i(mlkem ? {{(REG_SIZE-MLKEM_REG_SIZE){1'b0}}, opb0[MLKEM_REG_SIZE-1:0]} : opb0),
        .cin_i(sub_i),
        .s_o(r0),
        .cout_o(carry0_int)
    );
    abr_adder #(
        .RADIX(REG_SIZE)
        ) 
        adder_inst_1(
        .a_i(mlkem ? {{(REG_SIZE-MLKEM_REG_SIZE){1'b0}}, r0_reg[MLKEM_REG_SIZE-1:0]} : r0_reg),  
        .b_i(mlkem ? {{(REG_SIZE-MLKEM_REG_SIZE){1'b0}}, opb1[MLKEM_REG_SIZE-1:0]} : opb1),
        .cin_i(sub_n),
        .s_o(r1),
        .cout_o(carry1_int)
    );
    assign carry0 = mlkem ? r0[MLKEM_REG_SIZE] : carry0_int;
    assign carry1 = mlkem ? r1[MLKEM_REG_SIZE] : carry1_int;
    assign opb0 = sub_i ? ~opb_i : opb_i;
    always_ff @(posedge clk or negedge reset_n) 
    begin
        if(!reset_n) begin
            r0_reg <= '0;
            carry0_reg <= '0;
            sub_n <= '0;
            opb1 <= '0;
        end
        else if (zeroize) begin
            r0_reg <= '0;
            carry0_reg <= '0;
            sub_n <= '0;
            opb1 <= '0;
        end
        else if (add_en_i) begin 
            r0_reg <= r0;
            carry0_reg <= carry0;
            sub_n <= !sub_i;
            if (sub_i)
                opb1 <= prime_i;
            else
                opb1 <= ~prime_i;
        end
    end
    always_ff @(posedge clk or negedge reset_n) begin
        if (!reset_n)
            push_result_reg <= 2'b0;
        else if (zeroize)
            push_result_reg <= 2'b0;
        else if (add_en_i)
            push_result_reg <= 2'b10;
        else  
            push_result_reg <= 2'(push_result_reg >> 1);
    end
    assign ready_o = push_result_reg[0];
    always_comb begin
        if (mlkem)
            res_o = sub_n ? (carry0_reg ^ carry1)? {{(REG_SIZE-MLKEM_REG_SIZE){1'b0}}, r1[MLKEM_REG_SIZE-1:0]} : {{(REG_SIZE-MLKEM_REG_SIZE){1'b0}}, r0_reg[MLKEM_REG_SIZE-1:0]} : (carry0_reg) ? {{(REG_SIZE-MLKEM_REG_SIZE){1'b0}}, r0_reg[MLKEM_REG_SIZE-1:0]} : {{(REG_SIZE-MLKEM_REG_SIZE){1'b0}}, r1[MLKEM_REG_SIZE-1:0]};
        else
            res_o = sub_n ? (carry0_reg ^ carry1)? r1 : r0_reg : (carry0_reg) ? r0_reg : r1;
    end
endmodule
module abr_masked_OR
(
    input wire clk,
    input wire rst_n,
    input wire zeroize,
    input wire rnd,
    input wire [1:0] x,
    input wire [1:0] y,
    output logic [1:0] z
);
    logic inv_x0, inv_y0;
    logic [1:0] z_int;
    always_comb begin
        inv_x0 = x[0] ^ 1'b1;
        inv_y0 = y[0] ^ 1'b1;    
    end
    abr_masked_AND and_inst0 (
        .clk(clk),
        .rst_n(rst_n),
        .zeroize(zeroize),
        .x({x[1], inv_x0}),
        .y({y[1], inv_y0}),
        .rnd(rnd),
        .c(z_int)
    );
    always_comb z[0] = z_int[0];
    always_comb z[1] = z_int[1] ^ 1'b1;
endmodule
