  parameter SIB_TAU              = 60;
  parameter SIB_PISO_BUFFER_W    = 1344;
  parameter SIB_PISO_INPUT_RATE  = 1088;
  parameter SIB_PISO_OUTPUT_RATE = SIB_NUM_SAMPLERS*SIB_SAMPLE_W;
  parameter CBD_NUM_SAMPLERS     = COEFF_PER_CLK;
  parameter CBD_SAMPLE_W         = 2*MLKEM_ETA;
  parameter CBD_VLD_SAMPLES      = COEFF_PER_CLK;
  parameter CBD_PISO_BUFFER_W    = 1344;
  parameter CBD_PISO_INPUT_RATE  = 1088;
  parameter CBD_PISO_OUTPUT_RATE = CBD_NUM_SAMPLERS*CBD_SAMPLE_W;
  typedef enum logic [2:0] {
    ABR_SAMPLER_IDLE   = 3'b000,
    ABR_SAMPLER_PROC   = 3'b001,
    ABR_SAMPLER_WAIT   = 3'b010,
    ABR_SAMPLER_RUN    = 3'b011,
    ABR_SAMPLER_DONE   = 3'b100
  } abr_sampler_fsm_state_e;
  typedef enum logic [2:0] {
    ABR_REJS_MODE,
    ABR_REJB_MODE,
    ABR_EXP_MODE,
    ABR_SIB_MODE,
    ABR_CBD_MODE
  } abr_piso_mode_e;
  typedef enum logic [4:0] {
    ABR_SAMPLER_NONE,
    ABR_SHAKE256,
    ABR_SHAKE128,
    ABR_SHA512,
    ABR_SHA256,
    MLDSA_REJ_SAMPLER,
    MLKEM_REJ_SAMPLER,
    ABR_EXP_MASK,
    ABR_REJ_BOUNDED,
    ABR_SAMPLE_IN_BALL,
    ABR_CBD_SAMPLER
  } abr_sampler_mode_e;
endpackage
module rej_bounded_ctrl
  import abr_params_pkg::*;
  #(
   parameter REJ_NUM_SAMPLERS = 8
  ,parameter REJ_SAMPLE_W     = 4
  ,parameter REJ_VLD_SAMPLES  = 4
  ,parameter REJ_VLD_SAMPLES_W = 24
  ,parameter REJ_VALUE = 15
  ,parameter REJ_BUFFER_W = 3
  )
  (
  input logic clk,
  input logic rst_b,
  input logic zeroize,
  input  logic                                          data_valid_i,
  output logic                                          data_hold_o,
  input  logic [REJ_NUM_SAMPLERS-1:0][REJ_SAMPLE_W-1:0] data_i,
  output logic                                              data_valid_o,
  output logic [REJ_VLD_SAMPLES-1:0][REJ_VLD_SAMPLES_W-1:0] data_o
  );
  logic [REJ_NUM_SAMPLERS-1:0] sample_valid;
  logic [REJ_NUM_SAMPLERS-1:0][REJ_BUFFER_W-1:0] buffer_data;
  logic                                         rej_buffer_valid;
  logic [REJ_VLD_SAMPLES-1:0][REJ_BUFFER_W-1:0] rej_buffer;
  logic buffer_full;
  always_comb data_hold_o = buffer_full;
  generate
    for (genvar inst_g = 0; inst_g < REJ_NUM_SAMPLERS; inst_g++) begin : rej_bounded_inst
      rej_bounded2 #(
        .REJ_SAMPLE_W(REJ_SAMPLE_W),
        .REJ_VALUE(REJ_VALUE)
      ) rej_bounded_i (
        .valid_i(data_valid_i),
        .data_i(data_i[inst_g]),
        .valid_o(sample_valid[inst_g]),
        .data_o(buffer_data[inst_g])
      );
    end
  endgenerate
  abr_sample_buffer #(
    .NUM_WR(REJ_NUM_SAMPLERS),
    .NUM_RD(REJ_VLD_SAMPLES),
    .BUFFER_DATA_W(REJ_BUFFER_W)
  ) mldsa_sample_buffer_i (
    .clk(clk),
    .rst_b(rst_b),
    .zeroize(zeroize),
    .data_valid_i(sample_valid),
    .data_i(buffer_data),
    .buffer_full_o(buffer_full),
    .data_valid_o(rej_buffer_valid),
    .data_o(rej_buffer)
  );
  always_comb data_valid_o = rej_buffer_valid;
  always_comb begin
    for (int sample = 0; sample < REJ_VLD_SAMPLES; sample++) begin
      unique case (rej_buffer[sample])
        3'd0 : data_o[sample] = 2;
        3'd1 : data_o[sample] = 1;
        3'd2 : data_o[sample] = 0;
        3'd3 : data_o[sample] = MLDSA_Q-1;
        3'd4 : data_o[sample] = MLDSA_Q-2;
        default : data_o[sample] = '0;
      endcase
    end
  end
endmodule
module rej_bounded2
  #(
   parameter REJ_SAMPLE_W = 24
  ,parameter REJ_VALUE    = 15
  )
  (
  input  logic       valid_i,
  input  logic [3:0] data_i,
  output logic       valid_o,
  output logic [2:0] data_o
  );
  logic [3:0] a;
  logic [2:0] b;
  assign a = data_i;
  always_comb begin
    valid_o = valid_i & (a < REJ_VALUE);
    b = a[1:0] - a[3:2];
    data_o  = b[2] ? 'd5 + b[2:0] : {1'b0, b[1:0]}; 
  end
endmodule
module rej_sampler_ctrl
  import abr_params_pkg::*;
  #(
   parameter REJ_NUM_SAMPLERS = 5
  ,parameter REJ_SAMPLE_W     = 24
  ,parameter REJ_VLD_SAMPLES  = 4
  ,parameter REJ_VLD_SAMPLES_W = 24
  ,parameter REJ_VALUE = 8380417
  ,parameter OPT_REJ_BUFFER_DEPTH = 0
  ,parameter REJ_BUFFER_W = $clog2(REJ_VALUE)
  )
  (
  input logic clk,
  input logic rst_b,
  input logic zeroize,
  input  logic                                          data_valid_i,
  output logic                                          data_hold_o,
  input  logic [REJ_NUM_SAMPLERS-1:0][REJ_SAMPLE_W-1:0] data_i,
  output logic                                              data_valid_o,
  output logic [REJ_VLD_SAMPLES-1:0][REJ_VLD_SAMPLES_W-1:0] data_o
  );
  logic [REJ_NUM_SAMPLERS-1:0] sample_valid;
  logic [REJ_NUM_SAMPLERS-1:0][REJ_BUFFER_W-1:0] buffer_data;
  logic                                         rej_buffer_valid;
  logic [REJ_VLD_SAMPLES-1:0][REJ_BUFFER_W-1:0] rej_buffer;
  logic buffer_full;
  always_comb data_hold_o = buffer_full;
  generate
    for (genvar inst_g = 0; inst_g < REJ_NUM_SAMPLERS; inst_g++) begin : rej_sampler_inst
      rej_sampler #(
        .REJ_SAMPLE_W(REJ_SAMPLE_W),
        .REJ_VALUE(REJ_VALUE)
      ) rej_sampler_i (
        .valid_i(data_valid_i),
        .data_i(data_i[inst_g]),
        .valid_o(sample_valid[inst_g]),
        .data_o(buffer_data[inst_g])
      );
    end
  endgenerate
  abr_sample_buffer #(
    .NUM_WR(REJ_NUM_SAMPLERS),
    .NUM_RD(REJ_VLD_SAMPLES),
    .BUFFER_DATA_W(REJ_BUFFER_W)
  ) mldsa_sample_buffer_i (
    .clk(clk),
    .rst_b(rst_b),
    .zeroize(zeroize),
    .data_valid_i(sample_valid),
    .data_i(buffer_data),
    .buffer_full_o(buffer_full),
    .data_valid_o(rej_buffer_valid),
    .data_o(rej_buffer)
  );
  always_comb data_valid_o = rej_buffer_valid;
  always_comb begin
    for (int sample = 0; sample < REJ_VLD_SAMPLES; sample++) begin
      data_o[sample] = { {REJ_SAMPLE_W-REJ_BUFFER_W{1'b0}} , rej_buffer[sample] };
    end
  end
endmodule
module rej_sampler
  #(
   parameter REJ_SAMPLE_W      = 24
  ,parameter REJ_VALUE         = 8380417
  ,localparam REJ_VLD_SAMPLE_W = $clog2(REJ_VALUE)
  )
  (
  input  logic                    valid_i,
  input  logic [REJ_SAMPLE_W-1:0] data_i,
  output logic                        valid_o,
  output logic [REJ_VLD_SAMPLE_W-1:0] data_o
  );
  always_comb begin
    valid_o = valid_i & (data_i[REJ_VLD_SAMPLE_W-1:0] < REJ_VALUE[REJ_VLD_SAMPLE_W-1:0]);
    data_o  = data_i[REJ_VLD_SAMPLE_W-1:0];
  end
endmodule
module exp_mask_ctrl
  import abr_params_pkg::*;
  #(
   parameter EXP_NUM_SAMPLERS = 4
  ,parameter EXP_SAMPLE_W     = 20
  ,parameter EXP_VLD_SAMPLES  = 4
  ,parameter EXP_VLD_SAMPLE_W = 23
  )
  (
  input logic clk,
  input logic rst_b,
  input logic zeroize,
  input  logic                                          data_valid_i,
  output logic                                          data_hold_o,
  input  logic [EXP_NUM_SAMPLERS-1:0][EXP_SAMPLE_W-1:0] data_i,
  output logic                                             data_valid_o,
  output logic [EXP_VLD_SAMPLES-1:0][EXP_VLD_SAMPLE_W-1:0] data_o
  );
  always_comb data_hold_o = '0;
  generate
    for (genvar inst_g = 0; inst_g < EXP_NUM_SAMPLERS; inst_g++) begin : exp_mask_inst
      exp_mask #(
        .EXP_SAMPLE_W(EXP_SAMPLE_W),
        .EXP_VLD_SAMPLE_W(EXP_VLD_SAMPLE_W)
      ) exp_mask_i (
        .data_i(data_i[inst_g]),
        .data_o(data_o[inst_g])
      );
    end
  endgenerate
always_comb data_valid_o = data_valid_i & ~zeroize;
endmodule
module exp_mask
  import abr_params_pkg::*;
  #(
    parameter EXP_SAMPLE_W     = 20
   ,parameter EXP_VLD_SAMPLE_W = 23
  )
  (
  input  logic [EXP_SAMPLE_W-1:0] data_i,
  output logic [EXP_VLD_SAMPLE_W-1:0] data_o
  );
  logic [22:0] r0, r1;
  logic c0, c1;
  always_comb {c0,r0} = (24'd1 << 19) - data_i;
  always_comb {c1,r1} = r0 + MLDSA_Q;
  always_comb data_o  = (c0 & c1) ? {1'b0,r1} : {1'b0,r0};
endmodule
package sib_pkg;
  typedef enum logic [1:0] {
    SIB_IDLE         = 2'b00,
    SIB_SIGN_BUFFER  = 2'b01,
    SIB_ACTIVE       = 2'b10,
    SIB_DONE         = 2'b11
} sib_fsm_state_e;
endpackage
module sib_mem #(
     parameter DEPTH      = 64
    ,parameter NUM_PORTS  = 1
    ,parameter DATA_WIDTH = 32
    ,parameter ADDR_WIDTH = $clog2(DEPTH)
    )
    (
    input  logic                                 clk_i,
    input  logic                                 rst_b,
    input  logic                                 zeroize,
    input  logic [NUM_PORTS-1:0]                 cs_i,
    input  logic [NUM_PORTS-1:0]                 we_i,
    input  logic [NUM_PORTS-1:0][ADDR_WIDTH-1:0] addr_i,
    input  logic [NUM_PORTS-1:0][DATA_WIDTH-1:0] wdata_i,
    output logic [NUM_PORTS-1:0][DATA_WIDTH-1:0] rdata_o
    );
    logic [DEPTH-1:0][DATA_WIDTH-1:0] mem;
    always @(posedge clk_i or negedge rst_b) begin
        if (!rst_b) begin
            mem <= '0;
        end
        else if (zeroize) begin
            mem <= '0;
        end else begin
            for (int port = 0; port < NUM_PORTS; port++) begin
                if (cs_i[port] & we_i[port]) begin
                        mem[addr_i[port]] <= wdata_i[port];
                end
            end
        end
    end
    always @(posedge clk_i or negedge rst_b) begin
        if (!rst_b) begin
            rdata_o <= '0;
        end
        else if (zeroize) begin
            rdata_o <= '0;
        end else begin
            for (int port = 0; port < NUM_PORTS; port++) begin
                if (cs_i[port] & ~we_i[port]) begin
                    rdata_o[port] <= mem[addr_i[port]];
                end
            end 
        end
    end
endmodule
module sample_in_ball_ctrl
  import sib_pkg::*;
  import abr_params_pkg::*;
  #(
   parameter SIB_NUM_SAMPLERS = 4
  ,parameter SIB_SAMPLE_W     = 8
  ,parameter SIB_TAU          = 60
  ,parameter SIB_NUM_COEFF    = 256
  ,localparam MLDSA_Q_WIDTH   = $clog2(8380417)
  )
  (
  input logic clk,
  input logic rst_b,
  input logic zeroize,
  input  logic                                          data_valid_i,
  output logic                                          data_hold_o,
  input  logic [SIB_NUM_SAMPLERS-1:0][SIB_SAMPLE_W-1:0] data_i,
  output logic                                          sib_done_o,
  output logic [1:0]                         cs_o,
  output logic [1:0]                         we_o,
  output logic [1:0][7:2]                    addr_o,
  output logic [1:0][3:0][MLDSA_Q_WIDTH-1:0] wrdata_o,
  input  logic [1:0][3:0][MLDSA_Q_WIDTH-1:0] rddata_i
  );
  localparam SIB_NUM_DATA_BITS = $bits(data_i);
  sib_fsm_state_e sib_fsm_ns;
  sib_fsm_state_e sib_fsm_ps;
  logic last_sample;
  logic [SIB_TAU-1:0] sign_buffer, sign_buffer_d;
  logic [(SIB_NUM_DATA_BITS*2)-1:0] sign_buffer_nxt;
  logic sign_buffer_en;
  logic sign_buffer_ph;
  logic [SIB_SAMPLE_W-1:0] rej_value;
  logic rej_value_en;
  logic [SIB_NUM_SAMPLERS-1:0] sampler_valid;
  logic sampler_hold;
  logic index_found;
  logic [$clog2(SIB_NUM_SAMPLERS)-1:0] valid_index;
  logic [SIB_SAMPLE_W-1:0] valid_sample;
  logic [SIB_NUM_SAMPLERS-1:0] sampler_mask, sampler_mask_d;
  logic sampler_mask_en;
  logic sampler_mask_clear;
  logic shuffler_valid;
  logic shuffler_hold;
  always_comb begin : sib_fsm_state_combo
    sib_fsm_ns = sib_fsm_ps;
    unique case (sib_fsm_ps)
        SIB_IDLE: begin
          if (data_valid_i) sib_fsm_ns = SIB_SIGN_BUFFER;
        end
        SIB_SIGN_BUFFER: begin
          if (data_valid_i) sib_fsm_ns = SIB_ACTIVE;
        end
        SIB_ACTIVE: begin
          if (last_sample)  sib_fsm_ns = SIB_DONE;
        end
        SIB_DONE: begin
                            sib_fsm_ns = SIB_IDLE;
        end
        default: begin
                            sib_fsm_ns = SIB_IDLE;
        end
    endcase
  end
  always_comb begin : sib_fsm_output_combo
    data_hold_o = 0;
    sign_buffer_en = 0;
    sign_buffer_ph = 0;
    rej_value_en = 0;
    sampler_mask_en = 0;
    sampler_mask_clear = 0;
    shuffler_valid = 0;
    sib_done_o = 0;
    unique case (sib_fsm_ps)
        SIB_IDLE: begin
          sign_buffer_en = data_valid_i;
          sign_buffer_ph = 0;
        end
        SIB_SIGN_BUFFER: begin
          sign_buffer_en = data_valid_i;
          sign_buffer_ph = 1;
        end
        SIB_ACTIVE: begin
          data_hold_o = sampler_hold | shuffler_hold;
          shuffler_valid = index_found;
          rej_value_en = index_found & ~shuffler_hold;
          sampler_mask_en = index_found & sampler_hold & ~shuffler_hold;
          sampler_mask_clear = ~index_found | ~data_hold_o;
        end
        SIB_DONE: begin
          sib_done_o = 1;
        end
        default: begin
          data_hold_o = 1;
        end
    endcase
  end
  always_ff @(posedge clk or negedge rst_b) begin : sib_fsm_state_reg
    if (!rst_b)       sib_fsm_ps <= SIB_IDLE;
    else if (zeroize) sib_fsm_ps <= SIB_IDLE;
    else              sib_fsm_ps <= sib_fsm_ns;
  end
  always_comb sign_buffer_nxt = sign_buffer_ph ? {data_i, {SIB_NUM_DATA_BITS{1'b0}}} : {{SIB_NUM_DATA_BITS{1'b0}}, data_i};
  always_comb sign_buffer_d = sign_buffer | sign_buffer_nxt[SIB_TAU-1:0];
  always_ff @(posedge clk or negedge rst_b) begin
    if (!rst_b)begin
      sign_buffer <= '0;
    end else if (zeroize) begin
      sign_buffer <= '0;
    end else if (sib_done_o) begin
      sign_buffer <= '0;
    end else if (sign_buffer_en) begin
      sign_buffer <= sign_buffer_d;
    end else if (rej_value_en) begin
      sign_buffer <= SIB_TAU'(sign_buffer >> 1);
    end else begin
      sign_buffer <= sign_buffer;
    end
  end
  always_ff @(posedge clk or negedge rst_b) begin
    if (!rst_b) begin
      rej_value <= SIB_NUM_COEFF - SIB_TAU;
    end else if (zeroize) begin
      rej_value <= SIB_NUM_COEFF - SIB_TAU;
    end else if (sib_done_o) begin
      rej_value <= SIB_NUM_COEFF - SIB_TAU;
    end else if (rej_value_en) begin
      rej_value <= rej_value + 1'b1;
    end else begin
      rej_value <= rej_value;
    end
  end
  always_comb begin
    index_found = 0;
    valid_index = 0;
    sampler_mask_d = sampler_mask;
    for (int i = 0; i < SIB_NUM_SAMPLERS; i++) begin
      if (data_valid_i & ~index_found) begin
        sampler_mask_d[i] = 0;
        if (sampler_valid[i]) begin
          index_found = 1;
          valid_index = i[$clog2(SIB_NUM_SAMPLERS)-1:0];
        end
      end
    end
  end
  always_ff @(posedge clk or negedge rst_b) begin
    if (!rst_b)begin
      sampler_mask <= '1;
    end else if (zeroize | sampler_mask_clear) begin
      sampler_mask <= '1;
    end else if (sampler_mask_en) begin
      sampler_mask <= sampler_mask_d;
    end else begin
      sampler_mask <= sampler_mask;
    end
  end
  always_comb last_sample = (&rej_value) & shuffler_valid & ~shuffler_hold;
  always_comb valid_sample = data_i[valid_index];
  generate
    for (genvar inst_g = 0; inst_g < SIB_NUM_SAMPLERS; inst_g++) begin : sample_in_ball_inst
      sample_in_ball #(
        .SIB_SAMPLE_W(SIB_SAMPLE_W)
      ) sample_in_ball_i (
        .valid_i(sampler_mask[inst_g]),
        .data_i(data_i[inst_g]),
        .rej_value_i(rej_value),
        .valid_o(sampler_valid[inst_g])
      );
    end
  endgenerate
  always_comb sampler_hold = index_found & (valid_index != (SIB_NUM_SAMPLERS-1));
  sample_in_ball_shuffler #(
    .SIB_SAMPLE_W(SIB_SAMPLE_W)
  ) sib_shuffler_i (
    .clk(clk),
    .rst_b(rst_b),
    .zeroize(zeroize),
    .valid_i(shuffler_valid),
    .hold_o(shuffler_hold),
    .indexi_i(rej_value),
    .indexj_i(valid_sample),
    .sign_i(sign_buffer[0]),
    .cs_o(cs_o),
    .we_o(we_o),
    .addr_o(addr_o),
    .wrdata_o(wrdata_o),
    .rddata_i(rddata_i)
  );
endmodule
module sample_in_ball_shuffler
  import abr_params_pkg::*;
  #(
     parameter SIB_SAMPLE_W = 8
  )
  (
    input logic                          clk,
    input logic                          rst_b,
    input logic                          zeroize,
    input  logic                         valid_i,
    output logic                         hold_o,
    input  logic [SIB_SAMPLE_W-1:0]      indexi_i,
    input  logic [SIB_SAMPLE_W-1:0]      indexj_i,
    input  logic                         sign_i,
    output logic [1:0]                         cs_o,
    output logic [1:0]                         we_o,
    output logic [1:0][7:2]                    addr_o,
    output logic [1:0][3:0][MLDSA_Q_WIDTH-2:0] wrdata_o,
    input  logic [1:0][3:0][MLDSA_Q_WIDTH-2:0] rddata_i
  );
  logic read_valid;
  logic addr_match;
  logic [MLDSA_Q_WIDTH-2:0] nxt_i, nxt_j;
  logic [3:0][MLDSA_Q_WIDTH-2:0] wrdata_pre;
  always_comb hold_o = valid_i & ~read_valid;
  always_comb addr_o[0] = indexj_i[7:2];
  always_comb addr_o[1] = indexi_i[7:2];
  always_ff @(posedge clk or negedge rst_b) begin
    if (!rst_b)begin
      read_valid <= 0;
    end else if (zeroize) begin
      read_valid <= 0;
    end else if (valid_i & ~read_valid) begin
      read_valid <= 1;
    end else begin
      read_valid <= 0;
    end
  end
  always_comb addr_match = indexi_i[7:2] == indexj_i[7:2];
  always_comb nxt_j = sign_i ? MLDSA_Q-1 : 1;
  always_comb begin
    unique case (indexj_i[1:0])
      2'b00: wrdata_o[0] = {rddata_i[0][3],rddata_i[0][2],rddata_i[0][1],nxt_j       };
      2'b01: wrdata_o[0] = {rddata_i[0][3],rddata_i[0][2],nxt_j         ,rddata_i[0][0]};
      2'b10: wrdata_o[0] = {rddata_i[0][3],nxt_j         ,rddata_i[0][1],rddata_i[0][0]};
      2'b11: wrdata_o[0] = {nxt_j         ,rddata_i[0][2],rddata_i[0][1],rddata_i[0][0]};
      default: wrdata_o[0] = 'x;
    endcase
  end
  always_comb nxt_i = rddata_i[0][indexj_i[1:0]];
  always_comb begin
    unique case ({indexi_i[1:0]})
      2'b00: wrdata_pre = {rddata_i[1][3],rddata_i[1][2],rddata_i[1][1],nxt_i       };
      2'b01: wrdata_pre = {rddata_i[1][3],rddata_i[1][2],nxt_i         ,rddata_i[1][0]};
      2'b10: wrdata_pre = {rddata_i[1][3],nxt_i         ,rddata_i[1][1],rddata_i[1][0]};
      2'b11: wrdata_pre = {nxt_i         ,rddata_i[1][2],rddata_i[1][1],rddata_i[1][0]};
      default: wrdata_pre = 'x;
    endcase
  end
  always_comb begin
    unique casez ({addr_match, indexj_i[1:0]})
      3'b0_??: wrdata_o[1] = wrdata_pre;
      3'b1_00: wrdata_o[1] = {wrdata_pre[3],wrdata_pre[2],wrdata_pre[1],nxt_j       };
      3'b1_01: wrdata_o[1] = {wrdata_pre[3],wrdata_pre[2],nxt_j        ,wrdata_pre[0]};
      3'b1_10: wrdata_o[1] = {wrdata_pre[3],nxt_j        ,wrdata_pre[1],wrdata_pre[0]};
      3'b1_11: wrdata_o[1] = {nxt_j        ,wrdata_pre[2],wrdata_pre[1],wrdata_pre[0]};
      default: wrdata_o[1] = 'x;
    endcase
  end
  always_comb cs_o = {2{valid_i}};
  always_comb we_o[0] = read_valid & ~addr_match;
  always_comb we_o[1] = read_valid;
endmodule
module sample_in_ball
  #(
    parameter SIB_SAMPLE_W = 8
  )
  (
  input  logic                    valid_i,
  input  logic [SIB_SAMPLE_W-1:0] data_i,
  input  logic [SIB_SAMPLE_W-1:0] rej_value_i,
  output logic                    valid_o
  );
  always_comb valid_o = valid_i & (data_i <= rej_value_i);
endmodule
module cbd_sampler_ctrl
  import abr_params_pkg::*;
  #(
   localparam CBD_NUM_SAMPLERS = COEFF_PER_CLK
  ,localparam CBD_SAMPLE_W     = 2*MLKEM_ETA
  ,localparam CBD_VLD_SAMPLES  = CBD_NUM_SAMPLERS
  ,localparam CBD_VLD_SAMPLES_W = MLKEM_Q_WIDTH
  )
  (
  input logic clk,
  input logic rst_b,
  input logic zeroize,
  input  logic                                          data_valid_i,
  output logic                                          data_hold_o,
  input  logic [CBD_NUM_SAMPLERS-1:0][CBD_SAMPLE_W-1:0] data_i,
  output logic                                              data_valid_o,
  output logic [CBD_VLD_SAMPLES-1:0][CBD_VLD_SAMPLES_W-1:0] data_o
  );
  logic [CBD_NUM_SAMPLERS-1:0][2:0] sample_data;
  always_comb data_hold_o = 0;
  generate
    for (genvar inst_g = 0; inst_g < CBD_NUM_SAMPLERS; inst_g++) begin : cbd_sampler_inst
      cbd_sampler
      cbd_sampler_i (
        .data_i(data_i[inst_g]),
        .data_o(sample_data[inst_g])
      );
    end
  endgenerate
  always_comb data_valid_o = data_valid_i & ~zeroize;
  always_comb begin
    for (int sample = 0; sample < CBD_VLD_SAMPLES; sample++) begin
      unique case (sample_data[sample])
        3'd0 : data_o[sample] = 0;
        3'd1 : data_o[sample] = 1;
        3'd2 : data_o[sample] = 2;
        3'd7 : data_o[sample] = MLKEM_Q-1;
        3'd6 : data_o[sample] = MLKEM_Q-2;
        default : data_o[sample] = '0;
      endcase
    end
  end
endmodule
module cbd_sampler
  import abr_params_pkg::*;
  #(
   localparam CBD_SAMPLE_W = 2*MLKEM_ETA
  )
  (
  input  logic [CBD_SAMPLE_W-1:0] data_i,
  output logic [2:0] data_o
  );
  logic [CBD_SAMPLE_W-1:0] a;
  logic [MLKEM_ETA-1:0] b;
  logic [MLKEM_ETA-1:0] c;
  assign a = data_i;
  always_comb begin
    b = 0;
    c = 0;
    for (int i = 0; i < MLKEM_ETA; i++) begin
      b += a[i];
      c += a[i+MLKEM_ETA];
    end
    data_o  = b - c; 
  end
endmodule
package abr_sha3_pkg;
  parameter int StateW = 1600;
  parameter int FnWidth = 32;   
  parameter int CsWidth = 256;  
  parameter int MaxFnEncodeSize = ($clog2(FnWidth+1) + 8 - 1) / 8 + 1;
  parameter int MaxCsEncodeSize = ($clog2(CsWidth+1) + 8 - 1) / 8 + 1;
  parameter int NSRegisterSizePre = FnWidth/8       + CsWidth/8
                                  + MaxFnEncodeSize + MaxCsEncodeSize;
  parameter int NSRegisterSize = ((NSRegisterSizePre + 4 - 1 ) / 4) * 4;
  parameter int PrefixSize = NSRegisterSize + 2;
  parameter int PrefixIndexW = $clog2(PrefixSize/64);
  parameter int MsgWidth = 64;
  parameter int MsgStrbW = MsgWidth / 8;
  typedef enum logic[1:0] {
    Sha3   = 2'b 00,
    Shake  = 2'b 10,
    CShake = 2'b 11
  } sha3_mode_e;
  typedef enum logic [2:0] {
    L128 = 3'b 000,  
    L224 = 3'b 001,  
    L256 = 3'b 010,  
    L384 = 3'b 011,  
    L512 = 3'b 100   
  } keccak_strength_e;
  parameter int unsigned KeccakRate [5] = '{
    (1344+MsgWidth-1)/MsgWidth,   
    (1152+MsgWidth-1)/MsgWidth,   
    (1088+MsgWidth-1)/MsgWidth,   
     (832+MsgWidth-1)/MsgWidth,   
     (576+MsgWidth-1)/MsgWidth    
  };
  parameter int unsigned MaxBlockSize = KeccakRate[0];
  parameter int unsigned MsgEntries = (StateW+MsgWidth-1)/MsgWidth;
  parameter int unsigned MsgAddrW = $clog2(MsgEntries);
  parameter int unsigned MsgCountW = $clog2(MsgEntries+1);
  localparam int StateWidth = 6;
  typedef enum logic [StateWidth-1:0] {
    StIdle_sparse = 6'b101100,
    StAbsorb_sparse = 6'b100001,
    StSqueeze_sparse = 6'b001011,
    StManualRun_sparse = 6'b010000,
    StTerminalError_sparse = 6'b111010
  } sha3_st_sparse_e;
  localparam int StateWidthLogic = 3;
  typedef enum logic [StateWidthLogic-1:0] {
    StIdle,
    StAbsorb,
    StSqueeze,
    StManualRun,
    StFlush,
    StError
  } sha3_st_e;
  function automatic sha3_st_e sparse2logic(sha3_st_sparse_e st);
    unique case (st)
      StIdle_sparse      : return StIdle;
      StAbsorb_sparse    : return StAbsorb;
      StSqueeze_sparse   : return StSqueeze;
      StManualRun_sparse : return StManualRun;
      default            : return StError;
    endcase
  endfunction : sparse2logic
  typedef enum logic [7:0] {
    ErrNone = 8'h 00,
    ErrSha3SwControl = 8'h 80
  } err_code_e;
  typedef struct packed {
    logic        valid;
    err_code_e   code;  
    logic [23:0] info;  
  } err_t;
  function automatic logic [15:0] encode_bytepad_len(keccak_strength_e kstrength);
    logic [15:0] result;
    unique case (kstrength)
      L128: result = 16'h A801;  
      L224: result = 16'h 9001;  
      L256: result = 16'h 8801;  
      L384: result = 16'h 6801;  
      L512: result = 16'h 4801;  
      default: result = 16'h 0000;
    endcase
    return result;
  endfunction : encode_bytepad_len
endpackage : abr_sha3_pkg
