  } mubi4_t;
  function automatic logic assert_static_in_package_CheckMuBi4ValsComplementary_A();        
    logic unused_bit [((MuBi4True == ~MuBi4False) ? 1 : -1)];                            
    unused_bit = '{default: 1'b0};                                     
    return unused_bit[0];                                              
  endfunction
  function automatic logic mubi4_test_invalid(mubi4_t val);
    return ~(val inside {MuBi4True, MuBi4False});
