    .Width(Width),
    .ResetValue(ResetValue)
  ) u_state_flop (
    .clk_i,
    .rst_b,
    .d_i(state_i),
    .q_o(state_raw)
  );
  assign state_o = StateEnumT'(state_raw);
    assign unused_err_o = 1'b0;
endmodule
module abr_prim_dom_and_2share #(
  parameter int DW = 64,  
  parameter bit Pipeline = 1'b0  
) (
  input clk_i,
  input rst_b,
  input [DW-1:0] a0_i,  
  input [DW-1:0] a1_i,  
  input [DW-1:0] b0_i,  
  input [DW-1:0] b1_i,  
  input          z_valid_i,  
  input [DW-1:0] z_i,   
  output logic [DW-1:0] q0_o,  
  output logic [DW-1:0] q1_o,  
  output logic [DW-1:0] prd_o  
);
  logic [DW-1:0] t0_d, t0_q, t1_d, t1_q;
  logic [DW-1:0] t_a0b0, t_a1b1;
  logic [DW-1:0] t_a0b0_d, t_a1b1_d;
  logic [DW-1:0] t_a0b1, t_a1b0;
  assign t_a0b0_d = a0_i & b0_i;
  assign t_a1b1_d = a1_i & b1_i;
  assign t_a0b1 = a0_i & b1_i;
  assign t_a1b0 = a1_i & b0_i;
  abr_prim_xor2 #(
    .Width ( DW*2 )
  ) u_abr_prim_xor_t01 (
    .in0_i ( {t_a0b1, t_a1b0} ),
    .in1_i ( {z_i,    z_i}    ),
    .out_o ( {t0_d,   t1_d}   )
  );
  abr_prim_flop_en #(
    .Width      ( DW*2 ),
    .ResetValue ( '0   )
  ) u_abr_prim_flop_t01 (
    .clk_i  ( clk_i        ),
    .rst_b ( rst_b       ),
    .en_i   ( z_valid_i    ),
    .d_i    ( {t0_d, t1_d} ),
    .q_o    ( {t0_q, t1_q} )
  );
  if (Pipeline == 1'b1) begin : gen_inner_domain_regs
    logic [DW-1:0] t_a0b0_q, t_a1b1_q;
    abr_prim_flop_en #(
      .Width      ( DW*2 ),
      .ResetValue ( '0   )
    ) u_abr_prim_flop_tab01 (
      .clk_i  ( clk_i                ),
      .rst_b ( rst_b               ),
      .en_i   ( z_valid_i            ),
      .d_i    ( {t_a0b0_d, t_a1b1_d} ),
      .q_o    ( {t_a0b0_q, t_a1b1_q} )
    );
    assign t_a0b0 = t_a0b0_q;
    assign t_a1b1 = t_a1b1_q;
  end else begin : gen_no_inner_domain_regs
    assign t_a0b0 = t_a0b0_d;
    assign t_a1b1 = t_a1b1_d;
  end
  abr_prim_xor2 #(
    .Width ( DW*2 )
  ) u_abr_prim_xor_q01 (
    .in0_i ( {t_a0b0, t_a1b1} ),
    .in1_i ( {t0_q,   t1_q}   ),
    .out_o ( {q0_o,   q1_o}   )
  );
  assign prd_o = t1_q;
  if (Pipeline == 0) begin: g_assert_stable
  end
endmodule
