    logic [1:0][MLKEM_MASKED_WIDTH-1:0] z0_i;
    logic [1:0][MLKEM_MASKED_WIDTH-1:0] z1_i;
} mlkem_masked_pairwm_zeta_shares_t;
typedef struct packed {
    logic [MLKEM_REG_SIZE-1:0] uv0_o;
    logic [MLKEM_REG_SIZE-1:0] uv1_o;
} mlkem_pwo_t;
typedef struct packed {
    logic [1:0][MASKED_WIDTH-1:0] uv0;
    logic [1:0][MASKED_WIDTH-1:0] uv1;
    logic [1:0][MASKED_WIDTH-1:0] uv2;
    logic [1:0][MASKED_WIDTH-1:0] uv3;
} pwm_shares_uvo_t;
typedef enum logic [2:0] {RD_IDLE, RD_STAGE, RD_BUF, RD_EXEC, EXEC_WAIT} ntt_read_state_t;
typedef enum logic [2:0] {WR_IDLE, WR_STAGE, WR_BUF, WR_MEM, WR_WAIT} ntt_write_state_t;
endpackage
module barrett_reduction #(
    parameter int prime = 3329,
    parameter int REG_SIZE = $clog2(prime)
)(
    input  logic [2*REG_SIZE-1:0]   x,
    output logic [REG_SIZE-1:0]     inv,  
    output logic [REG_SIZE-1:0]     r     
);
    localparam int K = 2*REG_SIZE;
    localparam logic [REG_SIZE:0] m = (1 << K) / prime;
    logic [3*REG_SIZE:0]   mult_full;
    logic [REG_SIZE:0]     u_est, u_plus_one;
    logic [2*REG_SIZE:0]   u_prime, r_est, r_sub_prime;
    logic additional_reduction;
    assign mult_full = x * m;
    assign u_est = mult_full >> K;
    assign u_prime = u_est * prime;
    assign r_est = {1'b0, x} - u_prime;
    assign r_sub_prime = r_est - prime;
    assign u_plus_one = u_est + 1;
    assign additional_reduction = (r_est >= prime);
    assign r   = additional_reduction? r_sub_prime[REG_SIZE-1 : 0] : r_est[REG_SIZE-1 : 0];
    assign inv = additional_reduction? u_plus_one[REG_SIZE-1 : 0] : u_est[REG_SIZE-1 : 0];
endmodule
module masked_barrett_if_cond
    import abr_params_pkg::*;
    import ntt_defines_pkg::*;
    #(
        parameter MASKED_REG_SIZE = 2 * MLKEM_Q_WIDTH
    )
    (
        input wire clk,
        input wire rst_n,
        input wire zeroize,
        input wire [1:0][13:0] c_rolled,
        input wire [11:0] rnd_12bit,
        input wire [13:0] rnd_14bit,
        input wire [13:0] rnd_for_Boolean0,
        input wire [13:0] rnd_for_Boolean1,
        input wire rnd_1bit,
        output logic [1:0][MLKEM_Q_WIDTH-1:0] arith_Q
    );
    logic [1:0] c_rolled_unpacked [13:0];
    logic [1:0] c_boolean [13:0];
    logic [1:0] c_carry;
    logic [1:0][MLKEM_Q_WIDTH-1:0] q_share ;
    logic [1:0][MLKEM_Q_WIDTH-1:0] boolean_y;
    logic [1:0] boolean_y_unpacked [MLKEM_Q_WIDTH-1:0];
    logic [1:0] arith_Q_unpacked [MLKEM_Q_WIDTH-1:0];
    always_comb begin
        for (int i = 0; i < 14; i++) begin
            c_rolled_unpacked[i][1] = c_rolled[1][i];
            c_rolled_unpacked[i][0] = c_rolled[0][i];
        end
    end
    abr_masked_A2B_conv #(
        .WIDTH(14)
    ) barrett_a2b_inst (
        .clk(clk),
        .rst_n(rst_n),
        .zeroize(zeroize),
        .x(c_rolled_unpacked),
        .rnd(rnd_14bit),
        .rnd_for_Boolean0(rnd_for_Boolean0),
        .rnd_for_Boolean1(rnd_for_Boolean1),
        .s(c_boolean)
    );
    abr_masked_OR barrett_or_inst (
        .clk(clk),
        .rst_n(rst_n),
        .zeroize(zeroize),
        .rnd(rnd_1bit),
        .x(c_boolean[13]),
        .y(c_boolean[12]),
        .z(c_carry)
    );
    always_comb begin
        q_share[0] = MLKEM_Q ^ rnd_12bit;
        q_share[1] = rnd_12bit;
    end
    genvar i_AND;
    generate
        for (i_AND = 0; i_AND < MLKEM_Q_WIDTH; i_AND++) begin : gen_DOM_AND
            abr_masked_AND and_gate_inst (
                .clk(clk),
                .rst_n(rst_n),
                .zeroize(zeroize),
                .x(c_carry),
                .y({q_share[1][i_AND], q_share[0][i_AND]}),
                .rnd(rnd_12bit[i_AND]),
                .c(boolean_y_unpacked[i_AND])
            );
        end
    endgenerate
    abr_masked_B2A_conv #(
        .WIDTH(MLKEM_Q_WIDTH)
    ) barrett_b2a_inst (
        .clk(clk),
        .rst_n(rst_n),
        .zeroize(zeroize),
        .x_boolean(boolean_y_unpacked),
        .rnd(rnd_12bit),
        .x_arith(arith_Q_unpacked)
    );
    always_comb begin
        for (int i = 0; i < MLKEM_Q_WIDTH; i++) begin
            arith_Q[0][i] = arith_Q_unpacked[i][0];
            arith_Q[1][i] = arith_Q_unpacked[i][1];
        end
    end
endmodule
module masked_barrett_reduction
    import abr_params_pkg::*;
    import ntt_defines_pkg::*;
    #(
        parameter MASKED_REG_SIZE = 2 * MLKEM_Q_WIDTH
    )
    (
        input wire clk,
        input wire rst_n,
        input wire zeroize,
        input wire [1:0][MASKED_REG_SIZE-1:0] x,
        input wire [11:0] rnd_12bit,
        input wire [13:0] rnd_14bit,
        input wire [MASKED_REG_SIZE-1:0] rnd_24bit,
        input wire [13:0] rnd_for_Boolean0,
        input wire [13:0] rnd_for_Boolean1,
        input wire rnd_1bit,
        output logic [1:0][MASKED_REG_SIZE-1:0] y
    );
    localparam ROLLER = (2**9)+(2**8)-1;
    logic [1:0][MASKED_REG_SIZE+13-1:0] tmp ;
    logic [1:0][12:0] t_int, c_int, c, t;
    logic [13:0] t0_plus_carry, t0_plus_t1, c0_plus_c1;
    logic [1:0][13:0] c_rolled;
    logic carry_x, carry_tmp, carry_t, carry_c, carry_y_int;
    logic [1:0][MASKED_REG_SIZE:0] qt;
    logic [1:0][MASKED_REG_SIZE-1:0] x_reg;
    logic [1:0][11:0] arith_Q;
    logic [2:0][1:0][12:0] c_reg ;
    logic [13:0] carry_t_int;
    logic [1:0][MASKED_REG_SIZE+13-1:0] correction;
    logic [MASKED_REG_SIZE:0] carry_x_ext;
    logic [1:0][MLKEM_Q_WIDTH-1:0] y_int;
    logic [MLKEM_Q_WIDTH:0] carry_y_int_ext;
    logic [MLKEM_Q_WIDTH:0] y_int_comb;
    logic [MASKED_REG_SIZE:0] x_comb;
    always_comb begin
        x_comb = x[0] + x[1];
        carry_x = x_comb[MASKED_REG_SIZE];  
        carry_x_ext = {carry_x, {(MASKED_REG_SIZE){1'b0}}};
        correction[0] = 37'((carry_x_ext << 5) + (carry_x_ext << 3) + (carry_x_ext << 2) + (carry_x_ext << 1) + carry_x_ext);
        correction[1] = 37'((carry_x_ext << 12) + (carry_x_ext << 9) + (carry_x_ext << 8) + (carry_x_ext << 7));
        tmp[0] = (x[0] << 12) + (x[0] << 9) + (x[0] << 8) + (x[0] << 7) + (x[0] << 5) + (x[0] << 3) + (x[0] << 2) + (x[0] << 1) + x[0];
        tmp[1] = (x[1] << 12) + (x[1] << 9) + (x[1] << 8) + (x[1] << 7) + (x[1] << 5) + (x[1] << 3) + (x[1] << 2) + (x[1] << 1) + x[1];
        tmp[0] = (tmp[0] - correction[0]);
        tmp[1] = (tmp[1] - correction[1]);
        carry_tmp  = 25'(tmp[0][MASKED_REG_SIZE-1:0] + tmp[1][MASKED_REG_SIZE-1:0]) >> MASKED_REG_SIZE;
        t_int[0] = (tmp[0] >> MASKED_REG_SIZE);
        t_int[1] = (tmp[1] >> MASKED_REG_SIZE);
        t0_plus_carry = (t_int[0] + {{MLKEM_Q_WIDTH{1'b0}},carry_tmp});
    end
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            t <= '0;
            x_reg <= '0;
            c <= '0;
            for (int i = 0; i < 3; i++) begin
                c_reg[i] <= '0;
            end
        end
        else if (zeroize) begin
            t <= '0;
            x_reg <= '0;
            c <= '0;
            for (int i = 0; i < 3; i++) begin
                c_reg[i] <= '0;
            end
        end 
        else begin
            t[0] <= t0_plus_carry[12:0];
            t[1] <= t_int[1];
            x_reg <= x;
            c <= c_int;
            c_reg <= {c, c_reg[2:1]};
        end
    end
    always_comb begin
        t0_plus_t1 = t[0] + t[1];
        carry_t = t0_plus_t1[13];
        carry_t_int = carry_t ? 'h2000 : 'h0;
        qt[0] = ((t[0] << 11) + (t[0] << 10) + (t[0] << 8) + t[0] - carry_t_int - (carry_t_int << 10));
        qt[1] = 25'(((t[1] << 11) + (t[1] << 10) + (t[1] << 8) + t[1] - (carry_t_int << 8))) - (carry_t_int << 11);
        c_int[0] = 13'(25'(x_reg[0]) - qt[0]);
        c_int[1] = 13'(25'(x_reg[1]) - qt[1]);
        c0_plus_c1 = (c[0] + c[1]);
        carry_c = c0_plus_c1[13];
        c_rolled[0] = c[0] + (ROLLER-(carry_c ? 'h2000 : 'h0));
        c_rolled[1] = {1'b0, c[1]};
    end
    masked_barrett_if_cond_v2 masked_barrett_if_cond_inst (
        .clk(clk),
        .rst_n(rst_n),
        .zeroize(zeroize),
        .c_rolled(c_rolled),
        .rnd_12bit(rnd_12bit),
        .rnd_14bit(rnd_14bit),
        .rnd_for_Boolean0(rnd_for_Boolean0),
        .rnd_for_Boolean1(rnd_for_Boolean1),
        .rnd_1bit(rnd_1bit),
        .arith_Q(arith_Q)
    );
    always_comb begin
        y_int[0] = MLKEM_Q_WIDTH'(c_reg[0][0] - 13'(arith_Q[0]));
        y_int[1] = MLKEM_Q_WIDTH'(c_reg[0][1] - 13'(arith_Q[1]));
        y_int_comb = y_int[0] + y_int[1];
        carry_y_int = y_int_comb[MLKEM_Q_WIDTH];
        carry_y_int_ext = {carry_y_int, {(MLKEM_Q_WIDTH){1'b0}}};
    end
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            y <= '0;
        end
        else if (zeroize) begin
            y <= '0;
        end
        else begin
            y[0] <= MASKED_REG_SIZE'(MASKED_REG_SIZE'(y_int[0]) - rnd_24bit - MASKED_REG_SIZE'(carry_y_int_ext));
            y[1] <= MASKED_REG_SIZE'(MASKED_REG_SIZE'(y_int[1]) + rnd_24bit);
        end
    end
endmodule
module masked_barrett_if_cond_v2
    import abr_params_pkg::*;
    import ntt_defines_pkg::*;
    #(
        parameter MASKED_REG_SIZE = 2 * MLKEM_Q_WIDTH
    )
    (
        input wire clk,
        input wire rst_n,
        input wire zeroize,
        input wire [1:0][13:0] c_rolled,
        input wire [11:0] rnd_12bit,
        input wire [13:0] rnd_14bit,
        input wire [13:0] rnd_for_Boolean0,
        input wire [13:0] rnd_for_Boolean1,
        input wire rnd_1bit,
        output logic [1:0][MLKEM_Q_WIDTH-1:0] arith_Q
    );
    logic [1:0] c_rolled_unpacked [13:0];
    logic [1:0] c_boolean [13:0];
    logic [1:0] c_carry;
    logic [1:0][MLKEM_Q_WIDTH-1:0] q_share ;
    logic [1:0][MLKEM_Q_WIDTH-1:0] boolean_y;
    logic [1:0] boolean_y_unpacked [MLKEM_Q_WIDTH-1:0];
    logic [1:0] arith_Q_unpacked [MLKEM_Q_WIDTH-1:0];
    logic [14:0] c_rolled_comb;
    logic carry0, carry1;
    logic c_carry_comb;
    always_comb begin
        for (int i = 0; i < 14; i++) begin
            c_rolled_unpacked[i][1] = c_rolled[1][i];
            c_rolled_unpacked[i][0] = c_rolled[0][i];
        end
    end
    always_comb begin
        c_rolled_comb = c_rolled[0] + c_rolled[1];
        carry0 = c_rolled_comb[12];
        carry1 = c_rolled_comb[13];
        c_carry_comb = carry0 | carry1;
        c_carry[0] = c_carry_comb ^ rnd_1bit;
        c_carry[1] = rnd_1bit;
    end
    always_comb begin
        q_share[0] = MLKEM_Q ^ rnd_12bit;
        q_share[1] = rnd_12bit;
    end
    genvar i_AND;
    generate
        for (i_AND = 0; i_AND < MLKEM_Q_WIDTH; i_AND++) begin : gen_DOM_AND
            abr_masked_AND and_gate_inst (
                .clk(clk),
                .rst_n(rst_n),
                .zeroize(zeroize),
                .x(c_carry),
                .y({q_share[1][i_AND], q_share[0][i_AND]}),
                .rnd(rnd_14bit[i_AND]),
                .c(boolean_y_unpacked[i_AND])
            );
        end
    endgenerate
    abr_masked_B2A_conv #(
        .WIDTH(MLKEM_Q_WIDTH)
    ) barrett_b2a_inst (
        .clk(clk),
        .rst_n(rst_n),
        .zeroize(zeroize),
        .x_boolean(boolean_y_unpacked),
        .rnd(rnd_14bit[MLKEM_Q_WIDTH-1:0]),
        .x_arith(arith_Q_unpacked)
    );
    always_comb begin
        for (int i = 0; i < MLKEM_Q_WIDTH; i++) begin
            arith_Q[0][i] = arith_Q_unpacked[i][0];
            arith_Q[1][i] = arith_Q_unpacked[i][1];
        end
    end
endmodule
module ntt_butterfly2x2
    import ntt_defines_pkg::*;
    import abr_params_pkg::*;
#(
    parameter REG_SIZE = 23,
    parameter MLDSA_Q = 23'd8380417,
    parameter MLDSA_Q_DIV2_ODD = (MLDSA_Q + 1) / 2
)
(
    input wire clk,
    input wire reset_n,
    input wire zeroize,
    input mode_t mode,
    input wire enable,
    input bf_uvwi_t uvw_i,
    input pwo_uvwi_t pw_uvw_i,
