    always_ff @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            mldsa_w10_reg <= 'h0;
            mldsa_w11_reg <= 'h0;
            mlkem_w10_reg <= 'h0;
            mlkem_w11_reg <= 'h0;
        end
        else if (zeroize) begin
            mldsa_w10_reg <= 'h0;
            mldsa_w11_reg <= 'h0;
            mlkem_w10_reg <= 'h0;
            mlkem_w11_reg <= 'h0;
        end
        else begin
            mldsa_w10_reg <= {uvw_i.w10_i, mldsa_w10_reg[UNMASKED_BF_STAGE1_LATENCY-1:1]};
            mldsa_w11_reg <= {uvw_i.w11_i, mldsa_w11_reg[UNMASKED_BF_STAGE1_LATENCY-1:1]};
            mlkem_w10_reg <= {uvw_i.w10_i[MLKEM_REG_SIZE-1:0], mlkem_w10_reg[MLKEM_UNMASKED_BF_STAGE1_LATENCY-1:1]};
            mlkem_w11_reg <= {uvw_i.w11_i[MLKEM_REG_SIZE-1:0], mlkem_w11_reg[MLKEM_UNMASKED_BF_STAGE1_LATENCY-1:1]};
        end
    end
    assign pwo_mode = (mode inside {pwm, pwa, pws});
    always_comb begin
        if (pwo_mode) begin
            u00 = pw_uvw_i.u0_i;
            v00 = pw_uvw_i.v0_i;
            w00 = pw_uvw_i.w0_i;
            u01 = pw_uvw_i.u1_i;
            v01 = pw_uvw_i.v1_i;
            w01 = pw_uvw_i.w1_i;
            u10 = pw_uvw_i.u2_i;
            v10 = pw_uvw_i.v2_i;
            w10 = pw_uvw_i.w2_i;
            u11 = pw_uvw_i.u3_i;
            v11 = pw_uvw_i.v3_i;
            w11 = pw_uvw_i.w3_i;
        end
        else begin
            u00 = uvw_i.u00_i;
            v00 = uvw_i.v00_i;
            w00 = uvw_i.w00_i;
            u01 = uvw_i.u01_i;
            v01 = uvw_i.v01_i;
            w01 = uvw_i.w01_i;
            u10 = u10_int;
            v10 = v10_int;
            w10 = mlkem ? mlkem_w10_reg[0] : mldsa_w10_reg[0];
            u11 = u11_int;
            v11 = v11_int;
            w11 = mlkem ? mlkem_w11_reg[0] : mldsa_w11_reg[0];
        end
    end
    ntt_butterfly #(
        .REG_SIZE(REG_SIZE)
    )
    bf_inst00(
        .clk(clk),
        .reset_n(reset_n),
        .zeroize(zeroize),
        .mode(mode),
        .mlkem(mlkem),
        .opu_i(u00),
        .opv_i(v00),
        .opw_i(w00),
        .accumulate(accumulate),
        .u_o(u10_int),
        .v_o(u11_int),
        .pwm_res_o(mldsa_pwo_uv_o.uv0)
    );
    ntt_butterfly #(
        .REG_SIZE(REG_SIZE)
    )
    bf_inst01(
        .clk(clk),
        .reset_n(reset_n),
        .zeroize(zeroize),
        .mode(mode),
        .mlkem(mlkem),
        .opu_i(u01),
        .opv_i(v01),
        .opw_i(w01),
        .accumulate(accumulate),
        .u_o(v10_int),
        .v_o(v11_int),
        .pwm_res_o(mldsa_pwo_uv_o.uv1)
    );
    ntt_butterfly #(
        .REG_SIZE(REG_SIZE)
    )
    bf_inst10(
        .clk(clk),
        .reset_n(reset_n),
        .zeroize(zeroize),
        .mode(mode),
        .mlkem(mlkem),
        .opu_i(u10),
        .opv_i(v10),
        .opw_i(w10),
        .accumulate(accumulate),
        .u_o(uv_o.u20_o),
        .v_o(uv_o.v20_o),
        .pwm_res_o(mldsa_pwo_uv_o.uv2)
    );
    ntt_butterfly #(
        .REG_SIZE(REG_SIZE),
        .MLDSA_Q(MLDSA_Q)
    )
    bf_inst11(
        .clk(clk),
        .reset_n(reset_n),
        .zeroize(zeroize),
        .mode(mode),
        .mlkem(mlkem),
        .opu_i(u11),
        .opv_i(v11),
        .opw_i(w11),
        .accumulate(accumulate),
        .u_o(uv_o.u21_o),
        .v_o(uv_o.v21_o),
        .pwm_res_o(mldsa_pwo_uv_o.uv3)
    );
    mlkem_pwo_uvwzi_t pairwm_uvw01_i, pairwm_uvw23_i;
    mlkem_pwo_t pairwm_uv01_o, pairwm_uv23_o;
    always_comb begin
        if (mlkem & (mode == pairwm)) begin
            pairwm_uvw01_i.u0_i = pw_uvw_i.u0_i;
            pairwm_uvw01_i.v0_i = pw_uvw_i.v0_i;
            pairwm_uvw01_i.w0_i = pw_uvw_i.w0_i;
            pairwm_uvw01_i.u1_i = pw_uvw_i.u1_i;
            pairwm_uvw01_i.v1_i = pw_uvw_i.v1_i;
            pairwm_uvw01_i.w1_i = pw_uvw_i.w1_i;
            pairwm_uvw23_i.u0_i = pw_uvw_i.u2_i;
            pairwm_uvw23_i.v0_i = pw_uvw_i.v2_i;
            pairwm_uvw23_i.w0_i = pw_uvw_i.w2_i;
            pairwm_uvw23_i.u1_i = pw_uvw_i.u3_i;
            pairwm_uvw23_i.v1_i = pw_uvw_i.v3_i;
            pairwm_uvw23_i.w1_i = pw_uvw_i.w3_i;
        end
        else begin
            pairwm_uvw01_i = '0;
            pairwm_uvw23_i = '0;
        end
    end
    ntt_karatsuba_pairwm mlkem_pawm_inst0 (
        .clk(clk),
        .reset_n(reset_n),
        .zeroize(zeroize),
        .accumulate(accumulate),
        .pwo_uvw_i(pairwm_uvw01_i),
        .pwo_z_i(mlkem_pairwm_zeta13_i.z0_i),
        .pwo_uv_o(pairwm_uv01_o)
    );
    ntt_karatsuba_pairwm mlkem_pawm_inst1 (
        .clk(clk),
        .reset_n(reset_n),
        .zeroize(zeroize),
        .accumulate(accumulate),
        .pwo_uvw_i(pairwm_uvw23_i),
        .pwo_z_i(mlkem_pairwm_zeta13_i.z1_i),
        .pwo_uv_o(pairwm_uv23_o)
    );
    always_comb begin
        pwo_uv_o.uv0 = mlkem ? pairwm_uv01_o.uv0_o : mldsa_pwo_uv_o.uv0;
        pwo_uv_o.uv1 = mlkem ? pairwm_uv01_o.uv1_o : mldsa_pwo_uv_o.uv1;
        pwo_uv_o.uv2 = mlkem ? pairwm_uv23_o.uv0_o : mldsa_pwo_uv_o.uv2;
        pwo_uv_o.uv3 = mlkem ? pairwm_uv23_o.uv1_o : mldsa_pwo_uv_o.uv3;
    end
    always_ff @(posedge clk or negedge reset_n) begin
        if (!reset_n)
            ready_reg <= 'b0;
        else if (zeroize)
            ready_reg <= 'b0;
        else begin
            if (mlkem) begin
                unique case(mode)
                    ct:  ready_reg <= {4'h0, enable, ready_reg[MLKEM_UNMASKED_BF_LATENCY-1:1]};
                    gs:  ready_reg <= {4'h0, enable, ready_reg[MLKEM_UNMASKED_BF_LATENCY-1:1]};
                    pwm: ready_reg <= '0;
                    pwa: ready_reg <= {9'h0, enable};
                    pws: ready_reg <= {9'h0, enable};
                    pairwm: ready_reg <= accumulate ? {5'h0, enable, ready_reg[MLKEM_UNMASKED_PAIRWM_ACC_LATENCY-1:1]} : {6'h0, enable, ready_reg[MLKEM_UNMASKED_PAIRWM_LATENCY-1:1]};
                    default: ready_reg <= 'h0;
                endcase
            end
            else begin
                unique case(mode)
                    ct:  ready_reg <= {enable, ready_reg[UNMASKED_BF_LATENCY-1:1]};
                    gs:  ready_reg <= {enable, ready_reg[UNMASKED_BF_LATENCY-1:1]};
                    pwm: ready_reg <= accumulate ? {5'h0, enable, ready_reg[UNMASKED_PWM_LATENCY-1:1]} : {6'h0, enable, ready_reg[UNMASKED_PWM_LATENCY-2:1]};
                    pwa: ready_reg <= {9'h0, enable};
                    pws: ready_reg <= {9'h0, enable};
                    pairwm: ready_reg <= 'h0;
                    default: ready_reg <= 'h0;
                endcase
            end
        end
    end
    assign ready_o = ready_reg[0];
endmodule
module ntt_butterfly 
    import ntt_defines_pkg::*;
    import abr_params_pkg::*;
#(
    parameter REG_SIZE  = 23,
    parameter MLDSA_Q     = 23'd8380417,
    parameter MLDSA_Q_DIV2_ODD = (MLDSA_Q + 1) / 2,
    parameter MLKEM_Q = 12'd3329,
    parameter MLKEM_Q_DIV2_ODD = (MLKEM_Q + 1) / 2
)
(
    input wire clk,
    input wire reset_n,
    input wire zeroize,
    input mode_t mode,
    input wire accumulate,
    input wire mlkem,
    input wire   [REG_SIZE-1:0] opu_i,
    input wire   [REG_SIZE-1:0] opv_i,
    input wire   [REG_SIZE-1:0] opw_i,
    output logic [REG_SIZE-1:0]   u_o,
    output logic [REG_SIZE-1:0]   v_o,
    output logic [REG_SIZE-1:0]   pwm_res_o
);
    logic [REG_SIZE-1:0] u_reg, u_reg_d2, u_reg_d3, u_reg_d4;
    logic [REG_SIZE-1:0] w_reg, w_reg_d2, w_reg_d3, w_reg_d4;  
    logic [(2*REG_SIZE)-1:0] vw, vw_reg, mul_res; 
    logic [(2*MLKEM_REG_SIZE)-1:0] mul_res_reg;  
    logic [MLKEM_REG_SIZE-1:0] mlkem_mul_res_reduced;
    logic [22:0] mldsa_mul_res_reduced;
    logic [MLKEM_REG_SIZE-1:0] mlkem_mul_res_reduced_reg;  
    logic [REG_SIZE-1:0] mul_opa, mul_opb;
    logic [REG_SIZE-1:0] u_minus_v, mldsa_u_minus_v_div2;
    logic [MLKEM_REG_SIZE-1:0] mlkem_u_minus_v_div2;
    logic [REG_SIZE-1:0] add_opa, add_opb;
    logic [REG_SIZE-1:0] add_res, add_res_d1, add_res_d2, add_res_d3, add_res_d4, sub_res;
    logic [REG_SIZE-1:0] mldsa_add_res_div2, sub_res_div2, mul_res_reduced_div2;
    logic [MLKEM_REG_SIZE-1:0] mlkem_add_res_div2;
    always_ff @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            u_reg    <= 'h0;
            u_reg_d2 <= 'h0;
            u_reg_d3 <= 'h0; 
            u_reg_d4 <= 'h0;
            w_reg    <= 'h0; 
            w_reg_d2 <= 'h0; 
            w_reg_d3 <= 'h0; 
            w_reg_d4 <= 'h0;
            mul_res_reg <= '0;
            mlkem_mul_res_reduced_reg <= '0;
        end
        else if (zeroize) begin
            u_reg    <= 'h0;
            u_reg_d2 <= 'h0;
            u_reg_d3 <= 'h0; 
            u_reg_d4 <= 'h0;
            w_reg    <= 'h0; 
            w_reg_d2 <= 'h0; 
            w_reg_d3 <= 'h0; 
            w_reg_d4 <= 'h0;
            mul_res_reg <= '0;
            mlkem_mul_res_reduced_reg <= '0;
        end
        else begin
            u_reg    <= opu_i;
            u_reg_d2 <= u_reg;
            u_reg_d3 <= u_reg_d2; 
            u_reg_d4 <= u_reg_d3;
            w_reg    <= opw_i; 
            w_reg_d2 <= w_reg; 
            w_reg_d3 <= w_reg_d2; 
            w_reg_d4 <= w_reg_d3;
            mul_res_reg <= (2*MLKEM_REG_SIZE)'(mul_res);
            mlkem_mul_res_reduced_reg <= mlkem_mul_res_reduced;
        end
    end
    always_ff @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            add_res_d1 <= 'h0;
            add_res_d2 <= 'h0;
            add_res_d3 <= 'h0;
            add_res_d4 <= 'h0;
        end
        else if (zeroize) begin
            add_res_d1 <= 'h0;
            add_res_d2 <= 'h0;
            add_res_d3 <= 'h0;
            add_res_d4 <= 'h0;
        end
        else begin
            add_res_d1 <= add_res;
            add_res_d2 <= add_res_d1;
            add_res_d3 <= add_res_d2;
            add_res_d4 <= add_res_d3;
        end
    end
    always_comb begin
        unique case(mode)
            ct: begin
                u_o = add_res;
                v_o = sub_res;
                pwm_res_o = 'h0;
            end
            gs: begin
                u_o = mlkem ? REG_SIZE'(mlkem_add_res_div2) : mldsa_add_res_div2;
                v_o = mlkem ? REG_SIZE'(mlkem_mul_res_reduced_reg) : mldsa_mul_res_reduced[REG_SIZE-1:0];  
                pwm_res_o = 'h0;
            end
            pwm:begin
                u_o = 'h0;  
                v_o = 'h0;
                pwm_res_o = mlkem ? 'h0 : accumulate ? add_res : mldsa_mul_res_reduced[REG_SIZE-1:0];
            end
            pwa:begin
                u_o = 'h0;  
                v_o = 'h0;
                pwm_res_o = add_res;
            end
            pws:begin
                u_o = 'h0;  
                v_o = 'h0;
                pwm_res_o = u_minus_v;
            end
            pairwm: begin  
                u_o = 'h0;
                v_o = 'h0;
                pwm_res_o = 'h0;
            end
            default: begin
                u_o = 'h0;
                v_o = 'h0;
                pwm_res_o = 'h0;
            end
        endcase
    end
    always_comb begin
        unique case(mode)
            ct: begin
                add_opa = mlkem ? u_reg_d2 : u_reg_d4;
                add_opb = mlkem ? REG_SIZE'(mlkem_mul_res_reduced_reg) : mldsa_mul_res_reduced[REG_SIZE-1:0];
                mul_opa = opv_i;
                mul_opb = opw_i;
            end
            gs: begin
                add_opa = opu_i;
                add_opb = opv_i;
                mul_opa = mlkem ? REG_SIZE'(mlkem_u_minus_v_div2) : mldsa_u_minus_v_div2;  
                mul_opb = w_reg;
            end
            pwm:begin
                add_opa = mlkem ? 'h0 : w_reg_d4;
                add_opb = mlkem ? 'h0 : mldsa_mul_res_reduced[REG_SIZE-1:0];
                mul_opa = opu_i;
                mul_opb = opv_i;
            end
            pwa:begin
                add_opa = opu_i;
                add_opb = opv_i;
                mul_opa = 'h0;
                mul_opb = 'h0;
            end
            default: begin
                add_opa = 'h0;
                add_opb = 'h0;
                mul_opa = 'h0;
                mul_opb = 'h0;
            end
        endcase
    end
    abr_ntt_add_sub_mod #(
        .REG_SIZE(REG_SIZE)
        )
        sub_inst_0(
        .clk(clk),
        .reset_n(reset_n),
        .zeroize(zeroize),
        .add_en_i(1'b1),
        .sub_i(1'b1),
        .opa_i(opu_i),
        .opb_i(opv_i),
        .prime_i(mlkem ? REG_SIZE'(MLKEM_Q) : REG_SIZE'(MLDSA_Q)),
        .mlkem(mlkem),
        .res_o(u_minus_v),
        .ready_o()
    );
    abr_ntt_add_sub_mod #(
        .REG_SIZE(REG_SIZE)
        )
        sub_inst_1(
        .clk(clk),
        .reset_n(reset_n),
        .zeroize(zeroize),
        .add_en_i(1'b1),
        .sub_i(1'b1),
        .opa_i(mlkem ? u_reg_d2 : u_reg_d4),
        .opb_i(mlkem ?  REG_SIZE'(mlkem_mul_res_reduced_reg) : mldsa_mul_res_reduced[REG_SIZE-1:0]),
        .prime_i(mlkem ? REG_SIZE'(MLKEM_Q) : REG_SIZE'(MLDSA_Q)),
        .mlkem(mlkem),
        .res_o(sub_res),
        .ready_o()
    );
    abr_ntt_add_sub_mod #(
        .REG_SIZE(REG_SIZE)
        )
        add_inst_0(
        .clk(clk),
        .reset_n(reset_n),
        .zeroize(zeroize),
        .add_en_i(1'b1),
        .sub_i(1'b0),
        .opa_i(add_opa),
        .opb_i(add_opb),
        .prime_i(mlkem ? REG_SIZE'(MLKEM_Q) : REG_SIZE'(MLDSA_Q)),
        .mlkem(mlkem),
        .res_o(add_res),
        .ready_o()
    );
    ntt_mult_dsp #(
        .RADIX(REG_SIZE)
        )
        mul_inst_0 (
        .A_i(mul_opa),
        .B_i(mul_opb),
        .P_o(mul_res)
    );
    ntt_mult_reduction #(
        .REG_SIZE(23),
        .PRIME(MLDSA_Q)
        )
        mldsa_mul_redux_inst_0 (
        .clk(clk),
        .reset_n(reset_n),
        .zeroize(zeroize),
        .opa_i(mlkem ? '0 : 46'(mul_res)),
        .res_o(mldsa_mul_res_reduced),
        .ready_o()
    );
    barrett_reduction #(
        .REG_SIZE(MLKEM_REG_SIZE),
        .prime(MLKEM_Q)
        )
        mlkem_mul_redux_inst_0 (
        .x(mlkem ? mul_res_reg : '0),
        .inv(),
        .r(mlkem_mul_res_reduced)
    );
    ntt_div2 #(
        .REG_SIZE(REG_SIZE),
        .PRIME(MLDSA_Q)
    )
    mldsa_div2_inst_0 (
        .op_i (add_res_d4),
        .res_o (mldsa_add_res_div2)
    );
    ntt_div2 #(
        .REG_SIZE(REG_SIZE),
        .PRIME(MLDSA_Q)
    )
    mldsa_div2_inst_2 (
        .op_i (u_minus_v),
        .res_o (mldsa_u_minus_v_div2)
    );
    ntt_div2 #(
        .REG_SIZE(MLKEM_REG_SIZE),
        .PRIME(MLKEM_Q)
    )
    mlkem_div2_inst_0 (
        .op_i (add_res_d2[MLKEM_REG_SIZE-1:0]),
        .res_o (mlkem_add_res_div2)
    );
    ntt_div2 #(
        .REG_SIZE(MLKEM_REG_SIZE),
        .PRIME(MLKEM_Q)
    )
    mlkem_div2_inst_2 (
        .op_i (u_minus_v[MLKEM_REG_SIZE-1:0]),
        .res_o (mlkem_u_minus_v_div2)
    );
endmodule
module ntt_mult_dsp #(
    parameter RADIX = 32
)
(
    input  wire  [RADIX-1 : 0]        A_i,
    input  wire  [RADIX-1 : 0]        B_i,
    output logic [(2*RADIX)-1 : 0]    P_o
);
    always_comb begin
        P_o = A_i * B_i;
    end
endmodule
module ntt_mult_reduction #(
    parameter REG_SIZE = 23,
    parameter PRIME = 23'd8380417
)
(
    input wire clk,
    input wire reset_n,
    input wire zeroize,
    input wire [(2*REG_SIZE)-1:0] opa_i,
    output logic [REG_SIZE-1:0] res_o,
    output logic ready_o
);
    logic [2*REG_SIZE-1:0] z;
    logic [2*REG_SIZE-1:0] z_f;
    logic [11:0] c;
    logic [10:0] d;
    logic [REG_SIZE-1:0] e;
    logic [13:0] f;
    logic [REG_SIZE-1:0] g_reduced;
    logic [REG_SIZE-1:0] res;
    logic ready;
    logic ready_e, ready_g_reduced;
    logic enable_reg;
    logic [1:0] push_result_reg;
    always_ff @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            z_f <= 'h0;
        end
        else if (zeroize) begin
            z_f <= 'h0;
        end
        else begin
            z_f <= opa_i;
        end
    end
    always_comb begin
        c = z_f[45:43] + z_f[42:33] + z_f[32:23] + z_f[22:13];
        d = c[11:10] + c[9:0];
        f = z_f[45:43] + z_f[45:33] + c[11:10];
    end
    abr_ntt_add_sub_mod #(
        .REG_SIZE(REG_SIZE)
        )
        mod_add_inst_0(
        .clk(clk),
        .reset_n(reset_n),
        .zeroize(zeroize),
        .add_en_i(1'b1),  
        .sub_i(1'b0),
        .opa_i({{REG_SIZE-14{1'b0}},f[13:0]}),
        .opb_i(z_f[45:23]),
        .prime_i(PRIME),
        .mlkem(1'b0),
        .res_o(e),
        .ready_o()  
    );
    ntt_special_adder #(
        .REG_SIZE(REG_SIZE)
        )
        mod_add_inst_1(
        .clk(clk),
        .reset_n(reset_n),
        .zeroize(zeroize),
        .add_en_i(1'b1),  
        .opa_i(d[10:0]),
        .opb_i(z_f[12:0]),  
        .prime_i(PRIME),
        .res_o(g_reduced),
        .ready_o()  
    );
    abr_ntt_add_sub_mod #(
        .REG_SIZE(REG_SIZE)
        )
        mod_sub_inst_0(
        .clk(clk),
        .reset_n(reset_n),
        .zeroize(zeroize),
        .add_en_i(1'b1),  
        .sub_i(1'b1),
        .opa_i(g_reduced),
        .opb_i(e[22:0]),
        .prime_i(PRIME),
        .mlkem(1'b0),
        .res_o(res),
        .ready_o()  
    );
    always_ff @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            res_o <= 'h0;
        end
        else if (zeroize) begin
            res_o <= 'h0;
        end
        else begin  
            res_o <= res;
        end
    end
endmodule
module ntt_special_adder #(
    parameter REG_SIZE      = 24
    )
    (
    input wire           clk,
    input wire           reset_n,
    input wire           zeroize,
    input  wire                 add_en_i,
    input  wire  [10:0]         opa_i,
    input  wire  [12:0]         opb_i,
    input  wire  [REG_SIZE-1:0] prime_i,
    output logic [REG_SIZE-1:0] res_o,
    output logic                ready_o
);
    logic [REG_SIZE-1 : 0] opb1;
    logic [REG_SIZE-1 : 0] r0;
    logic [REG_SIZE-1 : 0] r1;
    logic                  carry0; 
    logic [REG_SIZE-1 : 0] r0_reg;
    logic                  carry0_reg;
    logic                  carry1;
    logic [1 : 0]          push_result_reg;
    always_comb {carry0, r0} = {opa_i, opb_i};
    always_comb opb1 = ~prime_i;
    abr_adder #(
        .RADIX(REG_SIZE)
        ) 
        adder_inst_1(
        .a_i(r0_reg),
        .b_i(opb1),
        .cin_i(1'b1),
        .s_o(r1),
        .cout_o(carry1)
    );
    always_ff @(posedge clk or negedge reset_n) 
    begin
        if(!reset_n) begin
            r0_reg <= '0;
            carry0_reg <= '0;
        end
        else if (zeroize) begin
            r0_reg <= '0;
            carry0_reg <= '0;
        end
        else if (add_en_i) begin 
            r0_reg <= r0;
            carry0_reg <= carry0;
        end
    end
    always_ff @(posedge clk or negedge reset_n) begin
        if (!reset_n)
            push_result_reg <= 2'b0;
        else if (zeroize)
            push_result_reg <= 2'b0;
        else if (add_en_i)
            push_result_reg <= 2'b10;
        else  
            push_result_reg <= 2'(push_result_reg >> 1);
    end
    assign ready_o = push_result_reg[0];
    assign res_o = (carry0_reg ^ carry1)? r1 : r0_reg;
endmodule
module ntt_masked_special_adder #(
    parameter WIDTH      = 23,
    parameter WIDTH2      = 11,
    parameter WIDTH3      = 13,
    parameter PRIME = 23'd8380417
    )
    (
    input wire           clk,
    input wire           rst_n,
    input wire           zeroize,
    input logic [3*WIDTH-1:0] rnd,
    input  wire  [1:0] d10_0 [WIDTH2-1:0],
    input  wire  [1:0] z_12_0 [WIDTH3-1:0],
    output logic [1:0] res_o_masked [WIDTH-1:0]
);
    logic  [1:0] opa_2_masked_padded [WIDTH:0];
    logic  [1:0] prime [WIDTH:0];
    logic  [1:0] r0_c0 [WIDTH:0];
    logic  [1:0] r1_c1 [WIDTH:0];
    logic  [1:0] r0_c0_delayed [WIDTH:0];
    always_comb begin
        for (int i = 0; i <WIDTH3; i = i + 1)
            r0_c0[i] = z_12_0[i];
        for (int i = WIDTH3; i < (WIDTH+1); i = i + 1)
            r0_c0[i] = d10_0[i-WIDTH3];        
        for (int i = 0; i < WIDTH; i = i + 1) begin
            opa_2_masked_padded[i] = r0_c0[i];
            prime[i]               = {1'b0, ~PRIME[i]};
        end
        opa_2_masked_padded[WIDTH] = 2'b00;
        prime[WIDTH] = 2'b00;
    end
    abr_delay_masked_shares #(
        .WIDTH(WIDTH+1),
        .N(WIDTH+3)  
    ) delay_r0_c0 (
        .clk(clk),
        .rst_n(rst_n),
        .zeroize(zeroize),
        .input_reg(r0_c0),
        .delayed_reg(r0_c0_delayed)
    );
    abr_masked_N_bit_Boolean_sub #(
        .WIDTH(WIDTH+1)
    ) r1_sub_or_add (
        .clk(clk),
        .rst_n(rst_n),
        .zeroize(zeroize),
        .sub_i(1'b1),
        .x(opa_2_masked_padded),
        .y(prime),
        .rnd(rnd[WIDTH:0]),
        .s(r1_c1)
    );
    abr_masked_MUX #(
        .WIDTH(WIDTH)
    ) r0_MUX_r0 (
        .clk(clk),
        .rst_n(rst_n),
        .zeroize(zeroize),
        .sub_i(1'b0),
        .carry0(r0_c0_delayed[WIDTH]),
        .carry1(r1_c1[WIDTH]),
        .r0(r0_c0_delayed[WIDTH-1:0]),
        .r1(r1_c1[WIDTH-1:0]),
        .rnd_xor(rnd[WIDTH*2-1:WIDTH]),
        .rnd_and(rnd[WIDTH*3-1:2*WIDTH]),
        .res_o_masked(res_o_masked)
    );
endmodule
module ntt_masked_mult_redux46
    import ntt_defines_pkg::*;
    import abr_params_pkg::*;
#(
    parameter WIDTH = 46
)
(
    input wire clk,
    input wire rst_n,
    input wire zeroize,
    input wire [10:0] rnd0_11,
    input wire [10:0] rnd1_11,
    input wire [10:0] rnd2_11,
    input wire [11:0] rnd0_12,
    input wire [3:0] rnd0_4,
    input wire [13:0] rnd0_14,
    input wire [3*(WIDTH/2)-1:0] rnd_3WIDTH,
    input wire [1:0] x [WIDTH-1:0],
    output logic [1:0] y [WIDTH/2-1:0]
);
    logic [4:0] cnt;
    logic [1:0] z_45_23 [22:0];
    logic [1:0] z_45_23_delayed [22:0];
    logic [1:0] z_45_33 [13:0];
    logic [1:0] z_45_33_delayed [13:0];
    logic [1:0] z_45_43 [3:0];
    logic [1:0] z_45_43_delayed [3:0];
    logic [1:0] z_45_43_padded_8 [10:0];
    logic [1:0] z_12_0 [12:0];
    logic [1:0] z_12_0_delayed [12:0];
    logic [1:0] z_22_13 [10:0];
    logic [1:0] z_32_23 [10:0];
    logic [1:0] z_42_33 [10:0];
    logic [1:0] tmp [10:0];
    logic [1:0] tmp_padded [11:0];
    logic [1:0] tmp0 [10:0];
    logic [1:0] tmp0_padded [11:0];
    logic [1:0] c0_11 [11:0];
    logic [1:0] c11_10 [1:0];
    logic [1:0] c11_10_padded_9 [10:0];
    logic [1:0] c11_10_padded_2 [3:0];
