module ntt_div2
    #(
        parameter REG_SIZE      = 23,
        parameter PRIME   = 23'd8380417,
        parameter PRIME_DIV2_ODD = (PRIME + 1) / 2
    )
    (
        input  wire  [REG_SIZE-1:0] op_i,
        output logic [REG_SIZE-1:0] res_o
    );
    always_comb res_o = op_i[0] ? REG_SIZE'((op_i >> 1) + PRIME_DIV2_ODD)
                                             : REG_SIZE'(op_i >> 1);
endmodule
module ntt_buffer
    import ntt_defines_pkg::*;
#(
    parameter REG_SIZE = 23
)
(
    input wire clk,
    input wire reset_n,
    input wire zeroize,
    input wire wren,  
    input wire rden,  
    input wire wr_rst_count,
    input wire rd_rst_count,
    input mode_t mode,
    input wire [(4*REG_SIZE)-1:0] data_i,
    output logic buf0_valid,
    output logic [(4*REG_SIZE)-1:0] data_o
);
    logic [3:0][REG_SIZE-1:0] buf0;   
    logic [4:0][REG_SIZE-1:0] buf1;   
    logic [5:0][REG_SIZE-1:0] buf2;   
    logic [6:0][REG_SIZE-1:0] buf3;   
    logic [1:0] data_i_count, data_i_count_reg;
    logic [1:0] data_o_count;
    logic wren_reg;
    always_ff @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            buf0 <= 'h0;
            buf1 <= 'h0;
            buf2 <= 'h0;
            buf3 <= 'h0;
        end
        else if (zeroize) begin
            buf0 <= 'h0;
            buf1 <= 'h0;
            buf2 <= 'h0;
            buf3 <= 'h0;
        end
        else if (wren) begin
                buf0 <= {data_i[REG_SIZE-1:0], buf0[3:1]};
                buf1 <= {data_i[(2*REG_SIZE)-1:REG_SIZE], buf1[4:1]};
                buf2 <= {data_i[(3*REG_SIZE)-1:(2*REG_SIZE)], buf2[5:1]};
                buf3 <= {data_i[(4*REG_SIZE)-1:(3*REG_SIZE)], buf3[6:1]};
        end
    end
    always_ff @(posedge clk or negedge reset_n) begin
        if (!reset_n)
            data_o_count <= 'h0;
        else if (zeroize)
            data_o_count <= 'h0;
        else if (rd_rst_count)
            data_o_count <= 'h0;
        else if (rden)
            data_o_count <= data_o_count + 'h1;
    end
    always_ff @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            data_i_count <= 'h0;
            data_i_count_reg <= 'h0;
        end
        else if (zeroize) begin
            data_i_count <= 'h0;
            data_i_count_reg <= 'h0;
        end
        else if (wr_rst_count) begin
            data_i_count <= 'h0;
            data_i_count_reg <= 'h0;
        end
        else if (wren) begin
            data_i_count <= data_i_count + 'h1;
            data_i_count_reg <= data_i_count;
        end
    end
    assign buf0_valid = (data_i_count_reg == 'd3);
    always_comb begin
        case(data_o_count)
            'd0: data_o = {buf0[3],buf0[2],buf0[1],buf0[0]};
            'd1: data_o = {buf1[3],buf1[2],buf1[1],buf1[0]};
            'd2: data_o = {buf2[3],buf2[2],buf2[1],buf2[0]};
            'd3: data_o = {buf3[3],buf3[2],buf3[1],buf3[0]};
        endcase
    end
endmodule
module ntt_shuffle_buffer
    import abr_params_pkg::*;
    import ntt_defines_pkg::*;
    #(
        parameter REG_SIZE = 24
    )
    (
        input wire clk,
        input wire reset_n,
        input wire zeroize,
        input mode_t mode,
        input wire shuffle_en,
        input wire wren,
        input wire rden,
        input wire [1:0] wrptr,
        input wire [1:0] rdptr,
        input wire wr_rst_count,
        input wire [(4*REG_SIZE)-1:0] data_i,
        output logic buf_valid,
        output logic [(4*REG_SIZE)-1:0] data_o
    );
        logic [1:0][3:0][3:0][REG_SIZE-1:0] buffer;  
        logic [1:0] data_i_count, data_i_count_reg;
        logic lo_hi, lo_hi_reg, lo_hi_rd;  
        always_ff @(posedge clk or negedge reset_n) begin
            if (!reset_n) begin
                buffer <= 'h0;
            end
            else if (zeroize) begin
                buffer <= 'h0;
            end
            else if (wren) begin
                buffer[lo_hi][wrptr] <= data_i;  
            end
        end
        always_ff @(posedge clk or negedge reset_n) begin
            if (!reset_n) begin
                data_i_count <= 'h0;
                data_i_count_reg <= 'h0;
            end
            else if (zeroize) begin
                data_i_count <= 'h0;
                data_i_count_reg <= 'h0;
            end
            else if (wr_rst_count) begin
                data_i_count <= 'h0;
                data_i_count_reg <= 'h0;
            end
            else if (wren) begin
                data_i_count <= data_i_count + 'h1;
                data_i_count_reg <= data_i_count;
            end
        end
        always_comb begin
            buf_valid = (data_i_count_reg == 'd3);
            lo_hi = buf_valid ^ lo_hi_reg;
            lo_hi_rd = (shuffle_en & (mode == 0)) ? lo_hi_reg : lo_hi;  
        end
        always_ff @(posedge clk or negedge reset_n) begin
            if (!reset_n)
                lo_hi_reg <= 'b0;
            else if (zeroize)
                lo_hi_reg <= 'b0;
            else if (buf_valid)
                lo_hi_reg <= ~lo_hi_reg;
        end
        always_comb begin
            data_o = '0;
            if (lo_hi_rd) begin
                data_o = {buffer[0][3][rdptr], buffer[0][2][rdptr], buffer[0][1][rdptr], buffer[0][0][rdptr]};
            end else if (~lo_hi_rd) begin
                data_o = {buffer[1][3][rdptr], buffer[1][2][rdptr], buffer[1][1][rdptr], buffer[1][0][rdptr]};
            end
        end
endmodule
