        .zeroize(zeroize),
        .sub(1'b0),
        .u(opu_i),
        .v(opv_i),
        .rnd(rnd_i[3:0]),
        .rnd_24bit({rnd_i[0][9:0], rnd_i[4]}),
        .res(add_res)
    );
    always_comb begin
        for (int i = 0; i < WIDTH; i++) begin
            add_res_unpacked[i][0] = add_res[0][i];
            add_res_unpacked[i][1] = add_res[1][i];
        end
    end
    abr_delay_masked_shares #(
        .WIDTH(WIDTH),
