    pwm_shares_uvo.uv1 = pairwm_mode ? {WIDTH'(mlkem_uv1_share[1]), WIDTH'(mlkem_uv1_share[0])} : mldsa_uv1_share;
    pwm_shares_uvo.uv2 = pairwm_mode ? {WIDTH'(mlkem_uv2_share[1]), WIDTH'(mlkem_uv2_share[0])} : bf_pwm_shares_uvo.uv2;
    pwm_shares_uvo.uv3 = pairwm_mode ? {WIDTH'(mlkem_uv3_share[1]), WIDTH'(mlkem_uv3_share[0])} : bf_pwm_shares_uvo.uv3;
end
    logic [MASKED_INTT_LATENCY-1:0] masked_ready_reg;  
    always_ff @(posedge clk or negedge reset_n) begin
        if (!reset_n)
            masked_ready_reg <= 'b0;
        else if (zeroize)
            masked_ready_reg <= 'b0;
        else begin
            if (mlkem) begin
                unique case(mode)
                    ct: masked_ready_reg <= {{(MASKED_INTT_LATENCY-MLKEM_UNMASKED_BF_LATENCY){1'b0}}, enable, masked_ready_reg[MLKEM_UNMASKED_BF_LATENCY-1:1]};
                    gs: begin
                        if (masking_en)
                            masked_ready_reg <= {{(MASKED_INTT_LATENCY-MLKEM_MASKED_INTT_LATENCY){1'b0}}, enable, masked_ready_reg[MLKEM_MASKED_INTT_LATENCY-1:1]};
                        else
                            masked_ready_reg <= {{(MASKED_INTT_LATENCY-MLKEM_UNMASKED_BF_LATENCY){1'b0}}, enable, masked_ready_reg[MLKEM_UNMASKED_BF_LATENCY-1:1]};
                    end
                    pwm: masked_ready_reg <= 'b0;
                    pwa: masked_ready_reg <= {{MASKED_INTT_LATENCY-1{1'b0}}, enable};
                    pws: masked_ready_reg <= {{MASKED_INTT_LATENCY-1{1'b0}}, enable};
                    pairwm: begin
                        if (masking_en)
                            masked_ready_reg <= accumulate ? {{(MASKED_INTT_LATENCY-MLKEM_MASKED_PAIRWM_ACC_LATENCY){1'b0}}, enable, masked_ready_reg[MLKEM_MASKED_PAIRWM_ACC_LATENCY-1:1]}
                                                            : {{(MASKED_INTT_LATENCY-MLKEM_MASKED_PAIRWM_LATENCY){1'b0}}, enable, masked_ready_reg[MLKEM_MASKED_PAIRWM_LATENCY-1:1]};
                        else
                            masked_ready_reg <= accumulate ? {{(MASKED_INTT_LATENCY-MLKEM_UNMASKED_PAIRWM_ACC_LATENCY){1'b0}}, enable, masked_ready_reg[MLKEM_UNMASKED_PAIRWM_ACC_LATENCY-1:1]}
                                                                               : {{(MASKED_INTT_LATENCY-MLKEM_UNMASKED_PAIRWM_LATENCY){1'b0}}, enable, masked_ready_reg[MLKEM_UNMASKED_PAIRWM_LATENCY-1:1]};
                    end
                    default: masked_ready_reg <= 'b0;
                endcase
            end
            else begin
                unique case(mode)  
                    ct:  masked_ready_reg <= {{(MASKED_INTT_LATENCY-UNMASKED_BF_LATENCY){1'b0}}, enable, masked_ready_reg[UNMASKED_BF_LATENCY-1:1]};
                    gs: begin 
                        if (masking_en)
                            masked_ready_reg <= {1'b0, enable, masked_ready_reg[MASKED_INTT_LATENCY-1:1]};
                        else
                            masked_ready_reg <= {{(MASKED_INTT_LATENCY-UNMASKED_BF_LATENCY){1'b0}}, enable, masked_ready_reg[UNMASKED_BF_LATENCY-1:1]};
                    end
                    pwm: begin
                        if (masking_en) begin
                            if (shuffle_en)
                                masked_ready_reg <= accumulate ? {{(MASKED_INTT_LATENCY-MASKED_PWM_ACC_LATENCY){1'b0}}, enable, masked_ready_reg[MASKED_PWM_ACC_LATENCY-1:1]} : {{(MASKED_INTT_LATENCY-MASKED_PWM_LATENCY-1){1'b0}}, enable, masked_ready_reg[MASKED_PWM_LATENCY-2:1]};
                            else
                                masked_ready_reg <= accumulate ? {{(MASKED_INTT_LATENCY-MASKED_PWM_ACC_LATENCY){1'b0}}, enable, masked_ready_reg[MASKED_PWM_ACC_LATENCY-1:1]} : {{(MASKED_INTT_LATENCY-MASKED_PWM_LATENCY-1){1'b0}}, enable, masked_ready_reg[MASKED_PWM_LATENCY-2:1]};
                        end
                        else
                            masked_ready_reg <= accumulate ? {{(MASKED_INTT_LATENCY-UNMASKED_PWM_LATENCY){1'b0}}, enable, masked_ready_reg[UNMASKED_PWM_LATENCY-1:1]} : {6'h0, enable, masked_ready_reg[UNMASKED_PWM_LATENCY-2:1]};
                    end
                    pwa: masked_ready_reg <= {{MASKED_INTT_LATENCY-1{1'b0}}, enable};
                    pws: masked_ready_reg <= {{MASKED_INTT_LATENCY-1{1'b0}}, enable};
                    pairwm: masked_ready_reg <= 'b0;
                    default: masked_ready_reg <= 'h0;
                endcase
            end
        end
    end
    assign ready_o = masked_ready_reg[0];
endmodule
module ntt_karatsuba_pairwm
    import ntt_defines_pkg::*;
    import abr_params_pkg::*;
(
    input wire clk,
    input wire reset_n,
    input wire zeroize,
    input wire accumulate,
    input mlkem_pwo_uvwzi_t pwo_uvw_i,
    input [MLKEM_REG_SIZE-1:0] pwo_z_i,
    output mlkem_pwo_t pwo_uv_o
);
logic [MLKEM_REG_SIZE-1:0] u0, u1, v0, v1, w0, w1, z1;
logic [(2*MLKEM_REG_SIZE)-1:0] uv00, uv01, uv11, mul_res_uv12, uvz11;
logic [MLKEM_REG_SIZE-1:0] uv00_reduced, uv11_reduced, mul_res_uv12_reduced, sub_res1, uvz11_reduced;
logic [REG_SIZE-1:0] add_res_u, add_res_v, sub_res0;
always_comb begin
    u0 = pwo_uvw_i.u0_i;
    u1 = pwo_uvw_i.u1_i;
    v0 = pwo_uvw_i.v0_i;
    v1 = pwo_uvw_i.v1_i;
    w0 = pwo_uvw_i.w0_i;
    w1 = pwo_uvw_i.w1_i;
    z1 = pwo_z_i;
end
ntt_mult_dsp #(
    .RADIX(MLKEM_REG_SIZE)
    )
    mul_inst_0 (
    .A_i(u0),
    .B_i(v0),
    .P_o(uv00)
);
barrett_reduction #(
    .REG_SIZE(MLKEM_REG_SIZE),
    .prime(MLKEM_Q)
)
mul_redux_inst_0 (
    .x(uv00),
    .inv(),
    .r(uv00_reduced)
);
logic [2:0][MLKEM_REG_SIZE-1:0] uv00_reduced_reg, uv11_reduced_reg, z1_reg;
logic [3:0][MLKEM_REG_SIZE-1:0] w0_reg, w1_reg;
logic [REG_SIZE-1:0] uv0_o_int, uv1_o_int, uv1_o_int_reg, uv0_o_acc, uv1_o_acc;
always_ff @(posedge clk or negedge reset_n) begin
    if (!reset_n) begin
        uv00_reduced_reg <= '0;
        uv11_reduced_reg <= '0;
        z1_reg <= '0;
        w0_reg <= '0;
        w1_reg <= '0;
        uv1_o_int_reg <= '0;
    end
    else if (zeroize) begin
        uv00_reduced_reg <= '0;
        uv11_reduced_reg <= '0;
        z1_reg <= '0;
        w0_reg <= '0;
        w1_reg <= '0;
        uv1_o_int_reg <= '0;
    end
    else begin
        uv00_reduced_reg <= {uv00_reduced_reg[1:0], uv00_reduced};
        uv11_reduced_reg <= {uv11_reduced_reg[1:0], uv11_reduced};
        z1_reg <= {z1_reg[1:0], z1};
        w0_reg <= {w0_reg[2:0], w0};
        w1_reg <= {w1_reg[2:0], w1};
        uv1_o_int_reg <= uv1_o_int;
    end
end
ntt_mult_dsp #(
    .RADIX(MLKEM_REG_SIZE)
    )
    mul_inst_3 (
    .A_i(u1),
    .B_i(v1),
    .P_o(uv11)
);
barrett_reduction #(
    .REG_SIZE(MLKEM_REG_SIZE),
    .prime(MLKEM_Q)
)
mul_redux_inst_3 (
    .x(uv11),
    .inv(),
    .r(uv11_reduced)
);
ntt_mult_dsp #(
    .RADIX(MLKEM_REG_SIZE)
)
mul_inst_zeta (
    .A_i(uv11_reduced_reg[2]),
    .B_i(z1_reg[2]),
    .P_o(uvz11)
);
barrett_reduction #(
    .REG_SIZE(MLKEM_REG_SIZE),
    .prime(MLKEM_Q)
)
mul_zeta_redux_inst (
    .x(uvz11),
    .inv(),
    .r(uvz11_reduced)
);
abr_ntt_add_sub_mod #(
    .REG_SIZE(REG_SIZE)  
)
add_inst_uvz11(
    .clk(clk),
    .reset_n(reset_n),
    .zeroize(zeroize),
    .add_en_i(1'b1),
    .sub_i(1'b0),
    .opa_i(REG_SIZE'(uvz11_reduced)),
    .opb_i(REG_SIZE'(uv00_reduced_reg[2])),
    .prime_i(REG_SIZE'(MLKEM_Q)),
    .mlkem(1'b1),
    .res_o(uv0_o_int),
    .ready_o()
);
abr_ntt_add_sub_mod #(
    .REG_SIZE(REG_SIZE)
)
add_inst_u(
    .clk(clk),
    .reset_n(reset_n),
    .zeroize(zeroize),
    .add_en_i(1'b1),
    .sub_i(1'b0),
    .opa_i(REG_SIZE'(u0)),
    .opb_i(REG_SIZE'(u1)),
    .prime_i(REG_SIZE'(MLKEM_Q)),
    .mlkem(1'b1),
    .res_o(add_res_u),
    .ready_o()
);
abr_ntt_add_sub_mod #(
    .REG_SIZE(REG_SIZE)
)
add_inst_v(
    .clk(clk),
    .reset_n(reset_n),
    .zeroize(zeroize),
    .add_en_i(1'b1),
    .sub_i(1'b0),
    .opa_i(REG_SIZE'(v0)),
    .opb_i(REG_SIZE'(v1)),
    .prime_i(REG_SIZE'(MLKEM_Q)),
    .mlkem(1'b1),
    .res_o(add_res_v),
    .ready_o()
);
ntt_mult_dsp #(
    .RADIX(MLKEM_REG_SIZE)
    )
    mul_inst_12 (
    .A_i(add_res_u[MLKEM_REG_SIZE-1:0]),
    .B_i(add_res_v[MLKEM_REG_SIZE-1:0]),
