        .debugUnlock_or_scan_mode_switch(debugUnlock_or_scan_mode_switch),
        .ocp_lock_in_progress(ocp_lock_in_progress),
        .key_release_addr    (key_release_addr    ),
        .key_release_size    (key_release_size    ),
        .aes_input_ready,
