        .aes_status_idle,
        .aes_req_dv,
        .aes_req_hold,
        .aes_req_data,
        .aes_rdata,
        .aes_err,
        .kv_read   (kv_read   ),
        .kv_rd_resp(kv_rd_resp),
        .mb_dv   (mb_dv   ),
        .mb_hold (mb_hold ),
        .mb_error(mb_error),
        .mb_data (mb_data ),
        .mb_rdata(mb_rdata),
        .r_req_if (r_req_if.src),
        .r_ready_o(r_ready     ),
        .r_valid_i(r_valid     ),
        .r_data_i (r_data      ),
        .w_req_if (w_req_if.src),
        .w_ready_i(w_ready     ),
        .w_valid_o(w_valid     ),
        .w_data_o (w_data      ),
        .dv      (dv      ),
        .req_data(req_data),
        .hold    (hold    ),
        .rdata   (rdata   ),
        .error   (error   ),
        .notif_intr(notif_intr),
        .error_intr(error_intr)
    );
    axi_mgr_rd #(
        .AW(AW),
        .DW(DW),
        .UW(UW),
        .IW(IW)
    ) i_axi_mgr_rd (
        .clk(clk),
        .rst_n(rst_n),
        .m_axi_if(m_axi_r_if),
        .req_if(r_req_if.snk),
        .axuser(axuser),
        .ready_i(r_ready),
        .valid_o(r_valid),
        .data_o (r_data )
    );
    axi_mgr_wr #(
        .AW(AW),
        .DW(DW),
        .UW(UW),
        .IW(IW)
    ) i_axi_mgr_wr (
        .clk  (clk  ),
        .rst_n(rst_n),
        .m_axi_if(m_axi_w_if),
        .req_if(w_req_if.snk),
        .axuser(axuser),
        .valid_i(w_valid),
        .data_i (w_data ),
        .ready_o(w_ready)
    );
endmodule
