        wdt_error_t2_intr_serviced <= soc_ifc_reg_req_data.wdata[(7)];
    end
    else begin
        wdt_error_t1_intr_serviced <= 1'b0;
        wdt_error_t2_intr_serviced <= 1'b0;
    end
