        .crypt_d_no            ( sp_crypt_d[i]            ),  
        .dec_key_gen_q_ni      ( sp_dec_key_gen_q[i]      ),  
        .dec_key_gen_d_no      ( sp_dec_key_gen_d[i]      ),  
        .prng_reseed_q_i       ( prng_reseed_q            ),
