  logic          [Sp2VWidth-1:0] mr_input_ready;
  logic          [Sp2VWidth-1:0] mr_input_ready_we;
  logic [Sp2VWidth-1:0][NumSharesKey-1:0][NumRegsKey-1:0]                int_key_init_we;
  logic                [NumSharesKey-1:0][NumRegsKey-1:0][Sp2VWidth-1:0] log_key_init_we;
  logic                [NumSharesKey-1:0][NumRegsKey-1:0]                int_key_init_qe;
  for (genvar s = 0; s < NumSharesKey; s++) begin : gen_conv_key_init_wqe_shares
    for (genvar i = 0; i < NumRegsKey; i++) begin : gen_conv_key_init_wqe_regs
      assign int_key_init_qe[s][i] = key_init_qe_i[s][i];
      for (genvar j = 0; j < Sp2VWidth; j++) begin : gen_conv_key_init_wqe_log
        assign log_key_init_we[s][i][j] = int_key_init_we[j][s][i];
      end
      assign key_init_we_o[s][i] = sp2v_e'(log_key_init_we[s][i]);
    end
  end
  logic [Sp2VWidth-1:0][NumSlicesCtr-1:0]                int_ctr_we;
  logic                [NumSlicesCtr-1:0][Sp2VWidth-1:0] log_ctr_we;
  logic [Sp2VWidth-1:0][NumSlicesCtr-1:0]                int_iv_we;
  logic                [NumSlicesCtr-1:0][Sp2VWidth-1:0] log_iv_we;
  for (genvar i = 0; i < NumSlicesCtr; i++) begin : gen_conv_ctr_iv_we_slices
    assign log_ctr_we[i] = {ctr_we[i]};
    for (genvar j = 0; j < Sp2VWidth; j++) begin : gen_conv_ctr_iv_we_log
      assign int_ctr_we[j][i] = log_ctr_we[i][j];
      assign log_iv_we[i][j]  = int_iv_we[j][i];
    end
    assign iv_we_o[i] = sp2v_e'(log_iv_we[i]);
  end
  assign sp_ctr_ready             = {ctr_ready};
  assign sp_cipher_in_ready       = {cipher_in_ready};
  assign sp_cipher_out_valid      = {cipher_out_valid};
  assign sp_in_cipher_crypt       = {cipher_crypt};
  assign sp_in_cipher_dec_key_gen = {cipher_dec_key_gen};
  assign sp_ghash_in_ready        = {ghash_in_ready};
  assign sp_ghash_out_valid       = {ghash_out_valid};
  for (genvar i = 0; i < Sp2VWidth; i++) begin : gen_fsm
    if (SP2V_LOGIC_HIGH[i] == 1'b1) begin : gen_fsm_p
      aes_control_fsm_p #(
        .AESGCMEnable ( AESGCMEnable ),
        .SecMasking   ( SecMasking   )
      ) u_aes_control_fsm_i (
        .clk_i                     ( clk_i                         ),
        .rst_ni                    ( rst_ni                        ),
        .ctrl_qe_i                 ( ctrl_qe_i                     ),
        .ctrl_we_o                 ( mr_ctrl_we[i]                 ),  
        .ctrl_phase_i              ( ctrl_phase_i                  ),
        .ctrl_err_storage_i        ( ctrl_err_storage_i            ),
        .op_i                      ( op_i                          ),
        .mode_i                    ( mode_i                        ),
        .cipher_op_i               ( cipher_op_i                   ),
        .sideload_i                ( sideload_i                    ),
        .prng_reseed_rate_i        ( prng_reseed_rate_i            ),
        .manual_operation_i        ( manual_operation_i            ),
        .key_touch_forces_reseed_i ( key_touch_forces_reseed_i     ),
        .ctrl_gcm_qe_i             ( ctrl_gcm_qe_i                 ),
        .ctrl_gcm_we_o             ( mr_ctrl_gcm_we[i]             ),  
        .ctrl_gcm_phase_i          ( ctrl_gcm_phase_i              ),
        .gcm_init_done_o           ( mr_gcm_init_done[i]           ),  
        .gcm_phase_i               ( gcm_phase_i                   ),
        .start_i                   ( start_trigger                 ),
        .key_iv_data_in_clear_i    ( key_iv_data_in_clear_i        ),
        .data_out_clear_i          ( data_out_clear_i              ),
        .prng_reseed_i             ( prng_reseed_i                 ),
        .mux_sel_err_i             ( mux_sel_err                   ),
        .sp_enc_err_i              ( sp_enc_err                    ),
        .lc_escalate_en_i          ( lc_escalate_en_i              ),
        .alert_fatal_i             ( alert_fatal_i                 ),
        .alert_o                   ( mr_alert[i]                   ),  
        .key_sideload_valid_i      ( key_sideload_valid_i          ),
        .key_init_qe_i             ( int_key_init_qe               ),
        .iv_qe_i                   ( iv_qe_i                       ),
        .data_in_qe_i              ( data_in_qe_i                  ),
        .data_out_re_i             ( data_out_re_i                 ),
        .data_in_we_o              ( mr_data_in_we[i]              ),  
        .data_out_sel_o            ( mr_data_out_sel[i]            ),  
        .data_out_we_o             ( sp_data_out_we[i]             ),  
        .data_in_prev_sel_o        ( mr_data_in_prev_sel[i]        ),  
        .data_in_prev_we_o         ( sp_data_in_prev_we[i]         ),  
        .state_in_sel_o            ( mr_state_in_sel[i]            ),  
        .add_state_in_sel_o        ( mr_add_state_in_sel[i]        ),  
        .add_state_out_sel_o       ( mr_add_state_out_sel[i]       ),  
        .ctr_inc32_o               ( sp_ctr_inc32[i]               ),  
        .ctr_incr_o                ( sp_ctr_incr[i]                ),  
        .ctr_ready_i               ( sp_ctr_ready[i]               ),  
        .ctr_we_i                  ( int_ctr_we[i]                 ),  
        .cipher_in_valid_o         ( sp_cipher_in_valid[i]         ),  
        .cipher_in_ready_i         ( sp_cipher_in_ready[i]         ),  
        .cipher_out_valid_i        ( sp_cipher_out_valid[i]        ),  
        .cipher_out_ready_o        ( sp_cipher_out_ready[i]        ),  
        .cipher_crypt_o            ( sp_out_cipher_crypt[i]        ),  
        .cipher_crypt_i            ( sp_in_cipher_crypt[i]         ),  
        .cipher_dec_key_gen_o      ( sp_out_cipher_dec_key_gen[i]  ),  
        .cipher_dec_key_gen_i      ( sp_in_cipher_dec_key_gen[i]   ),  
        .cipher_prng_reseed_o      ( mr_cipher_prng_reseed[i]      ),  
        .cipher_prng_reseed_i      ( cipher_prng_reseed_i          ),
        .cipher_key_clear_o        ( mr_cipher_key_clear[i]        ),  
        .cipher_key_clear_i        ( cipher_key_clear_i            ),
        .cipher_data_out_clear_o   ( mr_cipher_data_out_clear[i]   ),  
        .cipher_data_out_clear_i   ( cipher_data_out_clear_i       ),
        .ghash_in_valid_o          ( sp_ghash_in_valid[i]          ),  
        .ghash_in_ready_i          ( sp_ghash_in_ready[i]          ),  
        .ghash_out_valid_i         ( sp_ghash_out_valid[i]         ),  
        .ghash_out_ready_o         ( sp_ghash_out_ready[i]         ),  
        .ghash_load_hash_subkey_o  ( sp_ghash_load_hash_subkey[i]  ),  
        .key_init_sel_o            ( mr_key_init_sel[i]            ),  
        .key_init_we_o             ( int_key_init_we[i]            ),  
        .iv_sel_o                  ( mr_iv_sel[i]                  ),  
        .iv_we_o                   ( int_iv_we[i]                  ),  
        .prng_update_o             ( mr_prng_update[i]             ),  
        .prng_reseed_req_o         ( mr_prng_reseed_req[i]         ),  
        .prng_reseed_ack_i         ( prng_reseed_ack_i             ),
        .start_we_o                ( mr_start_we[i]                ),  
        .key_iv_data_in_clear_we_o ( mr_key_iv_data_in_clear_we[i] ),  
        .data_out_clear_we_o       ( mr_data_out_clear_we[i]       ),  
        .prng_reseed_o             ( mr_prng_reseed[i]             ),  
        .prng_reseed_we_o          ( mr_prng_reseed_we[i]          ),  
        .idle_o                    ( mr_idle[i]                    ),  
        .idle_we_o                 ( mr_idle_we[i]                 ),  
        .stall_o                   ( mr_stall[i]                   ),  
        .stall_we_o                ( mr_stall_we[i]                ),  
        .output_lost_i             ( output_lost_i                 ),  
        .output_lost_o             ( mr_output_lost[i]             ),  
        .output_lost_we_o          ( mr_output_lost_we[i]          ),  
        .output_valid_o            ( mr_output_valid[i]            ),  
        .output_valid_we_o         ( mr_output_valid_we[i]         ),  
        .input_ready_o             ( mr_input_ready[i]             ),  
        .input_ready_we_o          ( mr_input_ready_we[i]          )   
      );
    end else begin : gen_fsm_n
      aes_control_fsm_n #(
        .AESGCMEnable ( AESGCMEnable ),
        .SecMasking   ( SecMasking   )
      ) u_aes_control_fsm_i (
        .clk_i                     ( clk_i                         ),
        .rst_ni                    ( rst_ni                        ),
        .ctrl_qe_i                 ( ctrl_qe_i                     ),
        .ctrl_we_o                 ( mr_ctrl_we[i]                 ),  
        .ctrl_phase_i              ( ctrl_phase_i                  ),
        .ctrl_err_storage_i        ( ctrl_err_storage_i            ),
        .op_i                      ( op_i                          ),
        .mode_i                    ( mode_i                        ),
        .cipher_op_i               ( cipher_op_i                   ),
        .sideload_i                ( sideload_i                    ),
        .prng_reseed_rate_i        ( prng_reseed_rate_i            ),
        .manual_operation_i        ( manual_operation_i            ),
        .key_touch_forces_reseed_i ( key_touch_forces_reseed_i     ),
        .ctrl_gcm_qe_i             ( ctrl_gcm_qe_i                 ),
        .ctrl_gcm_we_o             ( mr_ctrl_gcm_we[i]             ),  
        .ctrl_gcm_phase_i          ( ctrl_gcm_phase_i              ),
        .gcm_init_done_o           ( mr_gcm_init_done[i]           ),  
        .gcm_phase_i               ( gcm_phase_i                   ),
        .start_i                   ( start_trigger                 ),
        .key_iv_data_in_clear_i    ( key_iv_data_in_clear_i        ),
        .data_out_clear_i          ( data_out_clear_i              ),
        .prng_reseed_i             ( prng_reseed_i                 ),
        .mux_sel_err_i             ( mux_sel_err                   ),
        .sp_enc_err_i              ( sp_enc_err                    ),
        .lc_escalate_en_i          ( lc_escalate_en_i              ),
        .alert_fatal_i             ( alert_fatal_i                 ),
        .alert_o                   ( mr_alert[i]                   ),  
        .key_sideload_valid_i      ( key_sideload_valid_i          ),
        .key_init_qe_i             ( int_key_init_qe               ),
        .iv_qe_i                   ( iv_qe_i                       ),
        .data_in_qe_i              ( data_in_qe_i                  ),
        .data_out_re_i             ( data_out_re_i                 ),
        .data_in_we_o              ( mr_data_in_we[i]              ),  
        .data_out_sel_o            ( mr_data_out_sel[i]            ),  
        .data_out_we_no            ( sp_data_out_we[i]             ),  
        .data_in_prev_sel_o        ( mr_data_in_prev_sel[i]        ),  
        .data_in_prev_we_no        ( sp_data_in_prev_we[i]         ),  
        .state_in_sel_o            ( mr_state_in_sel[i]            ),  
        .add_state_in_sel_o        ( mr_add_state_in_sel[i]        ),  
        .add_state_out_sel_o       ( mr_add_state_out_sel[i]       ),  
        .ctr_inc32_no              ( sp_ctr_inc32[i]               ),  
        .ctr_incr_no               ( sp_ctr_incr[i]                ),  
        .ctr_ready_ni              ( sp_ctr_ready[i]               ),  
        .ctr_we_ni                 ( int_ctr_we[i]                 ),  
        .cipher_in_valid_no        ( sp_cipher_in_valid[i]         ),  
        .cipher_in_ready_ni        ( sp_cipher_in_ready[i]         ),  
        .cipher_out_valid_ni       ( sp_cipher_out_valid[i]        ),  
        .cipher_out_ready_no       ( sp_cipher_out_ready[i]        ),  
        .cipher_crypt_no           ( sp_out_cipher_crypt[i]        ),  
        .cipher_crypt_ni           ( sp_in_cipher_crypt[i]         ),  
        .cipher_dec_key_gen_no     ( sp_out_cipher_dec_key_gen[i]  ),  
        .cipher_dec_key_gen_ni     ( sp_in_cipher_dec_key_gen[i]   ),  
        .cipher_prng_reseed_o      ( mr_cipher_prng_reseed[i]      ),  
        .cipher_prng_reseed_i      ( cipher_prng_reseed_i          ),
        .cipher_key_clear_o        ( mr_cipher_key_clear[i]        ),  
        .cipher_key_clear_i        ( cipher_key_clear_i            ),
        .cipher_data_out_clear_o   ( mr_cipher_data_out_clear[i]   ),  
        .cipher_data_out_clear_i   ( cipher_data_out_clear_i       ),
        .ghash_in_valid_no         ( sp_ghash_in_valid[i]          ),  
        .ghash_in_ready_ni         ( sp_ghash_in_ready[i]          ),  
        .ghash_out_valid_ni        ( sp_ghash_out_valid[i]         ),  
        .ghash_out_ready_no        ( sp_ghash_out_ready[i]         ),  
        .ghash_load_hash_subkey_no ( sp_ghash_load_hash_subkey[i]  ),  
        .key_init_sel_o            ( mr_key_init_sel[i]            ),  
        .key_init_we_no            ( int_key_init_we[i]            ),  
        .iv_sel_o                  ( mr_iv_sel[i]                  ),  
        .iv_we_no                  ( int_iv_we[i]                  ),  
        .prng_update_o             ( mr_prng_update[i]             ),  
        .prng_reseed_req_o         ( mr_prng_reseed_req[i]         ),  
        .prng_reseed_ack_i         ( prng_reseed_ack_i             ),
        .start_we_o                ( mr_start_we[i]                ),  
        .key_iv_data_in_clear_we_o ( mr_key_iv_data_in_clear_we[i] ),  
        .data_out_clear_we_o       ( mr_data_out_clear_we[i]       ),  
        .prng_reseed_o             ( mr_prng_reseed[i]             ),  
        .prng_reseed_we_o          ( mr_prng_reseed_we[i]          ),  
        .idle_o                    ( mr_idle[i]                    ),  
        .idle_we_o                 ( mr_idle_we[i]                 ),  
        .stall_o                   ( mr_stall[i]                   ),  
        .stall_we_o                ( mr_stall_we[i]                ),  
        .output_lost_i             ( output_lost_i                 ),  
        .output_lost_o             ( mr_output_lost[i]             ),  
        .output_lost_we_o          ( mr_output_lost_we[i]          ),  
        .output_valid_o            ( mr_output_valid[i]            ),  
        .output_valid_we_o         ( mr_output_valid_we[i]         ),  
        .input_ready_o             ( mr_input_ready[i]             ),  
        .input_ready_we_o          ( mr_input_ready_we[i]          )   
      );
    end
  end
  assign data_out_we_o            = sp2v_e'(sp_data_out_we);
  assign data_in_prev_we_o        = sp2v_e'(sp_data_in_prev_we);
  assign ctr_inc32_o              = sp2v_e'(sp_ctr_inc32);
  assign ctr_incr_o               = sp2v_e'(sp_ctr_incr);
  assign cipher_in_valid_o        = sp2v_e'(sp_cipher_in_valid);
  assign cipher_out_ready_o       = sp2v_e'(sp_cipher_out_ready);
  assign cipher_crypt_o           = sp2v_e'(sp_out_cipher_crypt);
  assign cipher_dec_key_gen_o     = sp2v_e'(sp_out_cipher_dec_key_gen);
  assign ghash_in_valid_o         = sp2v_e'(sp_ghash_in_valid);
  assign ghash_out_ready_o        = sp2v_e'(sp_ghash_out_ready);
  assign ghash_load_hash_subkey_o = sp2v_e'(sp_ghash_load_hash_subkey);
  assign alert_o                   = |mr_alert;
  assign cipher_prng_reseed_o      = |mr_cipher_prng_reseed;
  assign cipher_key_clear_o        = |mr_cipher_key_clear;
  assign cipher_data_out_clear_o   = |mr_cipher_data_out_clear;
  assign prng_update_o             = |mr_prng_update;
  assign prng_reseed_req_o         = |mr_prng_reseed_req;
  assign start_we_o                = |mr_start_we;
  assign prng_reseed_o             = |mr_prng_reseed;
  assign prng_reseed_we_o          = |mr_prng_reseed_we;
  assign ctrl_we_o                 = &mr_ctrl_we;
  assign ctrl_gcm_we_o             = &mr_ctrl_gcm_we;
  assign gcm_init_done_o           = &mr_gcm_init_done;
  assign data_in_we_o              = &mr_data_in_we;
  assign key_iv_data_in_clear_we_o = &mr_key_iv_data_in_clear_we;
  assign data_out_clear_we_o       = &mr_data_out_clear_we;
  assign idle_o                    = &mr_idle;
  assign idle_we_o                 = &mr_idle_we;
  assign stall_o                   = &mr_stall;
  assign stall_we_o                = &mr_stall_we;
  assign output_lost_o             = &mr_output_lost;
  assign output_lost_we_o          = &mr_output_lost_we;
  assign output_valid_o            = &mr_output_valid;
  assign output_valid_we_o         = &mr_output_valid_we;
  assign input_ready_o             = &mr_input_ready;
  assign input_ready_we_o          = &mr_input_ready_we;
  always_comb begin : combine_sparse_signals
    data_out_sel_o      = data_out_sel_e'({DataOutSelWidth{1'b0}});
    data_in_prev_sel_o  = dip_sel_e'({DIPSelWidth{1'b0}});
    state_in_sel_o      = si_sel_e'({SISelWidth{1'b0}});
    add_state_in_sel_o  = add_si_sel_e'({AddSISelWidth{1'b0}});
    add_state_out_sel_o = add_so_sel_e'({AddSOSelWidth{1'b0}});
    key_init_sel_o      = key_init_sel_e'({KeyInitSelWidth{1'b0}});
    iv_sel_o            = iv_sel_e'({IVSelWidth{1'b0}});
    mr_err              = 1'b0;
    for (int i = 0; i < Sp2VWidth; i++) begin
      data_out_sel_o      = data_out_sel_e'({data_out_sel_o}    | {mr_data_out_sel[i]});
      data_in_prev_sel_o  = dip_sel_e'({data_in_prev_sel_o}     | {mr_data_in_prev_sel[i]});
      state_in_sel_o      = si_sel_e'({state_in_sel_o}          | {mr_state_in_sel[i]});
      add_state_in_sel_o  = add_si_sel_e'({add_state_in_sel_o}  | {mr_add_state_in_sel[i]});
      add_state_out_sel_o = add_so_sel_e'({add_state_out_sel_o} | {mr_add_state_out_sel[i]});
      key_init_sel_o      = key_init_sel_e'({key_init_sel_o}    | {mr_key_init_sel[i]});
      iv_sel_o            = iv_sel_e'({iv_sel_o}                | {mr_iv_sel[i]});
    end
    for (int i = 0; i < Sp2VWidth; i++) begin
      if (data_out_sel_o      != mr_data_out_sel[i]      ||
          data_in_prev_sel_o  != mr_data_in_prev_sel[i]  ||
          state_in_sel_o      != mr_state_in_sel[i]      ||
          add_state_in_sel_o  != mr_add_state_in_sel[i]  ||
          add_state_out_sel_o != mr_add_state_out_sel[i] ||
          key_init_sel_o      != mr_key_init_sel[i]      ||
          iv_sel_o            != mr_iv_sel[i]) begin
        mr_err = 1'b1;
      end
    end
  end
  assign mux_sel_err = mux_sel_err_i | mr_err;
  localparam int unsigned NumSp2VSig = 7 + NumSlicesCtr;
  sp2v_e [NumSp2VSig-1:0]                sp2v_sig;
  sp2v_e [NumSp2VSig-1:0]                sp2v_sig_chk;
  logic  [NumSp2VSig-1:0][Sp2VWidth-1:0] sp2v_sig_chk_raw;
  logic  [NumSp2VSig-1:0]                sp2v_sig_err;
  assign sp2v_sig[0] = cipher_in_ready_i;
  assign sp2v_sig[1] = cipher_out_valid_i;
  assign sp2v_sig[2] = cipher_crypt_i;
  assign sp2v_sig[3] = cipher_dec_key_gen_i;
  assign sp2v_sig[4] = ghash_in_ready_i;
  assign sp2v_sig[5] = ghash_out_valid_i;
  assign sp2v_sig[6] = ctr_ready_i;
  for (genvar i = 0; i < NumSlicesCtr; i++) begin : gen_use_ctr_we_i
    assign sp2v_sig[7+i] = ctr_we_i[i];
  end
  localparam bit [NumSp2VSig-1:0] Sp2VEnSecBuf = '0;
  for (genvar i = 0; i < NumSp2VSig; i++) begin : gen_sel_buf_chk
    aes_sel_buf_chk #(
      .Num      ( Sp2VNum         ),
      .Width    ( Sp2VWidth       ),
      .EnSecBuf ( Sp2VEnSecBuf[i] )
    ) u_aes_sp2v_sig_buf_chk_i (
      .clk_i  ( clk_i               ),
      .rst_ni ( rst_ni              ),
      .sel_i  ( sp2v_sig[i]         ),
      .sel_o  ( sp2v_sig_chk_raw[i] ),
      .err_o  ( sp2v_sig_err[i]     )
    );
    assign sp2v_sig_chk[i] = sp2v_e'(sp2v_sig_chk_raw[i]);
  end
  assign cipher_in_ready    = sp2v_sig_chk[0];
  assign cipher_out_valid   = sp2v_sig_chk[1];
  assign cipher_crypt       = sp2v_sig_chk[2];
  assign cipher_dec_key_gen = sp2v_sig_chk[3];
  assign ghash_in_ready     = sp2v_sig_chk[4];
  assign ghash_out_valid    = sp2v_sig_chk[5];
  assign ctr_ready          = sp2v_sig_chk[6];
  for (genvar i = 0; i < NumSlicesCtr; i++) begin : gen_ctr_we
    assign ctr_we[i]        = sp2v_sig_chk[7+i];
  end
  assign sp_enc_err = |sp2v_sig_err | sp_enc_err_i;
  assign start_o                   = 1'b0;
  assign key_iv_data_in_clear_o    = 1'b0;
  assign data_out_clear_o          = 1'b0;
endmodule
module aes_control_fsm
  import aes_pkg::*;
  import aes_reg_pkg::*;
#(
  parameter bit AESGCMEnable = 0,
  parameter bit SecMasking   = 0
) (
  input  logic                                    clk_i,
  input  logic                                    rst_ni,
  input  logic                                    ctrl_qe_i,
  output logic                                    ctrl_we_o,
  input  logic                                    ctrl_phase_i,
  input  logic                                    ctrl_err_storage_i,
  input  aes_op_e                                 op_i,
  input  aes_mode_e                               mode_i,
  input  ciph_op_e                                cipher_op_i,
  input  logic                                    sideload_i,
  input  prs_rate_e                               prng_reseed_rate_i,
  input  logic                                    manual_operation_i,
  input  logic                                    key_touch_forces_reseed_i,
  input  logic                                    ctrl_gcm_qe_i,
  output logic                                    ctrl_gcm_we_o,
  input  logic                                    ctrl_gcm_phase_i,
  output logic                                    gcm_init_done_o,
  input  gcm_phase_e                              gcm_phase_i,
  input  logic                                    start_i,
  input  logic                                    key_iv_data_in_clear_i,
  input  logic                                    data_out_clear_i,
  input  logic                                    prng_reseed_i,
  input  logic                                    mux_sel_err_i,
  input  logic                                    sp_enc_err_i,
  input  lc_ctrl_pkg::lc_tx_t                     lc_escalate_en_i,
  input  logic                                    alert_fatal_i,
  output logic                                    alert_o,
  input  logic                                    key_sideload_valid_i,
  input  logic [NumSharesKey-1:0][NumRegsKey-1:0] key_init_qe_i,
  input  logic                    [NumRegsIv-1:0] iv_qe_i,
  input  logic                  [NumRegsData-1:0] data_in_qe_i,
  input  logic                  [NumRegsData-1:0] data_out_re_i,
  output logic                                    data_in_we_o,
  output data_out_sel_e                           data_out_sel_o,
  output logic                                    data_out_we_o,             
  output dip_sel_e                                data_in_prev_sel_o,
  output logic                                    data_in_prev_we_o,         
  output si_sel_e                                 state_in_sel_o,
  output add_si_sel_e                             add_state_in_sel_o,
  output add_so_sel_e                             add_state_out_sel_o,
  output logic                                    ctr_inc32_o,               
  output logic                                    ctr_incr_o,                
  input  logic                                    ctr_ready_i,               
  input  logic                 [NumSlicesCtr-1:0] ctr_we_i,                  
  output logic                                    cipher_in_valid_o,         
  input  logic                                    cipher_in_ready_i,         
  input  logic                                    cipher_out_valid_i,        
  output logic                                    cipher_out_ready_o,        
  output logic                                    cipher_crypt_o,            
  input  logic                                    cipher_crypt_i,            
  output logic                                    cipher_dec_key_gen_o,      
  input  logic                                    cipher_dec_key_gen_i,      
  output logic                                    cipher_prng_reseed_o,
  input  logic                                    cipher_prng_reseed_i,
  output logic                                    cipher_key_clear_o,
  input  logic                                    cipher_key_clear_i,
  output logic                                    cipher_data_out_clear_o,
  input  logic                                    cipher_data_out_clear_i,
  output logic                                    ghash_in_valid_o,          
  input  logic                                    ghash_in_ready_i,          
  input  logic                                    ghash_out_valid_i,         
  output logic                                    ghash_out_ready_o,         
  output logic                                    ghash_load_hash_subkey_o,  
  output key_init_sel_e                           key_init_sel_o,
  output logic [NumSharesKey-1:0][NumRegsKey-1:0] key_init_we_o,             
  output iv_sel_e                                 iv_sel_o,
  output logic                 [NumSlicesCtr-1:0] iv_we_o,                   
  output logic                                    prng_update_o,
  output logic                                    prng_reseed_req_o,
  input  logic                                    prng_reseed_ack_i,
  output logic                                    start_we_o,
  output logic                                    key_iv_data_in_clear_we_o,
  output logic                                    data_out_clear_we_o,
  output logic                                    prng_reseed_o,
  output logic                                    prng_reseed_we_o,
  output logic                                    idle_o,
  output logic                                    idle_we_o,
  output logic                                    stall_o,
  output logic                                    stall_we_o,
  input  logic                                    output_lost_i,
  output logic                                    output_lost_o,
  output logic                                    output_lost_we_o,
  output logic                                    output_valid_o,
  output logic                                    output_valid_we_o,
  output logic                                    input_ready_o,
  output logic                                    input_ready_we_o
);
  aes_ctrl_e                aes_ctrl_ns, aes_ctrl_cs;
  logic                     prng_reseed_done_d, prng_reseed_done_q;
  logic                     key_init_clear;
  logic                     key_init_new;
  logic                     key_init_new_pulse;
  logic                     key_init_load;
  logic                     key_init_arm;
  logic                     key_init_ready;
  logic                     key_sideload;
  logic  [NumSlicesCtr-1:0] iv_qe;
  logic                     iv_clear;
  logic                     iv_load;
  logic                     iv_arm;
  logic                     iv_ready;
  logic   [NumRegsData-1:0] data_in_new_d, data_in_new_q;
  logic                     data_in_new;
  logic                     data_in_load;
  logic   [NumRegsData-1:0] data_out_read_d, data_out_read_q;
  logic                     data_out_read;
  logic                     output_valid_q;
  logic                     cfg_valid;
  logic                     no_alert;
  logic                     cipher_op_err;
  logic                     start_common, start_ecb, start_cbc, start_cfb, start_ofb, start_ctr;
  logic                     start;
  logic                     start_core;
  logic                     finish;
  logic                     crypt;
  logic                     cipher_out_done;
  logic                     doing_cbc_enc, doing_cbc_dec;
  logic                     doing_cfb_enc, doing_cfb_dec;
  logic                     doing_ofb;
  logic                     doing_ctr;
  logic                     ctrl_we_q;
  logic                     clear_in_out_status;
  logic                     clear_on_fatal;
  logic                     start_we;
  logic                     key_iv_data_in_clear_we;
  logic                     data_out_clear_we;
  logic                     prng_reseed_we;
  logic                     idle;
  logic                     idle_we;
  logic                     stall;
  logic                     stall_we;
  logic                     output_lost;
  logic                     output_lost_we;
  logic                     output_valid;
  logic                     output_valid_we;
  logic                     input_ready;
  logic                     input_ready_we;
  logic                     ctrl_gcm_we_q;
  logic                     gcm_clear;
  logic                     gcm_init, gcm_restore, gcm_aad, gcm_txt, gcm_save, gcm_tag;
  logic                     start_common_gcm, start_ghash;
  logic                     start_gcm_init, start_gcm_hsk, start_gcm_s;
  logic                     start_gcm_restore, start_gcm_aad, start_gcm_txt, start_gcm_save;
  logic                     start_gcm_tag;
  logic                     doing_gcm_hsk, doing_gcm_s, doing_gcm_txt;
  logic                     hash_subkey_ready_d, hash_subkey_ready_q;
  logic                     s_ready_d, s_ready_q;
  logic                     doing_gcm_restore_d, doing_gcm_restore_q;
  logic                     doing_gcm_aad_d, doing_gcm_aad_q;
  logic                     doing_gcm_tag_d, doing_gcm_tag_q;
  logic                     doing_gcm_save_d, doing_gcm_save_q;
  logic                     ghash_out_done;
  logic                     ghash_idle;
  logic                     block_ctr_expr;
  logic                     block_ctr_decr;
  assign iv_qe = {iv_qe_i[3], iv_qe_i[3], iv_qe_i[2], iv_qe_i[2],
                  iv_qe_i[1], iv_qe_i[1], iv_qe_i[0], iv_qe_i[0]};
  assign cfg_valid = ~((mode_i == AES_NONE) | ctrl_err_storage_i);
  assign no_alert  = ~alert_fatal_i;
  assign cipher_op_err = ~(cipher_op_i == CIPH_FWD || cipher_op_i == CIPH_INV);
  assign start_common = key_init_ready & data_in_new &
      (sideload_i ? key_sideload_valid_i : 1'b1);
  assign start_ecb = (mode_i == AES_ECB);
  assign start_cbc = (mode_i == AES_CBC) & iv_ready;
  assign start_cfb = (mode_i == AES_CFB) & iv_ready;
  assign start_ofb = (mode_i == AES_OFB) & iv_ready;
  assign start_ctr = (mode_i == AES_CTR) & iv_ready & ctr_ready_i;
  assign start = cfg_valid & no_alert &
      (manual_operation_i ? start_i  :
          ((start_ecb |
            start_cbc |
            start_cfb |
            start_ofb |
            start_ctr) & start_common) |
           (start_gcm_init |
            start_gcm_txt));
  assign finish = cfg_valid & no_alert &
      (manual_operation_i ? 1'b1 :
          (~output_valid_q | data_out_read));
  assign gcm_init    = (mode_i == AES_GCM) & (gcm_phase_i == GCM_INIT);
  assign gcm_restore = (mode_i == AES_GCM) & (gcm_phase_i == GCM_RESTORE);
  assign gcm_aad     = (mode_i == AES_GCM) & (gcm_phase_i == GCM_AAD);
  assign gcm_txt     = (mode_i == AES_GCM) & (gcm_phase_i == GCM_TEXT);
  assign gcm_save    = (mode_i == AES_GCM) & (gcm_phase_i == GCM_SAVE);
  assign gcm_tag     = (mode_i == AES_GCM) & (gcm_phase_i == GCM_TAG);
  assign start_common_gcm = key_init_ready &
      (sideload_i ? key_sideload_valid_i : 1'b1);
  assign start_gcm_hsk  = gcm_init & ~gcm_clear & ~hash_subkey_ready_q & iv_ready & ctr_ready_i;
  assign start_gcm_s    = gcm_init & ~gcm_clear & ~s_ready_q           & iv_ready & ctr_ready_i;
  assign start_gcm_init = (start_gcm_hsk | start_gcm_s) & start_common_gcm;
  assign start_gcm_restore = gcm_restore & cfg_valid & no_alert &
      (manual_operation_i ? start_i : iv_ready & ctr_ready_i & data_in_new & start_common_gcm);
  assign start_gcm_aad = gcm_aad & cfg_valid & no_alert &
      (manual_operation_i ? start_i : iv_ready & ctr_ready_i & start_common);
  assign start_gcm_txt = gcm_txt & iv_ready & ctr_ready_i & start_common;
  assign start_gcm_save = gcm_save & cfg_valid & no_alert &
      (manual_operation_i ? start_i : hash_subkey_ready_q & s_ready_q);
  assign start_gcm_tag = gcm_tag & cfg_valid & no_alert &
      (manual_operation_i ? start_i : hash_subkey_ready_q & s_ready_q & data_in_new);
  assign start_ghash = start_gcm_restore | start_gcm_aad | start_gcm_save | start_gcm_tag;
  assign ghash_idle = ghash_in_ready_i & ~start_ghash;
  assign ctr_inc32_o = (mode_i == AES_GCM);
  assign crypt = cipher_crypt_o | cipher_crypt_i;
  assign doing_cbc_enc = (mode_i == AES_CBC && op_i == AES_ENC) & crypt;
  assign doing_cbc_dec = (mode_i == AES_CBC && op_i == AES_DEC) & crypt;
  assign doing_cfb_enc = (mode_i == AES_CFB && op_i == AES_ENC) & crypt;
  assign doing_cfb_dec = (mode_i == AES_CFB && op_i == AES_DEC) & crypt;
  assign doing_ofb     = (mode_i == AES_OFB)                    & crypt;
  assign doing_ctr     = (mode_i == AES_CTR)                    & crypt;
  assign doing_gcm_hsk = gcm_init & ~hash_subkey_ready_q        & crypt;
  assign doing_gcm_s   = gcm_init &  hash_subkey_ready_q        & crypt;
  assign doing_gcm_txt = gcm_txt                                & crypt;
  always_comb begin : aes_ctrl_fsm
    data_in_prev_sel_o = DIP_CLEAR;
    data_in_prev_we_o  = 1'b0;
    state_in_sel_o      = SI_DATA;
    add_state_in_sel_o  = ADD_SI_ZERO;
    add_state_out_sel_o = ADD_SO_ZERO;
    ctr_incr_o = 1'b0;
    cipher_in_valid_o       = 1'b0;
    cipher_out_ready_o      = 1'b0;
    cipher_out_done         = 1'b0;
    cipher_crypt_o          = 1'b0;
    cipher_dec_key_gen_o    = 1'b0;
    cipher_prng_reseed_o    = 1'b0;
    cipher_key_clear_o      = 1'b0;
    cipher_data_out_clear_o = 1'b0;
    ghash_in_valid_o         = 1'b0;
    ghash_out_ready_o        = 1'b0;
    ghash_out_done           = 1'b0;
    ghash_load_hash_subkey_o = ~hash_subkey_ready_q;
    key_init_sel_o = sideload_i ? KEY_INIT_KEYMGR : KEY_INIT_INPUT;
    key_init_we_o = {NumSharesKey * NumRegsKey{1'b0}};
    iv_sel_o = IV_INPUT;
    iv_we_o  = {NumSlicesCtr{1'b0}};
    ctrl_we_o     = 1'b0;
    ctrl_gcm_we_o = 1'b0;
    alert_o = 1'b0;
    prng_update_o     = 1'b0;
    prng_reseed_req_o = 1'b0;
    start_we                = 1'b0;
    key_iv_data_in_clear_we = 1'b0;
    data_out_clear_we       = 1'b0;
    prng_reseed_we          = 1'b0;
    idle     = 1'b0;
    idle_we  = 1'b0;
    stall    = 1'b0;
    stall_we = 1'b0;
    data_in_load   = 1'b0;
    data_in_we_o   = 1'b0;
    data_out_sel_o = DATA_OUT_CIPHER;
    data_out_we_o  = 1'b0;
    key_init_clear = 1'b0;
    key_init_load  = 1'b0;
    key_init_arm   = 1'b0;
    iv_clear       = 1'b0;
    iv_load        = 1'b0;
    iv_arm         = 1'b0;
    block_ctr_decr = 1'b0;
    aes_ctrl_ns         = aes_ctrl_cs;
    start_core          = 1'b0;
    prng_reseed_done_d  = prng_reseed_done_q | prng_reseed_ack_i;
    hash_subkey_ready_d = hash_subkey_ready_q;
    s_ready_d           = s_ready_q;
    doing_gcm_restore_d = doing_gcm_restore_q;
    doing_gcm_aad_d     = doing_gcm_aad_q;
    doing_gcm_tag_d     = doing_gcm_tag_q;
    doing_gcm_save_d    = doing_gcm_save_q;
    unique case (aes_ctrl_cs)
      CTRL_IDLE: begin
        start_core = start | key_iv_data_in_clear_i | data_out_clear_i | prng_reseed_i;
        idle    = ~(start_core | (prng_reseed_o & prng_reseed_we_o)) & ghash_idle;
        idle_we = 1'b1;
        start_we = start_i & ((mode_i == AES_NONE) | ~manual_operation_i);
        if (!start_core) begin
          key_init_we_o = sideload_i ? {NumSharesKey * NumRegsKey{key_sideload}} : key_init_qe_i;
          iv_we_o       = iv_qe;
        end
        if (!start_core && !start_ghash) begin
          ctrl_we_o      = !ctrl_err_storage_i ? ctrl_qe_i     : 1'b0;
          ctrl_gcm_we_o  = !ctrl_err_storage_i ? ctrl_gcm_qe_i : 1'b0;
          key_init_clear = ctrl_we_o;
          iv_clear       = ctrl_we_o | (gcm_init & gcm_clear);
          if (ctrl_we_o | gcm_clear) begin
            hash_subkey_ready_d = 1'b0;
            s_ready_d           = 1'b0;
          end
        end
        if (prng_reseed_i) begin
          if (!SecMasking) begin
            prng_reseed_done_d = 1'b0;
            aes_ctrl_ns        = CTRL_PRNG_RESEED;
          end else begin
            cipher_prng_reseed_o = 1'b1;
            cipher_in_valid_o = 1'b1;
            if (cipher_in_ready_i) begin
              prng_reseed_done_d = 1'b0;
              aes_ctrl_ns        = CTRL_PRNG_RESEED;
            end
          end
        end else if (key_iv_data_in_clear_i || data_out_clear_i) begin
          prng_update_o = 1'b1;
          cipher_key_clear_o      = key_iv_data_in_clear_i;
          cipher_data_out_clear_o = data_out_clear_i;
          cipher_in_valid_o = 1'b1;
          if (cipher_in_ready_i) begin
            aes_ctrl_ns = CTRL_GHASH_READY;
          end
        end else if (start_gcm_restore || start_gcm_aad || start_gcm_tag) begin
          data_in_prev_sel_o = DIP_DATA_IN;
          data_in_prev_we_o  = 1'b1;
          doing_gcm_restore_d = start_gcm_restore;
          doing_gcm_aad_d     = start_gcm_aad;
          doing_gcm_tag_d     = start_gcm_tag;
          start_we            = 1'b1;
          aes_ctrl_ns         = CTRL_LOAD;
        end else if (start_gcm_save) begin
          prng_update_o    = 1'b1;
          doing_gcm_save_d = 1'b1;
          start_we         = 1'b1;
          aes_ctrl_ns      = CTRL_GHASH_READY;
        end else if (start) begin
          cipher_crypt_o = 1'b1;
          cipher_prng_reseed_o = block_ctr_expr;
          cipher_dec_key_gen_o = (cipher_op_i == CIPH_INV) ? key_init_new : 1'b0;
          data_in_prev_sel_o = doing_cbc_dec ? DIP_DATA_IN :
                               doing_cfb_enc ? DIP_DATA_IN :
                               doing_cfb_dec ? DIP_DATA_IN :
                               doing_ofb     ? DIP_DATA_IN :
                               doing_ctr     ? DIP_DATA_IN :
                               doing_gcm_txt ? DIP_DATA_IN : DIP_CLEAR;
          data_in_prev_we_o  = doing_cbc_dec |
                               doing_cfb_enc |
                               doing_cfb_dec |
                               doing_ofb     |
                               doing_ctr     |
                               doing_gcm_txt;
          state_in_sel_o     = doing_cfb_enc ? SI_ZERO :
                               doing_cfb_dec ? SI_ZERO :
                               doing_ofb     ? SI_ZERO :
                               doing_ctr     ? SI_ZERO :
                               doing_gcm_hsk ? SI_ZERO :
                               doing_gcm_s   ? SI_ZERO :
                               doing_gcm_txt ? SI_ZERO : SI_DATA;
          add_state_in_sel_o = doing_cbc_enc ? ADD_SI_IV :
                               doing_cfb_enc ? ADD_SI_IV :
                               doing_cfb_dec ? ADD_SI_IV :
                               doing_ofb     ? ADD_SI_IV :
                               doing_ctr     ? ADD_SI_IV :
                               doing_gcm_s   ? ADD_SI_IV :
                               doing_gcm_txt ? ADD_SI_IV : ADD_SI_ZERO;
          cipher_in_valid_o = 1'b1;
          if (cipher_in_ready_i) begin
            start_we    = ~cipher_dec_key_gen_o;
            aes_ctrl_ns = CTRL_LOAD;
          end
        end
      end
      CTRL_LOAD: begin
        key_init_load =  cipher_dec_key_gen_i;  
        key_init_arm  = ~cipher_dec_key_gen_i;  
        iv_load       = ~cipher_dec_key_gen_i & (doing_cbc_enc |
                                                 doing_cbc_dec |
                                                 doing_cfb_enc |
                                                 doing_cfb_dec |
                                                 doing_ofb     |
                                                 doing_ctr     |
                                                 doing_gcm_hsk |
                                                 doing_gcm_s   |
                                                 doing_gcm_txt);
        data_in_load  = ~cipher_dec_key_gen_i;
        ctr_incr_o   = doing_ctr | doing_gcm_hsk | doing_gcm_s | doing_gcm_txt;
        prng_update_o = !cipher_dec_key_gen_i;
        aes_ctrl_ns   = !cipher_dec_key_gen_i ? CTRL_GHASH_READY : CTRL_FINISH;
      end
      CTRL_GHASH_READY: begin
        iv_sel_o = doing_ctr     ||
                   doing_gcm_hsk ||
                   doing_gcm_s   ||
                   doing_gcm_txt ? IV_CTR   : IV_INPUT;
        iv_we_o  = doing_ctr     ||
                   doing_gcm_hsk ||
                   doing_gcm_s   ||
                   doing_gcm_txt ? ctr_we_i : {NumSlicesCtr{1'b0}};
        if (cipher_crypt_i) begin
          if (doing_gcm_hsk || doing_gcm_s || doing_gcm_txt) begin
            if (ghash_in_ready_i) begin
              aes_ctrl_ns = CTRL_FINISH;
            end
          end else begin
            aes_ctrl_ns = CTRL_FINISH;
          end
        end else if (doing_gcm_restore_q) begin
          ghash_in_valid_o = 1'b1;
          if (ghash_in_ready_i) begin
            doing_gcm_restore_d = 1'b0;
            aes_ctrl_ns         = CTRL_IDLE;
          end
        end else if (doing_gcm_aad_q) begin
          ghash_in_valid_o = 1'b1;
          if (ghash_in_ready_i) begin
            doing_gcm_aad_d = 1'b0;
            aes_ctrl_ns     = CTRL_IDLE;
          end
        end else if (doing_gcm_save_q) begin
          ghash_in_valid_o = 1'b1;
          if (ghash_in_ready_i) begin
            aes_ctrl_ns = CTRL_FINISH;
          end
        end else if (doing_gcm_tag_q) begin
          ghash_in_valid_o = 1'b1;
          if (ghash_in_ready_i) begin
            aes_ctrl_ns = CTRL_FINISH;
          end
        end else if (key_iv_data_in_clear_i || data_out_clear_i ||
                     cipher_key_clear_i     || cipher_data_out_clear_i) begin
          if (ghash_in_ready_i) begin
            aes_ctrl_ns = CTRL_CLEAR_I;
          end
        end else begin
          aes_ctrl_ns = CTRL_IDLE;
        end
      end
      CTRL_PRNG_RESEED: begin
        prng_reseed_req_o = ~prng_reseed_done_q;
        if (!SecMasking) begin
          if (prng_reseed_done_q) begin
            prng_reseed_we     = 1'b1;
            prng_reseed_done_d = 1'b0;
            aes_ctrl_ns        = CTRL_IDLE;
          end
        end else begin
          cipher_out_ready_o = prng_reseed_done_q;
          if (cipher_out_ready_o && cipher_out_valid_i) begin
            prng_reseed_we     = 1'b1;
            prng_reseed_done_d = 1'b0;
            aes_ctrl_ns        = CTRL_IDLE;
          end
        end
      end
      CTRL_FINISH: begin
        if (cipher_dec_key_gen_i) begin
          cipher_out_ready_o = 1'b1;
          if (cipher_out_valid_i) begin
            block_ctr_decr = 1'b1;
            aes_ctrl_ns    = CTRL_IDLE;
          end
        end else if (doing_gcm_save_q || doing_gcm_tag_q) begin
          ghash_out_ready_o = finish;
          ghash_out_done    = finish & ghash_out_valid_i &
              ~mux_sel_err_i & ~sp_enc_err_i & ~cipher_op_err;
          stall    = ~finish & ghash_out_valid_i;
          stall_we = 1'b1;
          data_out_sel_o = DATA_OUT_GHASH;
          if (ghash_out_done) begin
            doing_gcm_save_d    = 1'b0;
            doing_gcm_tag_d     = 1'b0;
            hash_subkey_ready_d = 1'b0;
            s_ready_d           = 1'b0;
            data_out_we_o       = 1'b1;
            aes_ctrl_ns         = CTRL_IDLE;
          end
        end else begin
          cipher_out_ready_o = finish;
          cipher_out_done    = finish & cipher_out_valid_i &
              ~mux_sel_err_i & ~sp_enc_err_i & ~cipher_op_err;
          stall    = ~finish & cipher_out_valid_i;
          stall_we = 1'b1;
          add_state_out_sel_o = doing_cbc_dec ? ADD_SO_IV  :
                                doing_cfb_enc ? ADD_SO_DIP :
                                doing_cfb_dec ? ADD_SO_DIP :
                                doing_ofb     ? ADD_SO_DIP :
                                doing_ctr     ? ADD_SO_DIP :
                                doing_gcm_txt ? ADD_SO_DIP : ADD_SO_ZERO;
          iv_sel_o = doing_cbc_enc ? IV_DATA_OUT     :
                     doing_cbc_dec ? IV_DATA_IN_PREV :
                     doing_cfb_enc ? IV_DATA_OUT     :
                     doing_cfb_dec ? IV_DATA_IN_PREV :
                     doing_ofb     ? IV_DATA_OUT_RAW :
                     doing_ctr     ? IV_CTR          :
                     doing_gcm_hsk ? IV_CTR          :
                     doing_gcm_s   ? IV_CTR          :
                     doing_gcm_txt ? IV_CTR          : IV_INPUT;
          iv_we_o  = doing_cbc_enc ||
                     doing_cbc_dec ||
                     doing_cfb_enc ||
                     doing_cfb_dec ||
                     doing_ofb     ? {NumSlicesCtr{cipher_out_done}} :
                     doing_ctr     ? ctr_we_i                        :
                     doing_gcm_hsk ? ctr_we_i                        :
                     doing_gcm_s   ? ctr_we_i                        :
                     doing_gcm_txt ? ctr_we_i                        : {NumSlicesCtr{1'b0}};
          iv_arm = (doing_cbc_enc |
                    doing_cbc_dec |
                    doing_cfb_enc |
                    doing_cfb_dec |
                    doing_ofb     |
                    doing_ctr     |
                    doing_gcm_hsk |
                    doing_gcm_s   |
                    doing_gcm_txt) & cipher_out_done;
          if (cipher_out_done) begin
            block_ctr_decr      = 1'b1;
            data_out_we_o       = doing_gcm_hsk |
                                  doing_gcm_s   ? 1'b0 : 1'b1;
            ghash_in_valid_o    = doing_gcm_hsk |
                                  doing_gcm_s   |
                                  doing_gcm_txt ? 1'b1 : 1'b0;
            hash_subkey_ready_d = doing_gcm_hsk ? 1'b1 : hash_subkey_ready_q;
            s_ready_d           = doing_gcm_s   ? 1'b1 : s_ready_q;
            aes_ctrl_ns         = CTRL_IDLE;
          end
        end
      end
      CTRL_CLEAR_I: begin
        if (key_iv_data_in_clear_i) begin
          key_init_sel_o = KEY_INIT_CLEAR;
          key_init_we_o  = {NumSharesKey * NumRegsKey{1'b1}};
          key_init_clear = 1'b1;
          iv_sel_o = IV_CLEAR;
          iv_we_o  = {NumSlicesCtr{1'b1}};
          iv_clear = 1'b1;
          data_in_we_o       = 1'b1;
          data_in_prev_sel_o = DIP_CLEAR;
          data_in_prev_we_o  = 1'b1;
        end
        aes_ctrl_ns = CTRL_CLEAR_CO;
      end
      CTRL_CLEAR_CO: begin
        cipher_out_ready_o = 1'b1;
        if (cipher_out_valid_i) begin
          if (cipher_key_clear_i) begin
            key_iv_data_in_clear_we = 1'b1;
            ghash_in_valid_o = 1'b1;
          end
          if (cipher_data_out_clear_i) begin
            data_out_we_o     = ~mux_sel_err_i & ~sp_enc_err_i & ~cipher_op_err;
            data_out_clear_we = 1'b1;
          end
          aes_ctrl_ns = CTRL_IDLE;
        end
      end
      CTRL_ERROR: begin
        alert_o = 1'b1;
      end
      default: begin
        aes_ctrl_ns = CTRL_ERROR;
        alert_o = 1'b1;
      end
    endcase
    if (mux_sel_err_i || sp_enc_err_i || cipher_op_err ||
            lc_ctrl_pkg::lc_tx_test_true_loose(lc_escalate_en_i)) begin
      aes_ctrl_ns = CTRL_ERROR;
    end
  end
    caliptra_prim_sparse_fsm_flop #(                  
      .StateEnumT(aes_ctrl_e),                            
      .Width($bits(aes_ctrl_e)),                          
      .ResetValue($bits(aes_ctrl_e)'(CTRL_IDLE)),          
      .EnableAlertTriggerSVA( 1)  
    ) u_state_regs (                                        
      .clk_i   (  clk_i   ),                           
      .rst_ni  (  rst_ni ),                           
      .state_i ( aes_ctrl_ns     ),                           
      .state_o ( aes_ctrl_cs     )                            
    );                                                
  always_ff @(posedge clk_i or negedge rst_ni) begin : reg_fsm
    if (!rst_ni) begin
      prng_reseed_done_q <= 1'b0;
    end else begin
      prng_reseed_done_q <= prng_reseed_done_d;
    end
  end
  if (AESGCMEnable) begin : gen_reg_fsm_gcm
    always_ff @(posedge clk_i or negedge rst_ni) begin : reg_fsm_gcm
      if (!rst_ni) begin
        hash_subkey_ready_q <= 1'b0;
        s_ready_q           <= 1'b0;
        doing_gcm_restore_q <= 1'b0;
        doing_gcm_aad_q     <= 1'b0;
        doing_gcm_save_q    <= 1'b0;
        doing_gcm_tag_q     <= 1'b0;
      end else begin
        hash_subkey_ready_q <= hash_subkey_ready_d;
        s_ready_q           <= s_ready_d;
        doing_gcm_restore_q <= doing_gcm_restore_d;
        doing_gcm_aad_q     <= doing_gcm_aad_d;
        doing_gcm_save_q    <= doing_gcm_save_d;
        doing_gcm_tag_q     <= doing_gcm_tag_d;
      end
    end
  end else begin : gen_no_reg_fsm_gcm
    assign hash_subkey_ready_q = 1'b0;
    assign s_ready_q           = 1'b0;
    assign doing_gcm_restore_q = 1'b0;
    assign doing_gcm_aad_q     = 1'b0;
    assign doing_gcm_save_q    = 1'b0;
    assign doing_gcm_tag_q     = 1'b0;
    logic unused_gcm_d;
    assign unused_gcm_d = ^{hash_subkey_ready_d,
                            s_ready_d,
                            doing_gcm_restore_d,
                            doing_gcm_aad_d,
                            doing_gcm_save_d,
                            doing_gcm_tag_d};
  end
  assign key_sideload = sideload_i & key_sideload_valid_i & ctrl_we_q & ~ctrl_phase_i;
  aes_reg_status #(
    .Width ( $bits(key_init_we_o) )
  ) u_reg_status_key_init (
    .clk_i       ( clk_i              ),
    .rst_ni      ( rst_ni             ),
    .we_i        ( key_init_we_o      ),
    .use_i       ( key_init_load      ),
    .clear_i     ( key_init_clear     ),
    .arm_i       ( key_init_arm       ),
    .new_o       ( key_init_new       ),
    .new_pulse_o ( key_init_new_pulse ),
    .clean_o     ( key_init_ready     )
  );
  aes_reg_status #(
    .Width ( $bits(iv_we_o) )
  ) u_reg_status_iv (
    .clk_i       ( clk_i    ),
    .rst_ni      ( rst_ni   ),
    .we_i        ( iv_we_o  ),
    .use_i       ( iv_load  ),
    .clear_i     ( iv_clear ),
    .arm_i       ( iv_arm   ),
    .new_o       ( iv_ready ),
    .new_pulse_o (          ),
    .clean_o     (          )
  );
  always_ff @(posedge clk_i or negedge rst_ni) begin : reg_ctrl_we
    if (!rst_ni) begin
      ctrl_we_q <= 1'b0;
    end else begin
      ctrl_we_q <= ctrl_we_o;
    end
  end
  assign clear_in_out_status = ctrl_we_q;
  assign data_in_new_d = data_in_load || &data_in_qe_i || clear_in_out_status ? '0 :
      data_in_new_q | data_in_qe_i;
  assign data_in_new   = &data_in_new_d;
  assign data_out_read_d = &data_out_read_q || clear_in_out_status ? '0 :
      data_out_read_q | data_out_re_i;
  assign data_out_read   = &data_out_read_d;
  always_ff @(posedge clk_i or negedge rst_ni) begin : reg_edge_detection
    if (!rst_ni) begin
      data_in_new_q   <= '0;
      data_out_read_q <= '0;
    end else begin
      data_in_new_q   <= data_in_new_d;
      data_out_read_q <= data_out_read_d;
    end
  end
  assign input_ready    = ~data_in_new;
  assign input_ready_we =  data_in_new | data_in_load | data_in_we_o | clear_in_out_status;
  assign output_valid    = data_out_we_o & ~data_out_clear_we;
  assign output_valid_we = data_out_we_o | data_out_read | data_out_clear_we |
      clear_in_out_status;
  always_ff @(posedge clk_i or negedge rst_ni) begin : reg_output_valid
    if (!rst_ni) begin
      output_valid_q <= '0;
    end else if (output_valid_we) begin
      output_valid_q <= output_valid;
    end
  end
  assign output_lost    = ctrl_we_o     ? 1'b0 :
                          output_lost_i ? 1'b1 : output_valid_q & ~data_out_read;
  assign output_lost_we = ctrl_we_o | data_out_we_o;
  assign gcm_clear = (gcm_phase_i == GCM_INIT) & ctrl_gcm_we_q & ~ctrl_gcm_phase_i;
  if (AESGCMEnable) begin : gen_reg_ctrl_gcm_we
    always_ff @(posedge clk_i or negedge rst_ni) begin : reg_ctrl_gcm_we
      if (!rst_ni) begin
        ctrl_gcm_we_q <= 1'b0;
      end else begin
        ctrl_gcm_we_q <= ctrl_gcm_we_o;
      end
    end
  end else begin : gen_no_reg_ctrl_gcm_we
    assign ctrl_gcm_we_q = 1'b1;
  end
  assign gcm_init_done_o = hash_subkey_ready_q & s_ready_q;
  assign clear_on_fatal = ClearStatusOnFatalAlert ? alert_fatal_i : 1'b0;
  assign idle_o            = clear_on_fatal ? 1'b0 : idle;
  assign idle_we_o         = clear_on_fatal ? 1'b1 : idle_we;
  assign stall_o           = clear_on_fatal ? 1'b0 : stall;
  assign stall_we_o        = clear_on_fatal ? 1'b1 : stall_we;
  assign output_lost_o     = clear_on_fatal ? 1'b0 : output_lost;
  assign output_lost_we_o  = clear_on_fatal ? 1'b1 : output_lost_we;
  assign output_valid_o    = clear_on_fatal ? 1'b0 : output_valid;
  assign output_valid_we_o = clear_on_fatal ? 1'b1 : output_valid_we;
  assign input_ready_o     = clear_on_fatal ? 1'b0 : input_ready;
  assign input_ready_we_o  = clear_on_fatal ? 1'b1 : input_ready_we;
  assign start_we_o                = clear_on_fatal ? 1'b1 : start_we;
  assign key_iv_data_in_clear_we_o = clear_on_fatal ? 1'b1 : key_iv_data_in_clear_we;
  assign data_out_clear_we_o       = clear_on_fatal ? 1'b1 : data_out_clear_we;
  assign prng_reseed_o    = clear_on_fatal     ? 1'b0 :
                            key_init_new_pulse ? 1'b1 : 1'b0;
  assign prng_reseed_we_o = clear_on_fatal     ? 1'b1                      :
                            key_init_new_pulse ? key_touch_forces_reseed_i : prng_reseed_we;
  if (SecMasking) begin : gen_block_ctr
    logic                     block_ctr_set;
    logic [BlockCtrWidth-1:0] block_ctr_d, block_ctr_q;
    logic [BlockCtrWidth-1:0] block_ctr_set_val, block_ctr_decr_val;
    assign block_ctr_expr = block_ctr_q == '0;
    assign block_ctr_set  = ctrl_we_q | (block_ctr_decr & (block_ctr_expr | cipher_prng_reseed_i));
    assign block_ctr_set_val  = prng_reseed_rate_i == PER_1  ? '0                   :
                                prng_reseed_rate_i == PER_64 ? BlockCtrWidth'(63)   :
                                prng_reseed_rate_i == PER_8K ? BlockCtrWidth'(8191) : '0;
    assign block_ctr_decr_val = block_ctr_q - BlockCtrWidth'(1);
    assign block_ctr_d = block_ctr_set  ? block_ctr_set_val  :
                         block_ctr_decr ? block_ctr_decr_val : block_ctr_q;
    always_ff @(posedge clk_i or negedge rst_ni) begin : reg_block_ctr
      if (!rst_ni) begin
        block_ctr_q <= '0;
      end else begin
        block_ctr_q <= block_ctr_d;
      end
    end
  end else begin : gen_no_block_ctr
    assign block_ctr_expr = 1'b0;
    logic      unused_block_ctr_decr;
    prs_rate_e unused_prng_reseed_rate;
    logic      unused_cipher_prng_reseed;
    assign unused_block_ctr_decr     = block_ctr_decr;
    assign unused_prng_reseed_rate   = prng_reseed_rate_i;
    assign unused_cipher_prng_reseed = cipher_prng_reseed_i;
  end
  localparam int AesControlFsmSecMaskingNonDefault = (SecMasking == 1) ? 1 : 2;          
  always_comb begin                                  
    logic unused_assert_static_lint_error;           
    unused_assert_static_lint_error = AesControlFsmSecMaskingNonDefault'(1'b1); 
  end
endmodule
module aes_control_fsm_n
  import aes_pkg::*;
  import aes_reg_pkg::*;
#(
  parameter bit AESGCMEnable = 0,
  parameter bit SecMasking   = 0
) (
  input  logic                                    clk_i,
  input  logic                                    rst_ni,
  input  logic                                    ctrl_qe_i,
  output logic                                    ctrl_we_o,
  input  logic                                    ctrl_phase_i,
  input  logic                                    ctrl_err_storage_i,
  input  aes_op_e                                 op_i,
  input  aes_mode_e                               mode_i,
  input  ciph_op_e                                cipher_op_i,
  input  logic                                    sideload_i,
  input  prs_rate_e                               prng_reseed_rate_i,
  input  logic                                    manual_operation_i,
  input  logic                                    key_touch_forces_reseed_i,
  input  logic                                    ctrl_gcm_qe_i,
  output logic                                    ctrl_gcm_we_o,
  input  logic                                    ctrl_gcm_phase_i,
  output logic                                    gcm_init_done_o,
  input  gcm_phase_e                              gcm_phase_i,
  input  logic                                    start_i,
  input  logic                                    key_iv_data_in_clear_i,
  input  logic                                    data_out_clear_i,
  input  logic                                    prng_reseed_i,
  input  logic                                    mux_sel_err_i,
  input  logic                                    sp_enc_err_i,
  input  lc_ctrl_pkg::lc_tx_t                     lc_escalate_en_i,
  input  logic                                    alert_fatal_i,
  output logic                                    alert_o,
  input  logic                                    key_sideload_valid_i,
  input  logic [NumSharesKey-1:0][NumRegsKey-1:0] key_init_qe_i,
  input  logic                    [NumRegsIv-1:0] iv_qe_i,
  input  logic                  [NumRegsData-1:0] data_in_qe_i,
  input  logic                  [NumRegsData-1:0] data_out_re_i,
  output logic                                    data_in_we_o,
  output data_out_sel_e                           data_out_sel_o,
  output logic                                    data_out_we_no,             
  output dip_sel_e                                data_in_prev_sel_o,
  output logic                                    data_in_prev_we_no,         
  output si_sel_e                                 state_in_sel_o,
  output add_si_sel_e                             add_state_in_sel_o,
  output add_so_sel_e                             add_state_out_sel_o,
  output logic                                    ctr_inc32_no,               
  output logic                                    ctr_incr_no,                
  input  logic                                    ctr_ready_ni,               
  input  logic                 [NumSlicesCtr-1:0] ctr_we_ni,                  
  output logic                                    cipher_in_valid_no,         
  input  logic                                    cipher_in_ready_ni,         
  input  logic                                    cipher_out_valid_ni,        
  output logic                                    cipher_out_ready_no,        
  output logic                                    cipher_crypt_no,            
  input  logic                                    cipher_crypt_ni,            
  output logic                                    cipher_dec_key_gen_no,      
  input  logic                                    cipher_dec_key_gen_ni,      
  output logic                                    cipher_prng_reseed_o,
  input  logic                                    cipher_prng_reseed_i,
  output logic                                    cipher_key_clear_o,
  input  logic                                    cipher_key_clear_i,
  output logic                                    cipher_data_out_clear_o,
  input  logic                                    cipher_data_out_clear_i,
  output logic                                    ghash_in_valid_no,          
  input  logic                                    ghash_in_ready_ni,          
  input  logic                                    ghash_out_valid_ni,         
  output logic                                    ghash_out_ready_no,         
  output logic                                    ghash_load_hash_subkey_no,  
  output key_init_sel_e                           key_init_sel_o,
  output logic [NumSharesKey-1:0][NumRegsKey-1:0] key_init_we_no,             
  output iv_sel_e                                 iv_sel_o,
  output logic                 [NumSlicesCtr-1:0] iv_we_no,                   
  output logic                                    prng_update_o,
  output logic                                    prng_reseed_req_o,
  input  logic                                    prng_reseed_ack_i,
  output logic                                    start_we_o,
  output logic                                    key_iv_data_in_clear_we_o,
  output logic                                    data_out_clear_we_o,
  output logic                                    prng_reseed_o,
  output logic                                    prng_reseed_we_o,
  output logic                                    idle_o,
  output logic                                    idle_we_o,
  output logic                                    stall_o,
  output logic                                    stall_we_o,
  input  logic                                    output_lost_i,
  output logic                                    output_lost_o,
  output logic                                    output_lost_we_o,
  output logic                                    output_valid_o,
  output logic                                    output_valid_we_o,
  output logic                                    input_ready_o,
  output logic                                    input_ready_we_o
);
  localparam int NumInBufBits = $bits({
    ctrl_qe_i,
    ctrl_phase_i,
    ctrl_err_storage_i,
    op_i,
    mode_i,
    cipher_op_i,
    sideload_i,
    prng_reseed_rate_i,
    manual_operation_i,
    key_touch_forces_reseed_i,
    ctrl_gcm_qe_i,
    ctrl_gcm_phase_i,
    gcm_phase_i,
    start_i,
    key_iv_data_in_clear_i,
    data_out_clear_i,
    prng_reseed_i,
    mux_sel_err_i,
    sp_enc_err_i,
    lc_escalate_en_i,
    alert_fatal_i,
    key_sideload_valid_i,
    key_init_qe_i,
    iv_qe_i,
    data_in_qe_i,
    data_out_re_i,
    ctr_ready_ni,
    ctr_we_ni,
    cipher_in_ready_ni,
    cipher_out_valid_ni,
    cipher_crypt_ni,
    cipher_dec_key_gen_ni,
    cipher_prng_reseed_i,
    cipher_key_clear_i,
    cipher_data_out_clear_i,
    ghash_in_ready_ni,
    ghash_out_valid_ni,
    prng_reseed_ack_i,
    output_lost_i
  });
  logic [NumInBufBits-1:0] in, in_buf;
  assign in = {
    ctrl_qe_i,
    ctrl_phase_i,
    ctrl_err_storage_i,
    op_i,
    mode_i,
    cipher_op_i,
    sideload_i,
    prng_reseed_rate_i,
    manual_operation_i,
    key_touch_forces_reseed_i,
    ctrl_gcm_qe_i,
    ctrl_gcm_phase_i,
    gcm_phase_i,
    start_i,
    key_iv_data_in_clear_i,
    data_out_clear_i,
    prng_reseed_i,
    mux_sel_err_i,
    sp_enc_err_i,
    lc_escalate_en_i,
    alert_fatal_i,
    key_sideload_valid_i,
    key_init_qe_i,
    iv_qe_i,
    data_in_qe_i,
    data_out_re_i,
    ctr_ready_ni,
    ctr_we_ni,
    cipher_in_ready_ni,
    cipher_out_valid_ni,
    cipher_crypt_ni,
    cipher_dec_key_gen_ni,
    cipher_prng_reseed_i,
    cipher_key_clear_i,
    cipher_data_out_clear_i,
    ghash_in_ready_ni,
    ghash_out_valid_ni,
    prng_reseed_ack_i,
    output_lost_i
  };
  caliptra_prim_buf #(
    .Width(NumInBufBits)
  ) u_caliptra_prim_buf_in (
    .in_i(in),
    .out_o(in_buf)
  );
  logic                                    ctrl_qe;
  logic                                    ctrl_phase;
  logic                                    ctrl_err_storage;
  aes_op_e                                 op;
  aes_mode_e                               mode;
  ciph_op_e                                cipher_op;
  logic             [$bits(cipher_op)-1:0] cipher_op_raw;
  logic                                    sideload;
  prs_rate_e                               prng_reseed_rate;
  logic                                    manual_operation;
  logic                                    key_touch_forces_reseed;
  logic                                    ctrl_gcm_qe;
  logic                                    ctrl_gcm_phase;
  gcm_phase_e                              gcm_phase;
  logic             [$bits(gcm_phase)-1:0] gcm_phase_raw;
