    .err_o  ( data_in_prev_sel_err  )
  );
  assign data_in_prev_sel = dip_sel_e'(data_in_prev_sel_raw);
  aes_sel_buf_chk #(
    .Num      ( SISelNum   ),
    .Width    ( SISelWidth ),
    .EnSecBuf ( 1'b1       )
  ) u_aes_state_in_sel_buf_chk (
    .clk_i  ( clk_i             ),
    .rst_ni ( rst_ni            ),
    .sel_i  ( state_in_sel_ctrl ),
    .sel_o  ( state_in_sel_raw  ),
    .err_o  ( state_in_sel_err  )
  );
  assign state_in_sel = si_sel_e'(state_in_sel_raw);
  aes_sel_buf_chk #(
    .Num      ( AddSISelNum   ),
    .Width    ( AddSISelWidth ),
    .EnSecBuf ( 1'b1          )
  ) u_aes_add_state_in_sel_buf_chk (
    .clk_i  ( clk_i                 ),
    .rst_ni ( rst_ni                ),
    .sel_i  ( add_state_in_sel_ctrl ),
    .sel_o  ( add_state_in_sel_raw  ),
    .err_o  ( add_state_in_sel_err  )
  );
  assign add_state_in_sel = add_si_sel_e'(add_state_in_sel_raw);
  aes_sel_buf_chk #(
    .Num      ( AddSOSelNum   ),
    .Width    ( AddSOSelWidth ),
    .EnSecBuf ( 1'b1          )
  ) u_aes_add_state_out_sel_buf_chk (
    .clk_i  ( clk_i                  ),
    .rst_ni ( rst_ni                 ),
    .sel_i  ( add_state_out_sel_ctrl ),
    .sel_o  ( add_state_out_sel_raw  ),
    .err_o  ( add_state_out_sel_err  )
  );
  assign add_state_out_sel = add_so_sel_e'(add_state_out_sel_raw);
  aes_sel_buf_chk #(
    .Num      ( KeyInitSelNum   ),
    .Width    ( KeyInitSelWidth ),
    .EnSecBuf ( 1'b1            )
  ) u_aes_key_init_sel_buf_chk (
    .clk_i  ( clk_i             ),
    .rst_ni ( rst_ni            ),
    .sel_i  ( key_init_sel_ctrl ),
    .sel_o  ( key_init_sel_raw  ),
    .err_o  ( key_init_sel_err  )
  );
  assign key_init_sel = key_init_sel_e'(key_init_sel_raw);
  aes_sel_buf_chk #(
    .Num      ( IVSelNum   ),
    .Width    ( IVSelWidth ),
    .EnSecBuf ( 1'b1       )
  ) u_aes_iv_sel_buf_chk (
    .clk_i  ( clk_i       ),
    .rst_ni ( rst_ni      ),
    .sel_i  ( iv_sel_ctrl ),
    .sel_o  ( iv_sel_raw  ),
    .err_o  ( iv_sel_err  )
  );
  assign iv_sel = iv_sel_e'(iv_sel_raw);
  aes_sel_buf_chk #(
    .Num      ( DataOutSelNum   ),
    .Width    ( DataOutSelWidth ),
    .EnSecBuf ( 1'b1       )
  ) u_aes_data_out_sel_buf_chk (
    .clk_i  ( clk_i             ),
    .rst_ni ( rst_ni            ),
    .sel_i  ( data_out_sel_ctrl ),
    .sel_o  ( data_out_sel_raw  ),
    .err_o  ( data_out_sel_err  )
  );
  assign data_out_sel = data_out_sel_e'(data_out_sel_raw);
  assign mux_sel_err = data_in_prev_sel_err | state_in_sel_err | add_state_in_sel_err |
      add_state_out_sel_err | key_init_sel_err | iv_sel_err | data_out_sel_err;
  localparam int unsigned NumSp2VSig = NumSharesKey * NumRegsKey + NumSlicesCtr + 2;
  sp2v_e [NumSp2VSig-1:0]                sp2v_sig;
  sp2v_e [NumSp2VSig-1:0]                sp2v_sig_chk;
  logic  [NumSp2VSig-1:0][Sp2VWidth-1:0] sp2v_sig_chk_raw;
  logic  [NumSp2VSig-1:0]                sp2v_sig_err;
  for (genvar s = 0; s < NumSharesKey; s++) begin : gen_use_key_init_we_ctrl_shares
    for (genvar i = 0; i < NumRegsKey; i++) begin : gen_use_key_init_we_ctrl
      assign sp2v_sig[s * NumRegsKey + i] = key_init_we_ctrl[s][i];
    end
  end
  for (genvar i = 0; i < NumSlicesCtr; i++) begin : gen_use_iv_we_ctrl
    assign sp2v_sig[NumSharesKey * NumRegsKey + i] = iv_we_ctrl[i];
  end
  assign sp2v_sig[NumSharesKey * NumRegsKey + NumSlicesCtr + 0] = data_in_prev_we_ctrl;
  assign sp2v_sig[NumSharesKey * NumRegsKey + NumSlicesCtr + 1] = data_out_we_ctrl;
  localparam bit [NumSp2VSig-1:0] Sp2VEnSecBuf = {NumSp2VSig{1'b1}};
  for (genvar i = 0; i < NumSp2VSig; i++) begin : gen_sel_buf_chk
    aes_sel_buf_chk #(
      .Num      ( Sp2VNum         ),
      .Width    ( Sp2VWidth       ),
      .EnSecBuf ( Sp2VEnSecBuf[i] )
    ) u_aes_sp2v_sig_buf_chk_i (
      .clk_i  ( clk_i               ),
      .rst_ni ( rst_ni              ),
      .sel_i  ( sp2v_sig[i]         ),
      .sel_o  ( sp2v_sig_chk_raw[i] ),
      .err_o  ( sp2v_sig_err[i]     )
    );
    assign sp2v_sig_chk[i] = sp2v_e'(sp2v_sig_chk_raw[i]);
  end
  for (genvar s = 0; s < NumSharesKey; s++) begin : gen_key_init_we_shares
    for (genvar i = 0; i < NumRegsKey; i++) begin : gen_key_init_we
      assign key_init_we[s][i] = sp2v_sig_chk[s * NumRegsKey + i];
    end
  end
  for (genvar i = 0; i < NumSlicesCtr; i++) begin : gen_iv_we
    assign iv_we[i]      = sp2v_sig_chk[NumSharesKey * NumRegsKey + i];
  end
  assign data_in_prev_we = sp2v_sig_chk[NumSharesKey * NumRegsKey + NumSlicesCtr + 0];
  assign data_out_we     = sp2v_sig_chk[NumSharesKey * NumRegsKey + NumSlicesCtr + 1];
  assign sp_enc_err_d = |sp2v_sig_err;
  always_ff @(posedge clk_i or negedge rst_ni) begin : reg_sp_enc_err
    if (!rst_ni) begin
      sp_enc_err_q <= 1'b0;
    end else if (sp_enc_err_d) begin
      sp_enc_err_q <= 1'b1;
    end
  end
  always_ff @(posedge clk_i or negedge rst_ni) begin : data_out_reg
    if (!rst_ni) begin
      data_out_q <= '0;
    end else if (data_out_we == SP2V_HIGH) begin
      data_out_q <= data_out_d;
    end
  end
  always_comb begin : key_reg_put
    for (int i = 0; i < NumRegsKey; i++) begin
      hw2reg.key_share0[i].d = key_init_q[0][i];
      hw2reg.key_share1[i].d = key_init_q[1][i];
    end
  end
  always_comb begin : iv_reg_put
    for (int i = 0; i < NumRegsIv; i++) begin
      hw2reg.iv[i].d  = {iv_q[2 * i + 1], iv_q[2 * i]};
    end
  end
  always_comb begin : data_out_put
    for (int i = 0; i < NumRegsData; i++) begin
      hw2reg.data_out[i].d = data_out_q[i];
    end
  end
  assign clear_on_fatal = ClearStatusOnFatalAlert ? alert_fatal_o : 1'b0;
  assign ctrl_err_update = ctrl_reg_err_update | shadowed_update_err_i | ctrl_gcm_reg_err_update;
  assign alert_recov_o = ctrl_err_update;
  assign hw2reg.status.alert_recov_ctrl_update_err.d  = ctrl_err_update & ~clear_on_fatal;
  assign hw2reg.status.alert_recov_ctrl_update_err.de = ctrl_err_update | ctrl_we | clear_on_fatal;
  assign ctrl_err_storage_d =
      ctrl_reg_err_storage | shadowed_storage_err_i | ctrl_gcm_reg_err_storage;
  always_ff @(posedge clk_i or negedge rst_ni) begin : ctrl_err_storage_reg
    if (!rst_ni) begin
      ctrl_err_storage_q <= 1'b0;
    end else if (ctrl_err_storage_d) begin
      ctrl_err_storage_q <= 1'b1;
    end
  end
  assign ctrl_err_storage = ctrl_err_storage_d | ctrl_err_storage_q;
  assign alert_fatal_o = ctrl_err_storage |
                         ctr_alert        |
                         cipher_alert     |
                         ghash_alert      |
                         ctrl_alert       |
                         intg_err_alert_i;
  assign hw2reg.status.alert_fatal_fault.d  = alert_fatal_o;
  assign hw2reg.status.alert_fatal_fault.de = alert_fatal_o;
  logic unused_alert_signals;
  assign unused_alert_signals = ^reg2hw.alert_test;
  logic unused_idle;
  assign unused_idle = reg2hw.status.idle.q;
  localparam int AesCoreSecMaskingNonDefault = (SecMasking == 1) ? 1 : 2;          
  always_comb begin                                  
    logic unused_assert_static_lint_error;           
    unused_assert_static_lint_error = AesCoreSecMaskingNonDefault'(1'b1); 
  end
  logic [3:0][31:0] state_done_transposed, unused_state_done_transposed;
  if (!SecMasking) begin : gen_state_done_transposed_unmasked
    assign state_done_transposed = aes_transpose(state_done[0]);
  end else begin : gen_state_done_transposed_masked
    assign state_done_transposed = aes_transpose(state_done[0] ^ state_done[1]);
  end
  assign unused_state_done_transposed = state_done_transposed;
endmodule
module aes_ctr import aes_pkg::*;
(
  input  logic                                       clk_i,
  input  logic                                       rst_ni,
  input  sp2v_e                                      inc32_i,
  input  sp2v_e                                      incr_i,
  output sp2v_e                                      ready_o,
  output logic                                       alert_o,
  input  logic  [NumSlicesCtr-1:0][SliceSizeCtr-1:0] ctr_i,
  output logic  [NumSlicesCtr-1:0][SliceSizeCtr-1:0] ctr_o,
  output sp2v_e [NumSlicesCtr-1:0]                   ctr_we_o
);
  function automatic logic [15:0][7:0] aes_rev_order_byte(logic [15:0][7:0] in);
    logic [15:0][7:0] out;
    for (int i = 0; i < 16; i++) begin
      out[i] = in[15-i];
    end
    return out;
  endfunction
  function automatic sp2v_e [NumSlicesCtr-1:0] aes_rev_order_sp2v(sp2v_e [NumSlicesCtr-1:0] in);
    sp2v_e [NumSlicesCtr-1:0] out;
    for (int i = 0; i < NumSlicesCtr; i++) begin
      out[i] = in[NumSlicesCtr - 1 - i];
    end
    return out;
  endfunction
  logic                   [SliceIdxWidth-1:0] ctr_slice_idx;
  logic  [NumSlicesCtr-1:0][SliceSizeCtr-1:0] ctr_i_rev;  
  logic  [NumSlicesCtr-1:0][SliceSizeCtr-1:0] ctr_o_rev;  
  sp2v_e [NumSlicesCtr-1:0]                   ctr_we_o_rev;
  sp2v_e                                      ctr_we;
  logic                    [SliceSizeCtr-1:0] ctr_i_slice;
  logic                    [SliceSizeCtr-1:0] ctr_o_slice;
  sp2v_e                                      inc32;
  logic                                       inc32_err;
  sp2v_e                                      incr;
  logic                                       incr_err;
  logic                                       sp_enc_err;
  logic                                       mr_err;
  logic    [Sp2VWidth-1:0]                    sp_inc32;
  logic    [Sp2VWidth-1:0]                    sp_incr;
  logic    [Sp2VWidth-1:0]                    sp_ready;
  logic    [Sp2VWidth-1:0]                    sp_ctr_we;
  logic    [Sp2VWidth-1:0]                    mr_alert;
  logic    [Sp2VWidth-1:0][SliceIdxWidth-1:0] mr_ctr_slice_idx;
  logic    [Sp2VWidth-1:0] [SliceSizeCtr-1:0] mr_ctr_o_slice;
  assign ctr_i_rev = aes_rev_order_byte(ctr_i);
  logic [Sp2VWidth-1:0] inc32_raw;
  aes_sel_buf_chk #(
    .Num      ( Sp2VNum   ),
    .Width    ( Sp2VWidth ),
    .EnSecBuf ( 1'b0      )
  ) u_aes_inc32_buf_chk (
    .clk_i  ( clk_i    ),
    .rst_ni ( rst_ni   ),
    .sel_i  ( inc32_i   ),
    .sel_o  ( inc32_raw ),
    .err_o  ( inc32_err )
  );
  assign inc32 = sp2v_e'(inc32_raw);
  logic [Sp2VWidth-1:0] incr_raw;
  aes_sel_buf_chk #(
    .Num      ( Sp2VNum   ),
    .Width    ( Sp2VWidth ),
    .EnSecBuf ( 1'b0      )
  ) u_aes_incr_buf_chk (
    .clk_i  ( clk_i    ),
    .rst_ni ( rst_ni   ),
    .sel_i  ( incr_i   ),
    .sel_o  ( incr_raw ),
    .err_o  ( incr_err )
  );
  assign incr = sp2v_e'(incr_raw);
  assign sp_enc_err = inc32_err | incr_err;
  assign ctr_i_slice = ctr_i_rev[ctr_slice_idx];
  assign sp_inc32 = {inc32};
  assign sp_incr  = {incr};
  for (genvar i = 0; i < Sp2VWidth; i++) begin : gen_fsm
    if (SP2V_LOGIC_HIGH[i] == 1'b1) begin : gen_fsm_p
      aes_ctr_fsm_p u_aes_ctr_fsm_i (
        .clk_i           ( clk_i               ),
        .rst_ni          ( rst_ni              ),
        .inc32_i         ( sp_inc32[i]         ),  
        .incr_i          ( sp_incr[i]          ),  
        .ready_o         ( sp_ready[i]         ),  
        .sp_enc_err_i    ( sp_enc_err          ),
        .mr_err_i        ( mr_err              ),
        .alert_o         ( mr_alert[i]         ),  
        .ctr_slice_idx_o ( mr_ctr_slice_idx[i] ),  
        .ctr_slice_i     ( ctr_i_slice         ),
        .ctr_slice_o     ( mr_ctr_o_slice[i]   ),  
        .ctr_we_o        ( sp_ctr_we[i]        )   
      );
    end else begin : gen_fsm_n
      aes_ctr_fsm_n u_aes_ctr_fsm_i (
        .clk_i           ( clk_i               ),
        .rst_ni          ( rst_ni              ),
        .inc32_ni        ( sp_inc32[i]         ),  
        .incr_ni         ( sp_incr[i]          ),  
        .ready_no        ( sp_ready[i]         ),  
        .sp_enc_err_i    ( sp_enc_err          ),
        .mr_err_i        ( mr_err              ),
        .alert_o         ( mr_alert[i]         ),  
        .ctr_slice_idx_o ( mr_ctr_slice_idx[i] ),  
        .ctr_slice_i     ( ctr_i_slice         ),
        .ctr_slice_o     ( mr_ctr_o_slice[i]   ),  
        .ctr_we_no       ( sp_ctr_we[i]        )   
      );
    end
  end
  assign ready_o = sp2v_e'(sp_ready);
  assign ctr_we  = sp2v_e'(sp_ctr_we);
  assign alert_o = |mr_alert;
  always_comb begin : combine_sparse_signals
    ctr_slice_idx = '0;
    ctr_o_slice   = '0;
    mr_err        = 1'b0;
    for (int i = 0; i < Sp2VWidth; i++) begin
      ctr_slice_idx |= mr_ctr_slice_idx[i];
      ctr_o_slice   |= mr_ctr_o_slice[i];
    end
    for (int i = 0; i < Sp2VWidth; i++) begin
      if (ctr_slice_idx != mr_ctr_slice_idx[i] ||
          ctr_o_slice   != mr_ctr_o_slice[i]) begin
        mr_err = 1'b1;
      end
    end
  end
  always_comb begin
    ctr_o_rev                = ctr_i_rev;
    ctr_o_rev[ctr_slice_idx] = ctr_o_slice;
  end
  always_comb begin
    ctr_we_o_rev                = {NumSlicesCtr{SP2V_LOW}};
    ctr_we_o_rev[ctr_slice_idx] = ctr_we;
  end
  assign ctr_o    = aes_rev_order_byte(ctr_o_rev);
  assign ctr_we_o = aes_rev_order_sp2v(ctr_we_o_rev);
endmodule
module aes_ctr_fsm import aes_pkg::*;
(
  input  logic                     clk_i,
  input  logic                     rst_ni,
  input  logic                     inc32_i,     
  input  logic                     incr_i,      
  output logic                     ready_o,     
  input  logic                     sp_enc_err_i,
  input  logic                     mr_err_i,
  output logic                     alert_o,
  output logic [SliceIdxWidth-1:0] ctr_slice_idx_o,
  input  logic  [SliceSizeCtr-1:0] ctr_slice_i,
  output logic  [SliceSizeCtr-1:0] ctr_slice_o,
  output logic                     ctr_we_o     
);
  aes_ctr_e                 aes_ctr_ns, aes_ctr_cs;
  logic [SliceIdxWidth-1:0] ctr_slice_idx_d, ctr_slice_idx_q;
  logic [SliceIdxWidth-1:0] ctr_slice_idx_max;
  logic                     ctr_carry_d, ctr_carry_q;
  logic    [SliceSizeCtr:0] ctr_value;
  assign ctr_value   = ctr_slice_i + {{(SliceSizeCtr-1){1'b0}}, ctr_carry_q};
  assign ctr_slice_o = ctr_value[SliceSizeCtr-1:0];
  assign ctr_slice_idx_max = inc32_i ? SliceIdxWidth'(SliceIdxMaxInc32) : {SliceIdxWidth{1'b1}};
  always_comb begin : aes_ctr_fsm_comb
    ready_o         = 1'b0;
    ctr_we_o        = 1'b0;
    alert_o         = 1'b0;
    aes_ctr_ns      = aes_ctr_cs;
    ctr_slice_idx_d = ctr_slice_idx_q;
    ctr_carry_d     = ctr_carry_q;
    unique case (aes_ctr_cs)
      CTR_IDLE: begin
        ready_o = 1'b1;
        if (incr_i == 1'b1) begin
          ctr_slice_idx_d = '0;
          ctr_carry_d     = 1'b1;
          aes_ctr_ns      = CTR_INCR;
        end
      end
      CTR_INCR: begin
        ctr_slice_idx_d = ctr_slice_idx_q + SliceIdxWidth'(1);
        ctr_carry_d     = ctr_slice_idx_q >= ctr_slice_idx_max ? 1'b0 : ctr_value[SliceSizeCtr];
        ctr_we_o        = 1'b1;
        if (ctr_slice_idx_q == {SliceIdxWidth{1'b1}}) begin
          aes_ctr_ns = CTR_IDLE;
        end
      end
      CTR_ERROR: begin
        alert_o = 1'b1;
      end
      default: begin
        aes_ctr_ns = CTR_ERROR;
        alert_o = 1'b1;
      end
    endcase
    if (sp_enc_err_i || mr_err_i) begin
      aes_ctr_ns = CTR_ERROR;
    end
  end
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      ctr_slice_idx_q <= '0;
      ctr_carry_q     <= '0;
    end else begin
      ctr_slice_idx_q <= ctr_slice_idx_d;
      ctr_carry_q     <= ctr_carry_d;
    end
  end
    caliptra_prim_sparse_fsm_flop #(                  
      .StateEnumT(aes_ctr_e),                            
      .Width($bits(aes_ctr_e)),                          
      .ResetValue($bits(aes_ctr_e)'(CTR_IDLE)),          
      .EnableAlertTriggerSVA( 1)  
    ) u_state_regs (                                        
      .clk_i   (  clk_i   ),                           
      .rst_ni  (  rst_ni ),                           
      .state_i ( aes_ctr_ns     ),                           
      .state_o ( aes_ctr_cs     )                            
    );                                                
  assign ctr_slice_idx_o = ctr_slice_idx_q;
endmodule
module aes_ctr_fsm_n import aes_pkg::*;
(
  input  logic                     clk_i,
  input  logic                     rst_ni,
  input  logic                     inc32_ni,         
  input  logic                     incr_ni,          
  output logic                     ready_no,         
  input  logic                     sp_enc_err_i,
  input  logic                     mr_err_i,
  output logic                     alert_o,
  output logic [SliceIdxWidth-1:0] ctr_slice_idx_o,
  input  logic  [SliceSizeCtr-1:0] ctr_slice_i,
  output logic  [SliceSizeCtr-1:0] ctr_slice_o,
  output logic                     ctr_we_no         
);
  localparam int NumInBufBits = $bits({
    inc32_ni,
    incr_ni,
    sp_enc_err_i,
    mr_err_i,
    ctr_slice_i
  });
  logic [NumInBufBits-1:0] in, in_buf;
  assign in = {
    inc32_ni,
    incr_ni,
    sp_enc_err_i,
    mr_err_i,
    ctr_slice_i
  };
  caliptra_prim_buf #(
    .Width(NumInBufBits)
  ) u_caliptra_prim_buf_in (
    .in_i(in),
    .out_o(in_buf)
  );
  logic                    inc32_n;
  logic                    incr_n;
  logic                    sp_enc_err;
  logic                    mr_err;
  logic [SliceSizeCtr-1:0] ctr_i_slice;
  assign {inc32_n,
          incr_n,
          sp_enc_err,
          mr_err,
          ctr_i_slice} = in_buf;
  logic                     ready;
  logic                     alert;
  logic [SliceIdxWidth-1:0] ctr_slice_idx;
  logic  [SliceSizeCtr-1:0] ctr_o_slice;
  logic                     ctr_we;
  aes_ctr_fsm u_aes_ctr_fsm (
    .clk_i           ( clk_i         ),
    .rst_ni          ( rst_ni        ),
    .inc32_i         ( ~inc32_n      ),  
    .incr_i          ( ~incr_n       ),  
    .ready_o         ( ready         ),  
    .sp_enc_err_i    ( sp_enc_err    ),
    .mr_err_i        ( mr_err        ),
    .alert_o         ( alert         ),
    .ctr_slice_idx_o ( ctr_slice_idx ),
    .ctr_slice_i     ( ctr_i_slice   ),
    .ctr_slice_o     ( ctr_o_slice   ),
    .ctr_we_o        ( ctr_we        )   
  );
  localparam int NumOutBufBits = $bits({
    ready_no,
    alert_o,
    ctr_slice_idx_o,
    ctr_slice_o,
    ctr_we_no
  });
  logic [NumOutBufBits-1:0] out, out_buf;
  assign out = {
    ~ready,
    alert,
    ctr_slice_idx,
    ctr_o_slice,
    ~ctr_we
  };
  caliptra_prim_buf #(
    .Width(NumOutBufBits)
  ) u_caliptra_prim_buf_out (
    .in_i(out),
    .out_o(out_buf)
  );
  assign {ready_no,
          alert_o,
          ctr_slice_idx_o,
          ctr_slice_o,
          ctr_we_no} = out_buf;
endmodule
module aes_ctr_fsm_p import aes_pkg::*;
(
  input  logic                     clk_i,
  input  logic                     rst_ni,
  input  logic                     inc32_i,          
  input  logic                     incr_i,           
  output logic                     ready_o,          
  input  logic                     sp_enc_err_i,
  input  logic                     mr_err_i,
  output logic                     alert_o,
  output logic [SliceIdxWidth-1:0] ctr_slice_idx_o,
  input  logic  [SliceSizeCtr-1:0] ctr_slice_i,
  output logic  [SliceSizeCtr-1:0] ctr_slice_o,
  output logic                     ctr_we_o          
);
  localparam int NumInBufBits = $bits({
    inc32_i,
    incr_i,
    sp_enc_err_i,
    mr_err_i,
    ctr_slice_i
  });
  logic [NumInBufBits-1:0] in, in_buf;
  assign in = {
    inc32_i,
    incr_i,
    sp_enc_err_i,
    mr_err_i,
    ctr_slice_i
  };
  caliptra_prim_buf #(
    .Width(NumInBufBits)
  ) u_caliptra_prim_buf_in (
    .in_i(in),
    .out_o(in_buf)
  );
  logic                    inc32;
  logic                    incr;
  logic                    sp_enc_err;
  logic                    mr_err;
  logic [SliceSizeCtr-1:0] ctr_i_slice;
  assign {inc32,
          incr,
          sp_enc_err,
          mr_err,
          ctr_i_slice} = in_buf;
  logic                     ready;
  logic                     alert;
  logic [SliceIdxWidth-1:0] ctr_slice_idx;
  logic  [SliceSizeCtr-1:0] ctr_o_slice;
  logic                     ctr_we;
  aes_ctr_fsm u_aes_ctr_fsm (
    .clk_i           ( clk_i         ),
    .rst_ni          ( rst_ni        ),
    .inc32_i         ( inc32         ),
    .incr_i          ( incr          ),
    .ready_o         ( ready         ),
    .sp_enc_err_i    ( sp_enc_err    ),
    .mr_err_i        ( mr_err        ),
    .alert_o         ( alert         ),
    .ctr_slice_idx_o ( ctr_slice_idx ),
    .ctr_slice_i     ( ctr_i_slice   ),
    .ctr_slice_o     ( ctr_o_slice   ),
    .ctr_we_o        ( ctr_we        )
  );
  localparam int NumOutBufBits = $bits({
    ready_o,
    alert_o,
    ctr_slice_idx_o,
    ctr_slice_o,
    ctr_we_o
  });
  logic [NumOutBufBits-1:0] out, out_buf;
  assign out = {
    ready,
    alert,
    ctr_slice_idx,
    ctr_o_slice,
    ctr_we
  };
  caliptra_prim_buf #(
    .Width(NumOutBufBits)
  ) u_caliptra_prim_buf_out (
    .in_i(out),
    .out_o(out_buf)
  );
  assign {ready_o,
          alert_o,
          ctr_slice_idx_o,
          ctr_slice_o,
          ctr_we_o} = out_buf;
endmodule
module aes_ctrl_gcm_reg_shadowed
  import aes_pkg::*;
  import aes_reg_pkg::*;
#(
  parameter bit AESGCMEnable = 1
) (
  input  logic clk_i,
  input  logic rst_ni,
  input  logic rst_shadowed_ni,
  output logic       qe_o,  
  input  logic       we_i,  
  output logic       phase_o,
  input  logic       init_done_i,
  input  logic       first_block_i,
  output gcm_phase_e gcm_phase_o,
  output logic [4:0] num_valid_bytes_o,
  output logic err_update_o,
  output logic err_storage_o,
  input  aes_reg2hw_ctrl_gcm_shadowed_reg_t reg2hw_ctrl_gcm_i,
  output aes_hw2reg_ctrl_gcm_shadowed_reg_t hw2reg_ctrl_gcm_o
);
  logic phase_gcm_phase;
  logic phase_num_valid_bytes;
  logic err_update_gcm_phase;
  logic err_update_num_valid_bytes;
  logic err_storage_gcm_phase;
  logic err_storage_num_valid_bytes;
  assign qe_o = reg2hw_ctrl_gcm_i.phase.qe & reg2hw_ctrl_gcm_i.num_valid_bytes.qe;
  if (AESGCMEnable) begin : gen_ctrl_gcm_reg_shadowed
    ctrl_gcm_reg_t ctrl_gcm_wd;
    gcm_phase_e    gcm_phase_reg_if, gcm_phase;
    logic [4:0]    num_valid_bytes;
    assign gcm_phase_reg_if = gcm_phase_e'(reg2hw_ctrl_gcm_i.phase.q);
    always_comb begin : gcm_phase_get
      unique case (gcm_phase_reg_if)
        GCM_INIT:    gcm_phase = GCM_INIT;
        GCM_RESTORE: gcm_phase = GCM_RESTORE;
        GCM_AAD:     gcm_phase = GCM_AAD;
        GCM_TEXT:    gcm_phase = GCM_TEXT;
        GCM_SAVE:    gcm_phase = GCM_SAVE;
        GCM_TAG:     gcm_phase = GCM_TAG;
        default:     gcm_phase = GCM_INIT;  
      endcase
      unique case (gcm_phase_o)
        GCM_INIT: begin
          gcm_phase = init_done_i &&
              (gcm_phase == GCM_RESTORE ||
               gcm_phase == GCM_AAD     ||
               gcm_phase == GCM_TEXT    ||
               gcm_phase == GCM_TAG)    ? gcm_phase : gcm_phase_o;
        end
        GCM_RESTORE: begin
          gcm_phase = gcm_phase == GCM_INIT ||
                      gcm_phase == GCM_AAD  ||
                      gcm_phase == GCM_TEXT ? gcm_phase : gcm_phase_o;
        end
        GCM_AAD: begin
          gcm_phase = gcm_phase == GCM_INIT                   ||
                      gcm_phase == GCM_TEXT                   ||
                      gcm_phase == GCM_SAVE && !first_block_i ||
                      gcm_phase == GCM_TAG                    ? gcm_phase : gcm_phase_o;
        end
        GCM_TEXT: begin
          gcm_phase = gcm_phase == GCM_INIT                   ||
                      gcm_phase == GCM_SAVE && !first_block_i ||
                      gcm_phase == GCM_TAG                    ? gcm_phase : gcm_phase_o;
        end
        GCM_SAVE: begin
          gcm_phase = gcm_phase == GCM_INIT ? gcm_phase : gcm_phase_o;
        end
        GCM_TAG: begin
          gcm_phase = gcm_phase == GCM_INIT ? gcm_phase : gcm_phase_o;
        end
        default: begin
          gcm_phase = gcm_phase_o;  
        end
      endcase
    end
    assign ctrl_gcm_wd.phase = gcm_phase;
    assign num_valid_bytes = reg2hw_ctrl_gcm_i.num_valid_bytes.q;
    assign ctrl_gcm_wd.num_valid_bytes =
        ((num_valid_bytes == 5'd0) || (num_valid_bytes > 5'd16)) ? 5'd16 : num_valid_bytes;
    caliptra_prim_subreg_shadow #(
      .DW      ($bits(gcm_phase_e)),
      .SwAccess(caliptra_prim_subreg_pkg::SwAccessWO),
      .RESVAL  (AES_CTRL_GCM_SHADOWED_PHASE_RESVAL)
    ) u_ctrl_gcm_reg_shadowed_phase (
      .clk_i,
      .rst_ni,
      .rst_shadowed_ni,
      .re         (reg2hw_ctrl_gcm_i.phase.re),
      .we         (we_i),
      .wd         ({ctrl_gcm_wd.phase}),
      .de         (1'b0),
      .d          ('0),
      .qe         (),
      .q          (hw2reg_ctrl_gcm_o.phase.d),
      .qs         (),
      .ds         (),
      .phase      (phase_gcm_phase),
      .err_update (err_update_gcm_phase),
      .err_storage(err_storage_gcm_phase)
    );
    caliptra_prim_subreg_shadow #(
      .DW      (5),
      .SwAccess(caliptra_prim_subreg_pkg::SwAccessWO),
      .RESVAL  (AES_CTRL_GCM_SHADOWED_NUM_VALID_BYTES_RESVAL)
    ) u_ctrl_gcm_reg_shadowed_num_valid_bytes (
      .clk_i,
      .rst_ni,
      .rst_shadowed_ni,
      .re         (reg2hw_ctrl_gcm_i.num_valid_bytes.re),
      .we         (we_i),
      .wd         ({ctrl_gcm_wd.num_valid_bytes}),
      .de         (1'b0),
      .d          ('0),
      .qe         (),
      .q          (hw2reg_ctrl_gcm_o.num_valid_bytes.d),
      .qs         (),
      .ds         (),
      .phase      (phase_num_valid_bytes),
      .err_update (err_update_num_valid_bytes),
      .err_storage(err_storage_num_valid_bytes)
    );
  end else begin : gen_no_ctrl_gcm_reg_shadowed
    logic unused_ctrl_gcm;
    assign unused_ctrl_gcm = ^{reg2hw_ctrl_gcm_i.phase.re,
                               reg2hw_ctrl_gcm_i.phase.q,
                               reg2hw_ctrl_gcm_i.num_valid_bytes.re,
                               reg2hw_ctrl_gcm_i.num_valid_bytes.q};
    logic unused_we;
    logic unused_init_done;
    logic unused_first_block;
    assign unused_we = we_i;
    assign unused_init_done = init_done_i;
    assign unused_first_block = first_block_i;
    logic unused_clk;
    logic unused_rst;
    logic unused_rst_shadowed;
    assign unused_clk = clk_i;
    assign unused_rst = rst_ni;
    assign unused_rst_shadowed = rst_shadowed_ni;
    assign hw2reg_ctrl_gcm_o.phase.d           = {GCM_INIT};
    assign hw2reg_ctrl_gcm_o.num_valid_bytes.d = 5'd16;
    assign phase_gcm_phase                     = 1'b1;
    assign phase_num_valid_bytes               = 1'b1;
    assign err_update_gcm_phase        = 1'b0;
    assign err_update_num_valid_bytes  = 1'b0;
    assign err_storage_gcm_phase       = 1'b0;
    assign err_storage_num_valid_bytes = 1'b0;
  end
  assign phase_o = phase_gcm_phase | phase_num_valid_bytes;
  assign err_update_o = err_update_gcm_phase | err_update_num_valid_bytes;
  assign err_storage_o = err_storage_gcm_phase | err_storage_num_valid_bytes;
  assign gcm_phase_o       = gcm_phase_e'(hw2reg_ctrl_gcm_o.phase.d);
  assign num_valid_bytes_o = hw2reg_ctrl_gcm_o.num_valid_bytes.d;
endmodule
module aes_ctrl_reg_shadowed
  import aes_pkg::*;
  import aes_reg_pkg::*;
#(
  parameter bit AES192Enable = 1,
  parameter bit AESGCMEnable = 1
) (
  input  logic clk_i,
  input  logic rst_ni,
  input  logic rst_shadowed_ni,
  output logic      qe_o,  
  input  logic      we_i,  
  output logic      phase_o,
  output aes_op_e   operation_o,
  output aes_mode_e mode_o,
  output key_len_e  key_len_o,
  output logic      sideload_o,
  output prs_rate_e prng_reseed_rate_o,
  output logic      manual_operation_o,
  output logic err_update_o,
  output logic err_storage_o,
  input  aes_reg2hw_ctrl_shadowed_reg_t reg2hw_ctrl_i,
  output aes_hw2reg_ctrl_shadowed_reg_t hw2reg_ctrl_o
);
  ctrl_reg_t ctrl_wd;
  aes_op_e   op;
  aes_mode_e mode;
  key_len_e  key_len;
  prs_rate_e prng_reseed_rate;
  logic      phase_operation;
  logic      phase_mode;
  logic      phase_key_len;
  logic      phase_key_sideload;
  logic      phase_prng_reseed_rate;
  logic      phase_manual_operation;
  logic      err_update_operation;
  logic      err_update_mode;
  logic      err_update_key_len;
  logic      err_update_sideload;
  logic      err_update_prng_reseed_rate;
  logic      err_update_manual_operation;
  logic      err_storage_operation;
  logic      err_storage_mode;
  logic      err_storage_key_len;
  logic      err_storage_sideload;
  logic      err_storage_prng_reseed_rate;
  logic      err_storage_manual_operation;
  assign qe_o = reg2hw_ctrl_i.operation.qe & reg2hw_ctrl_i.mode.qe &
      reg2hw_ctrl_i.key_len.qe & reg2hw_ctrl_i.sideload.qe &
      reg2hw_ctrl_i.prng_reseed_rate.qe & reg2hw_ctrl_i.manual_operation.qe;
  assign op = aes_op_e'(reg2hw_ctrl_i.operation.q);
  always_comb begin : operation_get
    unique case (op)
      AES_ENC: ctrl_wd.operation = AES_ENC;
      AES_DEC: ctrl_wd.operation = AES_DEC;
      default: ctrl_wd.operation = AES_ENC;  
    endcase
  end
  assign mode = aes_mode_e'(reg2hw_ctrl_i.mode.q);
  always_comb begin : mode_get
    unique case (mode)
      AES_ECB: ctrl_wd.mode = AES_ECB;
      AES_CBC: ctrl_wd.mode = AES_CBC;
      AES_CFB: ctrl_wd.mode = AES_CFB;
      AES_OFB: ctrl_wd.mode = AES_OFB;
      AES_CTR: ctrl_wd.mode = AES_CTR;
      AES_GCM: ctrl_wd.mode = AESGCMEnable ? AES_GCM : AES_NONE;
      default: ctrl_wd.mode = AES_NONE;  
    endcase
  end
  assign key_len = key_len_e'(reg2hw_ctrl_i.key_len.q);
  always_comb begin : key_len_get
    unique case (key_len)
      AES_128: ctrl_wd.key_len = AES_128;
      AES_256: ctrl_wd.key_len = AES_256;
      AES_192: ctrl_wd.key_len = AES192Enable ? AES_192 : AES_256;
      default: ctrl_wd.key_len = AES_256;  
    endcase
  end
  assign ctrl_wd.sideload = reg2hw_ctrl_i.sideload.q;
  assign prng_reseed_rate = prs_rate_e'(reg2hw_ctrl_i.prng_reseed_rate.q);
  always_comb begin : prng_reseed_rate_get
    unique case (prng_reseed_rate)
      PER_1:   ctrl_wd.prng_reseed_rate = PER_1;
      PER_64:  ctrl_wd.prng_reseed_rate = PER_64;
      PER_8K:  ctrl_wd.prng_reseed_rate = PER_8K;
      default: ctrl_wd.prng_reseed_rate = PER_1;  
    endcase
  end
  assign ctrl_wd.manual_operation = reg2hw_ctrl_i.manual_operation.q;
  caliptra_prim_subreg_shadow #(
    .DW      ($bits(aes_op_e)),
    .SwAccess(caliptra_prim_subreg_pkg::SwAccessWO),
    .RESVAL  (AES_CTRL_SHADOWED_OPERATION_RESVAL)
  ) u_ctrl_reg_shadowed_operation (
    .clk_i,
    .rst_ni,
    .rst_shadowed_ni,
    .re         (reg2hw_ctrl_i.operation.re),
    .we         (we_i),
    .wd         ({ctrl_wd.operation}),
    .de         (1'b0),
    .d          ('0),
    .qe         (),
    .q          (hw2reg_ctrl_o.operation.d),
    .qs         (),
    .ds         (),
    .phase      (phase_operation),
    .err_update (err_update_operation),
    .err_storage(err_storage_operation)
  );
  caliptra_prim_subreg_shadow #(
    .DW      ($bits(aes_mode_e)),
    .SwAccess(caliptra_prim_subreg_pkg::SwAccessWO),
    .RESVAL  (AES_CTRL_SHADOWED_MODE_RESVAL)
  ) u_ctrl_reg_shadowed_mode (
    .clk_i,
    .rst_ni,
    .rst_shadowed_ni,
    .re         (reg2hw_ctrl_i.mode.re),
    .we         (we_i),
    .wd         ({ctrl_wd.mode}),
    .de         (1'b0),
    .d          ('0),
    .qe         (),
    .q          (hw2reg_ctrl_o.mode.d),
    .qs         (),
    .ds         (),
    .phase      (phase_mode),
    .err_update (err_update_mode),
    .err_storage(err_storage_mode)
  );
  caliptra_prim_subreg_shadow #(
    .DW      ($bits(key_len_e)),
    .SwAccess(caliptra_prim_subreg_pkg::SwAccessWO),
    .RESVAL  (AES_CTRL_SHADOWED_KEY_LEN_RESVAL)
  ) u_ctrl_reg_shadowed_key_len (
    .clk_i,
    .rst_ni,
    .rst_shadowed_ni,
    .re         (reg2hw_ctrl_i.key_len.re),
    .we         (we_i),
    .wd         ({ctrl_wd.key_len}),
    .de         (1'b0),
    .d          ('0),
    .qe         (),
    .q          (hw2reg_ctrl_o.key_len.d),
    .qs         (),
    .ds         (),
    .phase      (phase_key_len),
    .err_update (err_update_key_len),
    .err_storage(err_storage_key_len)
  );
  caliptra_prim_subreg_shadow #(
    .DW      (1),
    .SwAccess(caliptra_prim_subreg_pkg::SwAccessWO),
    .RESVAL  (AES_CTRL_SHADOWED_SIDELOAD_RESVAL)
  ) u_ctrl_reg_shadowed_sideload (
    .clk_i,
    .rst_ni,
    .rst_shadowed_ni,
    .re         (reg2hw_ctrl_i.sideload.re),
    .we         (we_i),
    .wd         (ctrl_wd.sideload),
    .de         (1'b0),
    .d          ('0),
    .qe         (),
    .q          (hw2reg_ctrl_o.sideload.d),
    .qs         (),
    .ds         (),
    .phase      (phase_key_sideload),
    .err_update (err_update_sideload),
    .err_storage(err_storage_sideload)
  );
  caliptra_prim_subreg_shadow #(
    .DW      ($bits(prs_rate_e)),
    .SwAccess(caliptra_prim_subreg_pkg::SwAccessWO),
    .RESVAL  (AES_CTRL_SHADOWED_PRNG_RESEED_RATE_RESVAL)
  ) u_ctrl_reg_shadowed_prng_reseed_rate (
    .clk_i,
    .rst_ni,
    .rst_shadowed_ni,
    .re         (reg2hw_ctrl_i.prng_reseed_rate.re),
    .we         (we_i),
    .wd         ({ctrl_wd.prng_reseed_rate}),
    .de         (1'b0),
    .d          ('0),
    .qe         (),
    .q          (hw2reg_ctrl_o.prng_reseed_rate.d),
    .qs         (),
    .ds         (),
    .phase      (phase_prng_reseed_rate),
    .err_update (err_update_prng_reseed_rate),
    .err_storage(err_storage_prng_reseed_rate)
  );
  caliptra_prim_subreg_shadow #(
    .DW      (1),
    .SwAccess(caliptra_prim_subreg_pkg::SwAccessWO),
    .RESVAL  (AES_CTRL_SHADOWED_MANUAL_OPERATION_RESVAL)
  ) u_ctrl_reg_shadowed_manual_operation (
    .clk_i,
    .rst_ni,
    .rst_shadowed_ni,
    .re         (reg2hw_ctrl_i.manual_operation.re),
    .we         (we_i),
    .wd         (ctrl_wd.manual_operation),
    .de         (1'b0),
    .d          ('0),
    .qe         (),
    .q          (hw2reg_ctrl_o.manual_operation.d),
    .qs         (),
    .ds         (),
    .phase      (phase_manual_operation),
    .err_update (err_update_manual_operation),
    .err_storage(err_storage_manual_operation)
  );
  assign phase_o = phase_operation | phase_mode | phase_key_len | phase_key_sideload |
      phase_prng_reseed_rate | phase_manual_operation;
  assign err_update_o = err_update_operation | err_update_mode | err_update_key_len |
      err_update_sideload | err_update_prng_reseed_rate | err_update_manual_operation;
  assign err_storage_o = err_storage_operation | err_storage_mode | err_storage_key_len |
      err_storage_sideload | err_storage_prng_reseed_rate | err_storage_manual_operation;
  assign operation_o        = aes_op_e'(hw2reg_ctrl_o.operation.d);
  assign mode_o             = aes_mode_e'(hw2reg_ctrl_o.mode.d);
  assign key_len_o          = key_len_e'(hw2reg_ctrl_o.key_len.d);
  assign sideload_o         = hw2reg_ctrl_o.sideload.d;
  assign prng_reseed_rate_o = prs_rate_e'(hw2reg_ctrl_o.prng_reseed_rate.d);
  assign manual_operation_o = hw2reg_ctrl_o.manual_operation.d;
endmodule
module aes_ghash
  import aes_pkg::*;
  import aes_reg_pkg::*;
#(
  parameter bit          SecMasking   = 1,
  parameter int unsigned GFMultCycles = 32,
  localparam int         NumShares    = SecMasking ? 2 : 1  
) (
  input  logic                         clk_i,
  input  logic                         rst_ni,
  input  sp2v_e                        in_valid_i,
  output sp2v_e                        in_ready_o,
  output sp2v_e                        out_valid_o,
  input  sp2v_e                        out_ready_i,
  input  aes_op_e                      op_i,
  input  gcm_phase_e                   gcm_phase_i,
  input  logic [4:0]                   num_valid_bytes_i,
  input  sp2v_e                        load_hash_subkey_i,
  input  logic                         clear_i,
  output logic                         first_block_o,
  input  logic                         alert_fatal_i,
  output logic                         alert_o,
  input  logic         [GCMDegree-1:0] data_in_prev_i,                   
  input  logic [NumRegsData-1:0][31:0] data_out_i,                       
  input  logic         [3:0][3:0][7:0] cipher_state_done_i [NumShares],  
  output logic [NumRegsData-1:0][31:0] ghash_state_done_o
);
  localparam int GFMultStagesPerCycle = GCMDegree / GFMultCycles;
  logic [GCMDegree-1:0] s_d;
  logic [GCMDegree-1:0] s_q;
  sp2v_e                s_we;
  logic [GCMDegree-1:0] corr_d [2];
  logic [GCMDegree-1:0] corr_q [2];
  sp2v_e                corr_we;
  logic                 corr0_en_d;
  logic                 corr0_en_q;
  logic [15:0][7:0]     ghash_in;
  logic [15:0][7:0]     ghash_in_valid;
  ghash_in_sel_e        ghash_in_sel;
  ghash_add_in_sel_e    ghash_add_in_sel_d [2];
  ghash_add_in_sel_e    ghash_add_in_sel_q [2];
  logic [1:0]           ghash_add_in_sel_err;
  logic [GCMDegree-1:0] ghash_state_d [NumShares];
  logic [GCMDegree-1:0] ghash_state_q [NumShares];
  logic [GCMDegree-1:0] add_s_in;
  logic                 add_s_en_d;
  logic                 add_s_en_q;
  logic [GCMDegree-1:0] ghash_state_done;
  logic [GCMDegree-1:0] ghash_state_add [NumShares];
  sp2v_e                ghash_state_we [2];
  ghash_state_sel_e     ghash_state_sel;
  logic [GCMDegree-1:0] ghash_state_mult [NumShares];
  logic [GCMDegree-1:0] hash_subkey_d [NumShares];
  logic [GCMDegree-1:0] hash_subkey_q [NumShares];
  sp2v_e                hash_subkey_we;
  logic                 gf_mult0_en_d;
  logic                 gf_mult0_en_q;
  gf_mult_in_sel_e      gf_mult1_in_sel_d;
  gf_mult_in_sel_e      gf_mult1_in_sel_q;
  logic                 gf_mult1_in_sel_err;
  logic [1:0]           gf_mult_req;
  logic [1:0]           gf_mult_ack;
  logic [1:0]           gf_mult_ack_pre;
  aes_ghash_e           aes_ghash_ns, aes_ghash_cs;
  logic                 first_block_d;
  logic                 first_block_q;
  logic                 final_add_d;
  logic                 final_add_q;
  logic                 advance;
  logic [GCMDegree-1:0] cipher_state_done [NumShares];
  logic [GCMDegree-1:0] data_in_prev;
  logic [GCMDegree-1:0] data_out;
  always_comb begin : data_in_conversion
    for (int s = 0; s < NumShares; s++) begin
      cipher_state_done[s] = aes_state_to_ghash_vec(cipher_state_done_i[s]);
    end
    data_in_prev = aes_state_to_ghash_vec(aes_transpose(data_in_prev_i));
    data_out     = aes_state_to_ghash_vec(aes_transpose(data_out_i));
  end
  if (SecMasking) begin : gen_s1
    assign s_d = cipher_state_done[1];
  end else begin : gen_s0
    assign s_d = cipher_state_done[0];
  end
  always_ff @(posedge clk_i or negedge rst_ni) begin : s_reg
    if (!rst_ni) begin
      s_q <= '0;
    end else if (s_we == SP2V_HIGH) begin
      s_q <= s_d;
    end
  end
  if (SecMasking) begin : gen_corr_terms
    caliptra_prim_flop #(
      .Width     (1),
      .ResetValue(1'b0)
    ) u_caliptra_prim_flop_corr0_en (
      .clk_i (clk_i),
      .rst_ni(rst_ni),
      .d_i(corr0_en_d),
      .q_o(corr0_en_q)
    );
    logic [GCMDegree-1:0] ghash_state0_blanked;
    caliptra_prim_blanker #(
      .Width(GCMDegree)
    ) u_caliptra_prim_blanker_corr0 (
      .in_i (ghash_state_q[0]),
      .en_i (corr0_en_q),
      .out_o(ghash_state0_blanked)
    );
    assign corr_d[0] = ghash_state_mult[0] ^ ghash_state0_blanked;
    assign corr_d[1] = ghash_state_mult[1];
    always_ff @(posedge clk_i or negedge rst_ni) begin : corr_reg
      if (!rst_ni) begin
        corr_q <= '{default: '0};
      end else if (corr_we == SP2V_HIGH) begin
        corr_q <= corr_d;
      end
    end
  end
  always_comb begin : ghash_in_mux
    unique case (ghash_in_sel)
      GHASH_IN_DATA_IN_PREV: ghash_in = data_in_prev;
      GHASH_IN_DATA_OUT:     ghash_in = data_out;
      default:               ghash_in = data_out;
    endcase
  end
  always_comb begin
    for (int unsigned i = 0; i < 16; i++) begin
      ghash_in_valid[15-i] = num_valid_bytes_i > i[4:0] ? ghash_in[15-i] : 8'b0;
    end
  end
  if (SecMasking) begin : gen_masked_add
    logic [GCMDegree-1:0] add_in [NumShares];
    logic [GHashAddInSelWidth-1:0] ghash_add_in_sel_q_raw [NumShares];
    logic          [GCMDegree-1:0] ghash_add_in_mux_in [NumShares][GHashAddInSelWidth];
    assign ghash_add_in_mux_in[0][0] = ghash_in_valid;
    assign ghash_add_in_mux_in[0][1] = corr_q[0];
    assign ghash_add_in_mux_in[0][2] = ghash_state_q[1];
    assign ghash_add_in_mux_in[1][0] = ghash_in_valid;
    assign ghash_add_in_mux_in[1][1] = corr_q[1];
    assign ghash_add_in_mux_in[1][2] = ghash_state_mult[1];
    for (genvar s = 0; s < NumShares; s++) begin : gen_add_in_muxes
      caliptra_prim_flop #(
        .Width     (GHashAddInSelWidth),
        .ResetValue({ADD_IN_GHASH_IN})
      ) u_caliptra_prim_flop_add_in_sel (
        .clk_i (clk_i),
        .rst_ni(rst_ni),
        .d_i({ghash_add_in_sel_d[s]}),
        .q_o(ghash_add_in_sel_q_raw[s])
      );
      assign ghash_add_in_sel_q[s] = ghash_add_in_sel_e'(ghash_add_in_sel_q_raw[s]);
      caliptra_prim_onehot_check #(
        .OneHotWidth(GHashAddInSelWidth),
        .AddrCheck  (1'b0),
        .StrictCheck(1'b0)
      ) u_caliptra_prim_onehot_check_add_in_sel (
        .clk_i (clk_i),
        .rst_ni(rst_ni),
        .oh_i  ({ghash_add_in_sel_q[s]}),
        .addr_i('0),
        .en_i  (1'b1),
        .err_o (ghash_add_in_sel_err[s])
      );
      caliptra_prim_onehot_mux #(
        .Width (GCMDegree),
        .Inputs(GHashAddInSelWidth)
      ) u_caliptra_prim_onehot_mux_add_in (
        .clk_i (clk_i),
        .rst_ni(rst_ni),
        .in_i (ghash_add_in_mux_in[s]),
        .sel_i(ghash_add_in_sel_q[s]),
        .out_o(add_in[s])
      );
    end
    for (genvar s = 0; s < NumShares; s++) begin : gen_state_add
      assign ghash_state_add[s] = ghash_state_q[s] ^ add_in[s];
    end
  end else begin : gen_unmasked_add
    assign ghash_state_add[0] = ghash_state_q[0] ^ ghash_in_valid;
  end
  if (SecMasking) begin : gen_ghash_state_mux_masked
    always_comb begin : ghash_state0_mux
      unique case (ghash_state_sel)
        GHASH_STATE_INIT:    ghash_state_d[0] = cipher_state_done[0];
        GHASH_STATE_RESTORE: ghash_state_d[0] = data_in_prev;
        GHASH_STATE_ADD:     ghash_state_d[0] = ghash_state_add[0];
        GHASH_STATE_MULT:    ghash_state_d[0] = ghash_state_mult[0];
        default:             ghash_state_d[0] = ghash_state_add[0];
      endcase
    end
    always_comb begin : ghash_state1_mux
      unique case (ghash_state_sel)
        GHASH_STATE_INIT:    ghash_state_d[1] = cipher_state_done[1];
        GHASH_STATE_ADD:     ghash_state_d[1] = ghash_state_add[1];
        GHASH_STATE_MULT:    ghash_state_d[1] = ghash_state_mult[1];
        default:             ghash_state_d[1] = ghash_state_add[1];
      endcase
    end
  end else begin : gen_ghash_state_mux_unmasked
    always_comb begin : ghash_state_mux
      unique case (ghash_state_sel)
        GHASH_STATE_RESTORE: ghash_state_d[0] = ghash_state_add[0];
        GHASH_STATE_INIT:    ghash_state_d[0] = cipher_state_done[0];
        GHASH_STATE_ADD:     ghash_state_d[0] = ghash_state_add[0];
        GHASH_STATE_ADD_S:   ghash_state_d[0] = ghash_state_done;
        GHASH_STATE_MULT:    ghash_state_d[0] = ghash_state_mult[0];
        default:             ghash_state_d[0] = ghash_state_add[0];
      endcase
    end
  end
  for (genvar s = 0; s < NumShares; s++) begin : gen_ghash_state_reg_shares
    always_ff @(posedge clk_i or negedge rst_ni) begin : ghash_state_reg
      if (!rst_ni) begin
        ghash_state_q[s] <= '0;
      end else if (ghash_state_we[s] == SP2V_HIGH) begin
        ghash_state_q[s] <= ghash_state_d[s];
      end
    end
  end
  assign hash_subkey_d = cipher_state_done;
  always_ff @(posedge clk_i or negedge rst_ni) begin : hash_subkey_reg
    if (!rst_ni) begin
      hash_subkey_q <= '{default: '0};
    end else if (hash_subkey_we == SP2V_HIGH) begin
      hash_subkey_q <= hash_subkey_d;
    end
  end
  logic [GCMDegree-1:0] gf_mult_op_b[NumShares];
  logic [GCMDegree-1:0] gf_mult_op_b_rev[NumShares];
  logic [GCMDegree-1:0] gf_mult_prod[NumShares];
  if (SecMasking) begin : gen_gf_mult0_blanker
    caliptra_prim_flop #(
      .Width     (1),
      .ResetValue(1'b0)
    ) u_caliptra_prim_flop_gf_mult0_en (
      .clk_i (clk_i),
      .rst_ni(rst_ni),
      .d_i(gf_mult0_en_d),
      .q_o(gf_mult0_en_q)
    );
    caliptra_prim_blanker #(
      .Width(GCMDegree)
    ) u_caliptra_prim_blanker_gf_mult0 (
      .in_i (ghash_state_q[0]),
      .en_i (gf_mult0_en_q),
      .out_o(gf_mult_op_b[0])
    );
  end else begin : gen_no_gf_mult0_blanker
    assign gf_mult_op_b[0] = ghash_state_q[0];
  end
  assign gf_mult_op_b_rev[0] = aes_ghash_reverse_bit_order(gf_mult_op_b[0]);
  if (SecMasking) begin : gen_gf_mult1_mux
    logic [GFMultInSelWidth-1:0] gf_mult1_in_sel_q_raw;
    logic        [GCMDegree-1:0] gf_mult1_op_b_mux_in [GFMultInSelWidth];
    caliptra_prim_flop #(
      .Width     (GFMultInSelWidth),
      .ResetValue({MULT_IN_ZERO})
    ) u_caliptra_prim_flop_gf_mult1_in_sel (
      .clk_i (clk_i),
      .rst_ni(rst_ni),
      .d_i({gf_mult1_in_sel_d}),
      .q_o(gf_mult1_in_sel_q_raw)
    );
    assign gf_mult1_in_sel_q = gf_mult_in_sel_e'(gf_mult1_in_sel_q_raw);
    caliptra_prim_onehot_check #(
      .OneHotWidth(GFMultInSelWidth),
      .AddrCheck  (1'b0),
      .StrictCheck(1'b0)
    ) u_caliptra_prim_onehot_check_gf_mult1_in_sel (
      .clk_i (clk_i),
      .rst_ni(rst_ni),
      .oh_i  ({gf_mult1_in_sel_q}),
      .addr_i('0),
      .en_i  (1'b1),
      .err_o (gf_mult1_in_sel_err)
    );
    assign gf_mult1_op_b_mux_in[0] = ghash_state_q[0];
    assign gf_mult1_op_b_mux_in[1] = ghash_state_q[1];
    assign gf_mult1_op_b_mux_in[2] = s_q;
    caliptra_prim_onehot_mux #(
      .Width (GCMDegree),
      .Inputs(GFMultInSelWidth)
    ) u_caliptra_prim_onehot_mux_gf_mult1_op_b (
      .clk_i (clk_i),
      .rst_ni(rst_ni),
      .in_i (gf_mult1_op_b_mux_in),
      .sel_i(gf_mult1_in_sel_q),
      .out_o(gf_mult_op_b[1])
    );
    logic [GCMDegree-1:0] gf_mult1_op_b_rev;
    assign gf_mult1_op_b_rev = aes_ghash_reverse_bit_order(gf_mult_op_b[1]);
    logic [GFMultStagesPerCycle-1:0] gf_mult1_op_b_rev_slice_d;
    logic [GFMultStagesPerCycle-1:0] gf_mult1_op_b_rev_slice_q;
    assign gf_mult1_op_b_rev_slice_d = gf_mult1_op_b_rev[GCMDegree-1 -: GFMultStagesPerCycle];
    always_ff @(posedge clk_i or negedge rst_ni) begin : gf_mult1_op_b_slice_reg
      if (!rst_ni) begin
        gf_mult1_op_b_rev_slice_q <= '0;
      end else begin
        gf_mult1_op_b_rev_slice_q <= gf_mult1_op_b_rev_slice_d;
      end
    end
    assign gf_mult_op_b_rev[1] =
        {gf_mult1_op_b_rev_slice_q, gf_mult1_op_b_rev[GCMDegree-GFMultStagesPerCycle-1:0]};
  end
  for (genvar s = 0; s < NumShares; s++) begin : gen_gf_mult
    caliptra_prim_gf_mult #(
      .Width             (GCMDegree),
      .StagesPerCycle    (GFMultStagesPerCycle),
      .IPoly             (GCMIPoly),
      .OutputZeroUntilAck(1'b1)
    ) u_gf_mult (
      .clk_i (clk_i),
      .rst_ni(rst_ni),
      .req_i(gf_mult_req[s]),
      .ack_o(gf_mult_ack[s]),
      .ack_pre_o(gf_mult_ack_pre[s]),
      .operand_a_i(aes_ghash_reverse_bit_order(hash_subkey_q[s])),  
      .operand_b_i(gf_mult_op_b_rev[s]),                            
      .prod_o(gf_mult_prod[s])
    );
    assign ghash_state_mult[s] = aes_ghash_reverse_bit_order(gf_mult_prod[s]);
  end
  if (!SecMasking) begin : gen_tie_offs
    logic [GCMDegree-1:0] unused_corr_q [2];
    sp2v_e                unused_corr_we;
    assign corr_d         = '{default: '0};
    assign corr_q         = corr_d;
    assign unused_corr_q  = corr_q;
    assign unused_corr_we = corr_we;
    logic unused_corr0_en_q;
    assign corr0_en_q        = corr0_en_d;
    assign unused_corr0_en_q = corr0_en_q;
    logic unused_ghash_add_in_sel_d;
    assign unused_ghash_add_in_sel_d = ^{{ghash_add_in_sel_d[0]}, {ghash_add_in_sel_d[1]}};
    assign ghash_add_in_sel_q        = '{default: ADD_IN_GHASH_IN};
    assign ghash_add_in_sel_err      = 2'b00;
    assign gf_mult1_in_sel_err       = 1'b0;
    sp2v_e unused_ghash_state_we;
    assign unused_ghash_state_we = ghash_state_we[1];
    logic unused_gf_mult_req;
    assign unused_gf_mult_req = gf_mult_req[1];
    assign gf_mult_ack[1]     = 1'b1;
    assign gf_mult_ack_pre[1] = 1'b1;
    logic unused_add_s_en_q;
    assign add_s_en_q        = add_s_en_d;
    assign unused_add_s_en_q = add_s_en_q;
  end
  always_comb begin : aes_ghash_fsm
    in_ready_o  = SP2V_LOW;
    out_valid_o = SP2V_LOW;
    s_we       = SP2V_LOW;
    corr_we    = SP2V_LOW;
    corr0_en_d = 1'b0;
    ghash_in_sel = GHASH_IN_DATA_OUT;
    ghash_add_in_sel_d = ghash_add_in_sel_q;
    ghash_state_sel   = GHASH_STATE_ADD;
    ghash_state_we[0] = SP2V_LOW;
    ghash_state_we[1] = SP2V_LOW;
    hash_subkey_we = SP2V_LOW;
    gf_mult_req       = '0;
    gf_mult0_en_d     = gf_mult0_en_q;
    gf_mult1_in_sel_d = gf_mult1_in_sel_q;
    add_s_en_d = 1'b0;
    aes_ghash_ns  = aes_ghash_cs;
    first_block_d = first_block_q;
    final_add_d   = final_add_q;
    advance       = 1'b0;
    alert_o = 1'b0;
