    if (|ghash_add_in_sel_err || gf_mult1_in_sel_err || alert_fatal_i) begin
      aes_ghash_ns = GHASH_ERROR;
    end
  end
    caliptra_prim_sparse_fsm_flop #(                  
      .StateEnumT(aes_ghash_e),                            
      .Width($bits(aes_ghash_e)),                          
      .ResetValue($bits(aes_ghash_e)'(GHASH_IDLE)),          
      .EnableAlertTriggerSVA( 1)  
    ) u_state_regs (                                        
      .clk_i   (  clk_i   ),                           
      .rst_ni  (  rst_ni ),                           
      .state_i ( aes_ghash_ns     ),                           
      .state_o ( aes_ghash_cs     )                            
    );                                                
  always_ff @(posedge clk_i or negedge rst_ni) begin : fsm_reg
    if (!rst_ni) begin
      first_block_q <= 1'b0;
    end else begin
      first_block_q <= first_block_d;
    end
  end
  if (SecMasking) begin : gen_fsm_reg_masked
    always_ff @(posedge clk_i or negedge rst_ni) begin : fsm_reg_masked
      if (!rst_ni) begin
        final_add_q <= 1'b0;
      end else begin
        final_add_q <= final_add_d;
      end
    end
  end else begin : gen_no_fsm_reg
    logic unused_final_add_d;
    assign final_add_q = 1'b0;
    assign unused_final_add_d = final_add_d;
    logic unused_gf_mult0_en_d;
    assign gf_mult0_en_q = 1'b0;
    assign unused_gf_mult0_en_d = gf_mult0_en_d;
    gf_mult_in_sel_e unused_gf_mult1_in_sel_d;
    assign gf_mult1_in_sel_q = MULT_IN_ZERO;
    assign unused_gf_mult1_in_sel_d = gf_mult1_in_sel_d;
    logic unused_advance;
    assign unused_advance = advance;
  end
  assign first_block_o = first_block_q;
  if (SecMasking) begin : gen_add_s_in_masked
    caliptra_prim_flop #(
      .Width     (1),
      .ResetValue(1'b0)
    ) u_caliptra_prim_flop_add_s_en (
      .clk_i (clk_i),
      .rst_ni(rst_ni),
      .d_i(add_s_en_d),
      .q_o(add_s_en_q)
    );
    caliptra_prim_blanker #(
      .Width(GCMDegree)
    ) u_caliptra_prim_blanker_add_s_in (
      .in_i (ghash_state_q[0]),
      .en_i (add_s_en_q),
      .out_o(add_s_in)
    );
  end else begin : gen_add_s_in_unmasked
    assign add_s_in = ghash_state_q[0];
  end
  assign ghash_state_done = s_q ^ add_s_in;
  always_comb begin : data_out_conversion
    ghash_state_done_o = aes_transpose(aes_state_to_ghash_vec(ghash_state_done));
  end
endmodule
module aes_prng_clearing import aes_pkg::*;
#(
  parameter int unsigned Width                = 64,  
  parameter int unsigned EntropyWidth         = edn_pkg::ENDPOINT_BUS_WIDTH,
  parameter bit          SecSkipPRNGReseeding = 0,   
  parameter clearing_lfsr_seed_t RndCnstLfsrSeed  = RndCnstClearingLfsrSeedDefault,
  parameter clearing_lfsr_perm_t RndCnstLfsrPerm  = RndCnstClearingLfsrPermDefault,
  parameter clearing_lfsr_perm_t RndCnstSharePerm = RndCnstClearingSharePermDefault
) (
  input  logic                    clk_i,
  input  logic                    rst_ni,
  input  logic                    data_update_i,
  output logic        [Width-1:0] data_o [NumSharesKey],
  input  logic                    reseed_req_i,
  output logic                    reseed_ack_o,
  output logic                    entropy_req_o,
  input  logic                    entropy_ack_i,
  input  logic [EntropyWidth-1:0] entropy_i
);
  logic             seed_valid;
  logic             seed_en;
  logic [Width-1:0] seed;
  logic             lfsr_en;
  logic [Width-1:0] lfsr_state;
  localparam int AesSecSkipPRNGReseedingNonDefault = (SecSkipPRNGReseeding == 0) ? 1 : 2;          
  always_comb begin                                  
    logic unused_assert_static_lint_error;           
    unused_assert_static_lint_error = AesSecSkipPRNGReseedingNonDefault'(1'b1); 
  end
  assign lfsr_en = data_update_i;
  assign seed_en = SecSkipPRNGReseeding ? 1'b0 : seed_valid;
  if (Width/2 == EntropyWidth) begin : gen_buffer
    logic [EntropyWidth-1:0] buffer_d, buffer_q;
    logic                    buffer_valid_d, buffer_valid_q;
    assign entropy_req_o = SecSkipPRNGReseeding ? 1'b0         : reseed_req_i;
    assign reseed_ack_o  = SecSkipPRNGReseeding ? reseed_req_i : seed_valid;
    assign buffer_valid_d = entropy_req_o && entropy_ack_i ? ~buffer_valid_q : buffer_valid_q;
    assign buffer_d = entropy_req_o && entropy_ack_i && !buffer_valid_q ? entropy_i : buffer_q;
    always_ff @(posedge clk_i or negedge rst_ni) begin : reg_buffer
      if (!rst_ni) begin
        buffer_q       <= '0;
        buffer_valid_q <= 1'b0;
      end else begin
        buffer_q       <= buffer_d;
        buffer_valid_q <= buffer_valid_d;
      end
    end
    assign seed       = {buffer_q, entropy_i};
    assign seed_valid = buffer_valid_q & entropy_req_o & entropy_ack_i;
  end else begin : gen_packer
    assign entropy_req_o = SecSkipPRNGReseeding ? 1'b0         : reseed_req_i & ~seed_valid;
    assign reseed_ack_o  = SecSkipPRNGReseeding ? reseed_req_i : seed_valid;
    caliptra_prim_packer_fifo #(
      .InW         ( EntropyWidth ),
      .OutW        ( Width        ),
      .ClearOnRead ( 1'b0         )
    ) u_caliptra_prim_packer_fifo (
      .clk_i    ( clk_i         ),
      .rst_ni   ( rst_ni        ),
      .clr_i    ( 1'b0          ),  
      .wvalid_i ( entropy_ack_i ),
      .wdata_i  ( entropy_i     ),
      .wready_o (               ),  
      .rvalid_o ( seed_valid    ),
      .rdata_o  ( seed          ),
      .rready_i ( 1'b1          ),  
      .depth_o  (               )   
    );
  end
  caliptra_prim_lfsr #(
    .LfsrType     ( "GAL_XOR"       ),
    .LfsrDw       ( Width           ),
    .StateOutDw   ( Width           ),
    .DefaultSeed  ( RndCnstLfsrSeed ),
    .StatePermEn  ( 1'b1            ),
    .StatePerm    ( RndCnstLfsrPerm ),
    .NonLinearOut ( 1'b1            )
  ) u_lfsr (
    .clk_i     ( clk_i      ),
    .rst_ni    ( rst_ni     ),
    .seed_en_i ( seed_en    ),
    .seed_i    ( seed       ),
    .lfsr_en_i ( lfsr_en    ),
    .entropy_i (         '0 ),
    .state_o   ( lfsr_state )
  );
  assign data_o[0] = lfsr_state;
  for (genvar i = 0; i < Width; i++) begin : gen_share_perm
    assign data_o[1][i] = lfsr_state[RndCnstSharePerm[i]];
  end
endmodule
module aes_reduced_round import aes_pkg::*;
#(
  parameter sbox_impl_e SecSBoxImpl = SBoxImplDom
) (
  input  logic                              clk_i,
  input  logic                              rst_ni,
  input  sp2v_e                             en_i,
  output sp2v_e                             out_req_o,
  input  sp2v_e                             out_ack_i,
  input  ciph_op_e                          op_i,
  input  logic              [3:0][3:0][7:0] data_i,
  input  logic              [3:0][3:0][7:0] mask_i,
  input  logic [3:0][3:0][WidthPRDSBox-1:0] prd_i,
  output logic              [3:0][3:0][7:0] data_o,
  output logic              [3:0][3:0][7:0] mask_o,
  output logic                              err_o
);
  localparam int NumShares = 2;
  logic [3:0][3:0][7:0] sub_bytes_out;
  logic [3:0][3:0][7:0] sb_out_mask;
  logic [3:0][3:0][7:0] shift_rows_in [NumShares];
  logic [3:0][3:0][7:0] shift_rows_out [NumShares];
  logic [3:0][3:0][7:0] mix_columns_out [NumShares];
  aes_sub_bytes #(
    .SecSBoxImpl ( SecSBoxImpl )
  ) u_aes_sub_bytes (
    .clk_i     ( clk_i             ),
    .rst_ni    ( rst_ni            ),
    .en_i      ( en_i              ),
    .out_req_o ( out_req_o         ),
    .out_ack_i ( out_ack_i         ),
    .op_i      ( op_i              ),
    .data_i    ( data_i            ),
    .mask_i    ( mask_i            ),
    .prd_i     ( prd_i             ),
    .data_o    ( sub_bytes_out     ),
    .mask_o    ( sb_out_mask       ),
    .err_o     ( err_o             )
  );
  for (genvar s = 0; s < NumShares; s++) begin : gen_shares_shift_mix
    if (s == 0) begin : gen_shift_in_data
      assign shift_rows_in[s] = sub_bytes_out;
    end else begin : gen_shift_in_mask
      assign shift_rows_in[s] = sb_out_mask;
    end
    aes_shift_rows u_aes_shift_rows (
      .op_i   ( op_i              ),
      .data_i ( shift_rows_in[s]  ),
      .data_o ( shift_rows_out[s] )
    );
    aes_mix_columns u_aes_mix_columns (
      .op_i   ( op_i               ),
      .data_i ( shift_rows_out[s]  ),
      .data_o ( mix_columns_out[s] )
    );
  end
  assign data_o = mix_columns_out[0];
  assign mask_o = mix_columns_out[1];
endmodule
module aes_reg_status #(
  parameter int Width = 1
) (
  input  logic             clk_i,
  input  logic             rst_ni,
  input  logic [Width-1:0] we_i,
  input  logic             use_i,
  input  logic             clear_i,
  input  logic             arm_i,
  output logic             new_o,
  output logic             new_pulse_o,
  output logic             clean_o
);
  logic [Width-1:0] we_d, we_q;
  logic             armed_d, armed_q;
  logic             all_written;
  logic             none_written;
  logic             new_d, new_q;
  logic             clean_d, clean_q;
  assign we_d    = (clear_i || use_i) ? '0   :
                   (armed_q && |we_i) ? we_i : (we_q | we_i);
  assign armed_d = (clear_i || use_i) ? 1'b0 :
                   (armed_q && |we_i) ? 1'b0 : armed_q | arm_i;
  always_ff @(posedge clk_i or negedge rst_ni) begin : reg_ops
    if (!rst_ni) begin
      we_q    <= '0;
      armed_q <= 1'b0;
    end else begin
      we_q    <= we_d;
      armed_q <= armed_d;
    end
  end
  assign all_written  =  &we_d;
  assign none_written = ~|we_d;
  assign new_d   = (clear_i || use_i) ? 1'b0 : all_written;
  assign clean_d =  clear_i      ? 1'b0    :
                    all_written  ? 1'b1    :
                    none_written ? clean_q : 1'b0;
  always_ff @(posedge clk_i or negedge rst_ni) begin : reg_status
    if (!rst_ni) begin
      new_q   <= 1'b0;
      clean_q <= 1'b0;
    end else begin
      new_q   <= new_d;
      clean_q <= clean_d;
    end
  end
  assign new_o       = new_q;
  assign new_pulse_o = new_d & ~new_q;
  assign clean_o     = clean_q;
endmodule
